// --- services' RPC listener thread (the SCM's ScmStartRpcServer io_thread). Runs in services' OWN
// pml4 (pi 3) at the SAME target VSpace VAs as WL_LISTENER (isolated per-VSpace); its executive-side
// env-scratch + stack-mirror must be DISTINCT. Unlike WL_LISTENER (suspended), this one RESUMES and
// its faults route into the main service loop keyed by SVC_LISTENER_BADGE (the N-threads multiplex).
pub const SVC_LISTENER_STACK_BASE: u64 = HOSTED_THREAD_STACK_BASE; // services VSpace (own pml4)
pub const SVC_LISTENER_STACK_FRAMES: u64 = 8;
pub const SVC_LISTENER_IPCBUF_VA: u64 = HOSTED_THREAD_IPCBUF_VA;
pub const SVC_LISTENER_TEB_VA: u64 = HOSTED_THREAD_TEB_VA;
pub const SVC_LISTENER_TRAMP_VA: u64 = HOSTED_THREAD_TRAMP_VA;
/// Executive scratch (3 pages) — distinct from WL_LISTENER (0x1072). FILEBUF PT.
pub const SVC_LISTENER_ENV_SCRATCH_VA: u64 = 0x0000_0100_1073_0000;
/// Executive-side stack mirror for services' listener (so its syscall out-params / arg reads route to
/// its OWN stack, not services' main-thread stack). Distinct 8-page window.
pub const SVC_LISTENER_STACK_MIRROR_VA: u64 = 0x0000_0100_1360_0000;
/// The fault-EP badge for services' RPC listener thread — the main loop maps it to (pi 3, listener),
/// switching ACTIVE_STACK_MIRROR to the listener's mirror. The N-threads-per-process sub-selection.
pub const SVC_LISTENER_BADGE: u64 = 7;
// --- lsass' LSA server thread(s) (StartAuthenticationPort / LsapRmServerThread, created by lsass'
// LsapInitDatabase via NtCreateThread). Runs in lsass' OWN pml4 (pi 4) at the SAME target VSpace VAs
// as the SM/SVC listeners (isolated per-VSpace); its executive-side env-scratch + stack-mirror must be
// DISTINCT. RESUMES + faults route into the main service loop keyed by LSASS_LISTENER_BADGE (the
// N-threads multiplex — the SERVICE-9 C-c pattern replicated for lsass).
pub const LSASS_LISTENER_STACK_BASE: u64 = HOSTED_THREAD_STACK_BASE; // lsass VSpace (own pml4)
pub const LSASS_LISTENER_STACK_FRAMES: u64 = 8;
pub const LSASS_LISTENER_IPCBUF_VA: u64 = HOSTED_THREAD_IPCBUF_VA;
pub const LSASS_LISTENER_TEB_VA: u64 = HOSTED_THREAD_TEB_VA;
pub const LSASS_LISTENER_TRAMP_VA: u64 = HOSTED_THREAD_TRAMP_VA;
/// Executive scratch (3 pages) — distinct from SVC_LISTENER (0x1073) / lsass-main env (0x1077). FILEBUF PT.
pub const LSASS_LISTENER_ENV_SCRATCH_VA: u64 = 0x0000_0100_1079_0000;
/// Executive-side stack mirror for lsass' listener (its syscall out-params / arg reads route to its OWN
/// stack, not lsass' main-thread stack). Distinct 8-page window (past SVC_LISTENER's 0x1360).
pub const LSASS_LISTENER_STACK_MIRROR_VA: u64 = 0x0000_0100_1368_0000;
/// The fault-EP badge for lsass' LSA server thread — the main loop maps it to (pi 4, listener),
/// switching ACTIVE_STACK_MIRROR to the listener's mirror. The N-threads-per-process sub-selection.
pub const LSASS_LISTENER_BADGE: u64 = 9;
// --- lsass' SECOND LSA server thread (LsapRmServerThread — lsass creates TWO server threads in
// LsapInitDatabase: StartAuthenticationPort then LsapRmServerThread). It runs in lsass' pml4 (pi 4) too,
// so it needs its OWN target-VSpace VAs (a distinct TEB → distinct GS base, distinct stack/tramp/ipcbuf)
// plus distinct executive-side env-scratch + stack-mirror. Same multiplex, badge LSASS_LISTENER2_BADGE.
pub const LSASS_LISTENER2_STACK_BASE: u64 = 0x0000_0100_104C_0000; // lsass VSpace (own pml4), 0x1040 PT
pub const LSASS_LISTENER2_STACK_FRAMES: u64 = 8;
pub const LSASS_LISTENER2_IPCBUF_VA: u64 = 0x0000_0100_104E_0000;
pub const LSASS_LISTENER2_TEB_VA: u64 = 0x0000_0100_104F_0000; // 2 pages
pub const LSASS_LISTENER2_TRAMP_VA: u64 = 0x0000_0100_1051_0000;
/// Executive scratch (3 pages) — distinct from LSASS_LISTENER (0x1079). FILEBUF PT.
pub const LSASS_LISTENER2_ENV_SCRATCH_VA: u64 = 0x0000_0100_107A_0000;
/// Executive-side stack mirror for lsass' 2nd server thread. Distinct 8-page window (past 0x1368).
pub const LSASS_LISTENER2_STACK_MIRROR_VA: u64 = 0x0000_0100_1370_0000;
/// The fault-EP badge for lsass' 2nd LSA server thread.
pub const LSASS_LISTENER2_BADGE: u64 = 10;
pub const LSASS_LISTENER3_STACK_BASE: u64 = WL_WORKER3_STACK_BASE;
pub const LSASS_LISTENER3_STACK_FRAMES: u64 = WL_WORKER3_STACK_FRAMES;
pub const LSASS_LISTENER3_IPCBUF_VA: u64 = WL_WORKER3_IPCBUF_VA;
pub const LSASS_LISTENER3_TEB_VA: u64 = WL_WORKER3_TEB_VA;
pub const LSASS_LISTENER3_TRAMP_VA: u64 = WL_WORKER3_TRAMP_VA;
pub const LSASS_LISTENER3_ENV_SCRATCH_VA: u64 = 0x0000_0100_107E_0000;
pub const LSASS_LISTENER3_STACK_MIRROR_VA: u64 = 0x0000_0100_1390_0000;
pub const LSASS_LISTENER3_BADGE: u64 = 14;

// --- Generic hosted same-process worker threads ----------------------------------------------
// The established SM/CSR/RPC roles retain their specialized layouts. An NtCreateThread whose
// target is the current process can use this generic high-lane layout at the same target VAs in
// each process (safe because every process has a distinct VSpace) and a per-pi mirror/scratch.
pub const TP_WORKER_PI_COUNT: usize = 5;
pub const TP_WORKER_LEGACY_SLOT_COUNT: usize = 2;
pub const TP_WORKER_SLOT_COUNT: usize = PM_RUNTIME_THREAD_SLOTS;
pub const TP_WORKER_BADGE_BASE: u64 = 16;
pub const TP_WORKER_AUX_BADGE_BASE: u64 = 0x200;
pub const TP_WORKER_EXEC_BASE: u64 = 0x0000_0100_13A0_0000;
pub const TP_WORKER_EXEC_STRIDE: u64 = 0x0004_0000;
pub const TP_WORKER_ENV_SCRATCH_OFFSET: u64 = 0x0002_0000;
pub const TP_WORKER_SLOT1_REGION_BASE: u64 = 0x0000_0100_13E0_0000;
pub const TP_WORKER_SLOT0_REGION_BASE: u64 = TP_WORKER_SLOT1_REGION_BASE - TP_WORKER_EXEC_STRIDE;
pub const TP_WORKER_STACK_BASE: u64 = TP_WORKER_SLOT0_REGION_BASE;
pub const TP_WORKER_STACK_FRAMES: u64 = 16;
pub const TP_WORKER_STACK_TOP: u64 = TP_WORKER_STACK_BASE + TP_WORKER_STACK_FRAMES * 0x1000;
pub const TP_WORKER_CONTEXT_RSP: u64 = ((TP_WORKER_STACK_TOP - 6 * 8) & !15) - 8;
pub const TP_WORKER_IPCBUF_VA: u64 = TP_WORKER_SLOT0_REGION_BASE + 0x1_0000;
pub const TP_WORKER_TEB_VA: u64 = TP_WORKER_SLOT0_REGION_BASE + 0x2_0000;
pub const TP_WORKER_TRAMP_VA: u64 = TP_WORKER_SLOT0_REGION_BASE + 0x3_0000;
pub const TP_WORKER_SLOT1_STACK_BASE: u64 = TP_WORKER_SLOT1_REGION_BASE;
pub const TP_WORKER_SLOT1_IPCBUF_VA: u64 = TP_WORKER_SLOT1_REGION_BASE + 0x1_0000;
pub const TP_WORKER_SLOT1_TEB_VA: u64 = TP_WORKER_SLOT1_REGION_BASE + 0x2_0000;
pub const TP_WORKER_SLOT1_TRAMP_VA: u64 = TP_WORKER_SLOT1_REGION_BASE + 0x3_0000;
pub const TP_WORKER_SLOT1_EXEC_BASE: u64 = 0x0000_0100_13C0_0000;
/// Executive-side windows for worker identities outside the legacy slot-0/slot-1, first-five-pi
/// layout. The two legacy `TP_WORKER_*_EXEC_BASE` regions are laid out as `base + pi * STRIDE` and
/// are only disjoint for `pi < TP_WORKER_PI_COUNT`; later hosted processes and extra worker slots get
/// densely-packed `(pi, slot)` regions here: a free high band between the file-buffer POOL
/// (`0x1500`+24*2 MiB = `0x1800`) and the hosted-driver execution arena. Legacy slots for
/// `pi < TP_WORKER_PI_COUNT` are byte-identical to before.
pub const TP_WORKER_AUX_EXEC_BASE: u64 = 0x0000_0100_1800_0000;

#[inline]
pub const fn tp_worker_aux_index(pi: usize, slot: usize) -> usize {
    if pi < TP_WORKER_PI_COUNT {
        (slot - TP_WORKER_LEGACY_SLOT_COUNT) * TP_WORKER_PI_COUNT + pi
    } else {
        (TP_WORKER_SLOT_COUNT - TP_WORKER_LEGACY_SLOT_COUNT) * TP_WORKER_PI_COUNT
            + (pi - TP_WORKER_PI_COUNT) * TP_WORKER_SLOT_COUNT
            + slot
    }
}

#[inline]
pub const fn tp_worker_badge(pi: usize, slot: usize) -> u64 {
    if pi < TP_WORKER_PI_COUNT && slot < TP_WORKER_LEGACY_SLOT_COUNT {
        TP_WORKER_BADGE_BASE + slot as u64 * TP_WORKER_PI_COUNT as u64 + pi as u64
    } else {
        TP_WORKER_AUX_BADGE_BASE + tp_worker_aux_index(pi, slot) as u64
    }
}

#[inline]
pub const fn tp_worker_identity_from_badge(badge: u64) -> Option<(usize, usize)> {
    let offset = badge.wrapping_sub(TP_WORKER_BADGE_BASE);
    if offset < (TP_WORKER_PI_COUNT * TP_WORKER_LEGACY_SLOT_COUNT) as u64 {
        Some((
            offset as usize % TP_WORKER_PI_COUNT,
            offset as usize / TP_WORKER_PI_COUNT,
        ))
    } else {
        let aux_offset = badge.wrapping_sub(TP_WORKER_AUX_BADGE_BASE);
        let live_extra = (TP_WORKER_SLOT_COUNT - TP_WORKER_LEGACY_SLOT_COUNT) * TP_WORKER_PI_COUNT;
        if aux_offset < live_extra as u64 {
            let index = aux_offset as usize;
            Some((
                index % TP_WORKER_PI_COUNT,
                TP_WORKER_LEGACY_SLOT_COUNT + index / TP_WORKER_PI_COUNT,
            ))
        } else {
            let later_offset = aux_offset - live_extra as u64;
            if later_offset < ((MAX_PI - TP_WORKER_PI_COUNT) * TP_WORKER_SLOT_COUNT) as u64 {
                let index = later_offset as usize;
                Some((
                    TP_WORKER_PI_COUNT + index / TP_WORKER_SLOT_COUNT,
                    index % TP_WORKER_SLOT_COUNT,
                ))
            } else {
                None
            }
        }
    }
}

#[inline]
pub const fn tp_worker_high_region_base(slot: usize) -> u64 {
    TP_WORKER_SLOT0_REGION_BASE + slot as u64 * TP_WORKER_EXEC_STRIDE
}

#[inline]
pub const fn tp_worker_stack_base(slot: usize) -> u64 {
    tp_worker_high_region_base(slot)
}

#[inline]
pub const fn tp_worker_stack_top(slot: usize) -> u64 {
    tp_worker_stack_base(slot) + TP_WORKER_STACK_FRAMES * 0x1000
}

#[inline]
pub const fn tp_worker_context_rsp(slot: usize) -> u64 {
    ((tp_worker_stack_top(slot) - 6 * 8) & !15) - 8
}

#[inline]
pub const fn tp_worker_ipcbuf_va(slot: usize) -> u64 {
    tp_worker_high_region_base(slot) + 0x1_0000
}

#[inline]
pub const fn tp_worker_teb_va(slot: usize) -> u64 {
    tp_worker_high_region_base(slot) + 0x2_0000
}

#[inline]
pub const fn tp_worker_tramp_va(slot: usize) -> u64 {
    tp_worker_high_region_base(slot) + 0x3_0000
}

#[inline]
pub const fn tp_worker_stack_mirror_va(pi: usize, slot: usize) -> u64 {
    if pi < TP_WORKER_PI_COUNT && slot < TP_WORKER_LEGACY_SLOT_COUNT {
        let base = if slot == 0 {
            TP_WORKER_EXEC_BASE
        } else {
            TP_WORKER_SLOT1_EXEC_BASE
        };
        base + pi as u64 * TP_WORKER_EXEC_STRIDE
    } else {
        TP_WORKER_AUX_EXEC_BASE + tp_worker_aux_index(pi, slot) as u64 * TP_WORKER_EXEC_STRIDE
    }
}

#[inline]
pub const fn tp_worker_teb_mirror_va(pi: usize, slot: usize) -> u64 {
    tp_worker_stack_mirror_va(pi, slot) + TP_WORKER_STACK_FRAMES * 0x1000
}

#[inline]
pub const fn tp_worker_env_scratch_va(pi: usize, slot: usize) -> u64 {
    tp_worker_stack_mirror_va(pi, slot) + TP_WORKER_ENV_SCRATCH_OFFSET
}

pub const TP_WORKER_STACK_FRAME_COUNT: usize = TP_WORKER_STACK_FRAMES as usize;

#[derive(Clone, Copy)]
struct HostedTpWorkerWindowResources {
    live: bool,
    stack_owner: [u64; TP_WORKER_STACK_FRAME_COUNT],
    stack_target: [u64; TP_WORKER_STACK_FRAME_COUNT],
    stack_mirror: [u64; TP_WORKER_STACK_FRAME_COUNT],
    teb_owner: u64,
    teb_target: u64,
    teb_scratch: u64,
    teb2_owner: u64,
    teb2_target: u64,
    teb2_scratch: u64,
    acs_owner: u64,
    acs_target: u64,
    ipc_target: u64,
    tramp_owner: u64,
    tramp_target: u64,
}

impl HostedTpWorkerWindowResources {
    const fn empty() -> Self {
        Self {
            live: false,
            stack_owner: [0; TP_WORKER_STACK_FRAME_COUNT],
            stack_target: [0; TP_WORKER_STACK_FRAME_COUNT],
            stack_mirror: [0; TP_WORKER_STACK_FRAME_COUNT],
            teb_owner: 0,
            teb_target: 0,
            teb_scratch: 0,
            teb2_owner: 0,
            teb2_target: 0,
            teb2_scratch: 0,
            acs_owner: 0,
            acs_target: 0,
            ipc_target: 0,
            tramp_owner: 0,
            tramp_target: 0,
        }
    }
}

static HOSTED_TP_WORKER_WINDOW_RESOURCE_ALLOCATION_FAILURES: AtomicU64 = AtomicU64::new(0);
static mut HOSTED_TP_WORKER_WINDOW_RESOURCES: alloc::vec::Vec<
    [HostedTpWorkerWindowResources; TP_WORKER_SLOT_COUNT],
> = alloc::vec::Vec::new();

pub(crate) unsafe fn reset_hosted_tp_worker_window_resources(slots: usize) -> bool {
    let table = &mut *core::ptr::addr_of_mut!(HOSTED_TP_WORKER_WINDOW_RESOURCES);
    table.clear();
    if table.try_reserve(slots).is_err() {
        HOSTED_TP_WORKER_WINDOW_RESOURCE_ALLOCATION_FAILURES.fetch_add(1, Ordering::Relaxed);
        return false;
    }
    while table.len() < slots {
        table.push([HostedTpWorkerWindowResources::empty(); TP_WORKER_SLOT_COUNT]);
    }
    true
}

fn hosted_tp_worker_window_resource_stats() -> (usize, usize, u64) {
    unsafe {
        let table = &*core::ptr::addr_of!(HOSTED_TP_WORKER_WINDOW_RESOURCES);
        (
            table.len(),
            table.capacity(),
            HOSTED_TP_WORKER_WINDOW_RESOURCE_ALLOCATION_FAILURES.load(Ordering::Relaxed),
        )
    }
}

fn hosted_tp_worker_slot_from_layout(
    pi: usize,
    stack_base: u64,
    teb_va: u64,
    ipcbuf_va: u64,
    tramp_va: u64,
) -> Option<usize> {
    if pi >= MAX_PI {
        return None;
    }
    (0..TP_WORKER_SLOT_COUNT).find(|&slot| {
        stack_base == tp_worker_stack_base(slot)
            && teb_va == tp_worker_teb_va(slot)
            && ipcbuf_va == tp_worker_ipcbuf_va(slot)
            && tramp_va == tp_worker_tramp_va(slot)
    })
}

unsafe fn recycle_mapped_cap(cap: u64) {
    if cap != 0 {
        let _ = page_unmap_r(cap);
        let _ = cnode_delete_recycle_r(cap);
    }
}

unsafe fn recycle_plain_cap(cap: u64) {
    if cap != 0 {
        let _ = cnode_delete_recycle_r(cap);
    }
}

unsafe fn detach_win32k_attached_page_for_thread_release(pi: usize, page: u64) {
    if W32_ATTACHED_PI.load(Ordering::Relaxed) != pi as u64 {
        return;
    }
    let (cap, _, _) = w32_attach_replace_mapping(page, 0, 0);
    recycle_mapped_cap(cap);
}

unsafe fn take_registered_thread_page(pi: usize, page: u64, owner: u64) {
    detach_win32k_attached_page_for_thread_release(pi, page);
    if let Some((frame, alias_cap, source_cap, _owns_frame)) = csrss_frame_take(pi as u64, page) {
        recycle_mapped_cap(alias_cap);
        if source_cap != owner && source_cap != frame && source_cap != alias_cap {
            recycle_plain_cap(source_cap);
        }
    }
}

unsafe fn release_unmapped_owned_thread_frame(owner: u64) {
    if owner != 0 {
        vm_frame_release_unmapped(owner);
    }
}

unsafe fn release_mapped_owned_thread_frame(owner: u64) {
    if owner != 0 {
        vm_frame_release(owner, 0);
    }
}

unsafe fn store_hosted_tp_worker_window_resources(
    pi: usize,
    slot: usize,
    resources: HostedTpWorkerWindowResources,
) {
    let table = &mut *core::ptr::addr_of_mut!(HOSTED_TP_WORKER_WINDOW_RESOURCES);
    if pi < table.len() && slot < TP_WORKER_SLOT_COUNT {
        table[pi][slot] = resources;
    }
}

pub(crate) unsafe fn release_hosted_tp_worker_window_resources(pi: usize, slot: usize) {
    let table = &mut *core::ptr::addr_of_mut!(HOSTED_TP_WORKER_WINDOW_RESOURCES);
    if pi >= table.len() || slot >= TP_WORKER_SLOT_COUNT {
        return;
    }
    let resources = table[pi][slot];
    if !resources.live {
        return;
    }
    table[pi][slot] = HostedTpWorkerWindowResources::empty();

    for index in 0..TP_WORKER_STACK_FRAME_COUNT {
        let page = tp_worker_stack_base(slot) + index as u64 * 0x1000;
        take_registered_thread_page(pi, page, resources.stack_owner[index]);
        recycle_mapped_cap(resources.stack_target[index]);
        recycle_mapped_cap(resources.stack_mirror[index]);
        release_unmapped_owned_thread_frame(resources.stack_owner[index]);
    }

    take_registered_thread_page(pi, tp_worker_teb_va(slot), resources.teb_owner);
    recycle_mapped_cap(resources.teb_target);
    recycle_mapped_cap(resources.teb_scratch);
    release_unmapped_owned_thread_frame(resources.teb_owner);

    take_registered_thread_page(pi, tp_worker_teb_va(slot) + 0x1000, resources.teb2_owner);
    recycle_mapped_cap(resources.teb2_target);
    recycle_mapped_cap(resources.teb2_scratch);
    release_unmapped_owned_thread_frame(resources.teb2_owner);

    recycle_mapped_cap(resources.acs_target);
    release_mapped_owned_thread_frame(resources.acs_owner);
    recycle_mapped_cap(resources.ipc_target);
    recycle_mapped_cap(resources.tramp_target);
    release_mapped_owned_thread_frame(resources.tramp_owner);
}

const fn hosted_thread_layout_is_disjoint(
    stack_base: u64,
    stack_frames: u64,
    ipcbuf_va: u64,
    teb_va: u64,
    tramp_va: u64,
) -> bool {
    stack_base + stack_frames * 0x1000 <= ipcbuf_va
        && ipcbuf_va + 0x1000 <= teb_va
        // TEB page 1 + TEB page 2 + the thread's PRIVATE ACTIVATION_CONTEXT_STACK page.
        && teb_va + 0x3000 <= tramp_va
}

const fn ranges_are_disjoint(a_base: u64, a_size: u64, b_base: u64, b_size: u64) -> bool {
    a_base + a_size <= b_base || b_base + b_size <= a_base
}

const _: () = {
    assert!(WL_LISTENER_STACK_FRAMES >= 8);
    assert!(nt_syscall_abi::native_ipc_buffer_va(SMSS_TEB_VA) == IPCBUF_VADDR);
    assert!(nt_syscall_abi::native_ipc_buffer_va(TEB_VA) == IPCBUF_VADDR);
    assert!(nt_syscall_abi::native_ipc_buffer_va(HOSTED_THREAD_TEB_VA) == HOSTED_THREAD_IPCBUF_VA);
    assert!(nt_syscall_abi::native_ipc_buffer_va(WL_LISTENER_TEB_VA) == WL_LISTENER_IPCBUF_VA);
    assert!(nt_syscall_abi::native_ipc_buffer_va(WL_WORKER2_TEB_VA) == WL_WORKER2_IPCBUF_VA);
    assert!(nt_syscall_abi::native_ipc_buffer_va(WL_WORKER3_TEB_VA) == WL_WORKER3_IPCBUF_VA);
    assert!(nt_syscall_abi::native_ipc_buffer_va(SVC_LISTENER_TEB_VA) == SVC_LISTENER_IPCBUF_VA);
    assert!(
        nt_syscall_abi::native_ipc_buffer_va(LSASS_LISTENER_TEB_VA) == LSASS_LISTENER_IPCBUF_VA
    );
    assert!(
        nt_syscall_abi::native_ipc_buffer_va(LSASS_LISTENER2_TEB_VA) == LSASS_LISTENER2_IPCBUF_VA
    );
    assert!(
        nt_syscall_abi::native_ipc_buffer_va(LSASS_LISTENER3_TEB_VA) == LSASS_LISTENER3_IPCBUF_VA
    );
    assert!(nt_syscall_abi::native_ipc_buffer_va(TP_WORKER_TEB_VA) == TP_WORKER_IPCBUF_VA);
    assert!(
        nt_syscall_abi::native_ipc_buffer_va(TP_WORKER_SLOT1_TEB_VA) == TP_WORKER_SLOT1_IPCBUF_VA
    );
    assert!(nt_syscall_abi::native_ipc_buffer_va(tp_worker_teb_va(4)) == tp_worker_ipcbuf_va(4));
    assert!(HOSTED_THREAD_IPCBUF_VA != WL_WORKER2_IPCBUF_VA);
    assert!(HOSTED_THREAD_IPCBUF_VA != WL_WORKER3_IPCBUF_VA);
    assert!(WL_WORKER2_IPCBUF_VA != WL_WORKER3_IPCBUF_VA);
    assert!(hosted_thread_layout_is_disjoint(
        HOSTED_THREAD_STACK_BASE,
        HOSTED_THREAD_STACK_FRAMES,
        HOSTED_THREAD_IPCBUF_VA,
        HOSTED_THREAD_TEB_VA,
        HOSTED_THREAD_TRAMP_VA,
    ));
    assert!(hosted_thread_layout_is_disjoint(
        SVC_LISTENER_STACK_BASE,
        SVC_LISTENER_STACK_FRAMES,
        SVC_LISTENER_IPCBUF_VA,
        SVC_LISTENER_TEB_VA,
        SVC_LISTENER_TRAMP_VA,
    ));
    assert!(hosted_thread_layout_is_disjoint(
        WL_WORKER2_STACK_BASE,
        WL_WORKER2_STACK_FRAMES,
        WL_WORKER2_IPCBUF_VA,
        WL_WORKER2_TEB_VA,
        WL_WORKER2_TRAMP_VA,
    ));
    assert!(hosted_thread_layout_is_disjoint(
        WL_WORKER3_STACK_BASE,
        WL_WORKER3_STACK_FRAMES,
        WL_WORKER3_IPCBUF_VA,
        WL_WORKER3_TEB_VA,
        WL_WORKER3_TRAMP_VA,
    ));
    assert!(hosted_thread_layout_is_disjoint(
        TP_WORKER_STACK_BASE,
        TP_WORKER_STACK_FRAMES,
        TP_WORKER_IPCBUF_VA,
        TP_WORKER_TEB_VA,
        TP_WORKER_TRAMP_VA,
    ));
    assert!(hosted_thread_layout_is_disjoint(
        TP_WORKER_SLOT1_STACK_BASE,
        TP_WORKER_STACK_FRAMES,
        TP_WORKER_SLOT1_IPCBUF_VA,
        TP_WORKER_SLOT1_TEB_VA,
        TP_WORKER_SLOT1_TRAMP_VA,
    ));
    assert!(TP_WORKER_SLOT0_REGION_BASE + TP_WORKER_EXEC_STRIDE == TP_WORKER_SLOT1_REGION_BASE);
    assert!(TP_WORKER_SLOT0_REGION_BASE & 0xffff == 0);
    assert!(tp_worker_high_region_base(0) == TP_WORKER_SLOT0_REGION_BASE);
    assert!(tp_worker_high_region_base(1) == TP_WORKER_SLOT1_REGION_BASE);
    assert!(ranges_are_disjoint(
        TP_WORKER_SLOT0_REGION_BASE,
        TP_WORKER_EXEC_STRIDE,
        HOSTED_MAIN_STACK_ALLOCATION_BASE,
        STACK_BASE + STACK_FRAMES * 0x1000 - HOSTED_MAIN_STACK_ALLOCATION_BASE,
    ));
    assert!(TP_WORKER_AUX_BADGE_BASE >= 0x100);
    assert!(TP_WORKER_SLOT_COUNT > TP_WORKER_LEGACY_SLOT_COUNT);
    assert!(TP_WORKER_SLOT_COUNT <= 16);
    assert!(tp_worker_badge(0, 0) == 16);
    assert!(tp_worker_badge(TP_WORKER_PI_COUNT - 1, 0) == 20);
    assert!(tp_worker_badge(0, 1) == 21);
    assert!(tp_worker_badge(TP_WORKER_PI_COUNT - 1, 1) == 25);
    assert!(tp_worker_badge(0, 2) == TP_WORKER_AUX_BADGE_BASE);
    assert!(tp_worker_badge(TP_WORKER_PI_COUNT - 1, 2) == TP_WORKER_AUX_BADGE_BASE + 4);
    assert!(
        tp_worker_badge(TP_WORKER_PI_COUNT, 0)
            == TP_WORKER_AUX_BADGE_BASE
                + ((TP_WORKER_SLOT_COUNT - TP_WORKER_LEGACY_SLOT_COUNT) * TP_WORKER_PI_COUNT)
                    as u64
    );
    match tp_worker_identity_from_badge(tp_worker_badge(MAX_PI - 1, TP_WORKER_SLOT_COUNT - 1)) {
        Some((pi, slot)) => {
            assert!(pi == MAX_PI - 1);
            assert!(slot == TP_WORKER_SLOT_COUNT - 1);
        }
        None => assert!(false),
    }
    assert!(TP_WORKER_CONTEXT_RSP >= TP_WORKER_STACK_BASE);
    assert!(TP_WORKER_CONTEXT_RSP < TP_WORKER_STACK_TOP);
    assert!(TP_WORKER_CONTEXT_RSP & 15 == 8);
    // 5 scratch pages: TEB p1, TEB p2, trampoline, verify, the private ACS page.
    assert!(TP_WORKER_EXEC_STRIDE >= TP_WORKER_ENV_SCRATCH_OFFSET + 0x5000);
    assert!(
        tp_worker_env_scratch_va(TP_WORKER_PI_COUNT - 1, 0) + 0x5000
            <= TP_WORKER_EXEC_BASE + 0x20_0000
    );
    assert!(TP_WORKER_SLOT1_REGION_BASE & 0x1f_ffff == 0);
    assert!(
        tp_worker_high_region_base(TP_WORKER_SLOT_COUNT - 1) + 0x20_0000 <= TP_WORKER_AUX_EXEC_BASE
    );
    assert!(
        tp_worker_env_scratch_va(TP_WORKER_PI_COUNT - 1, 1) + 0x4000
            <= TP_WORKER_SLOT1_EXEC_BASE + 0x20_0000
    );
    assert!(
        tp_worker_stack_mirror_va(TP_WORKER_PI_COUNT - 1, TP_WORKER_LEGACY_SLOT_COUNT)
            >= TP_WORKER_AUX_EXEC_BASE
    );
    // The AUX region must not alias either legacy mirror region, and must stay below the hosted
    // driver execution arena.
    assert!(TP_WORKER_AUX_EXEC_BASE >= TP_WORKER_SLOT1_EXEC_BASE + 0x20_0000);
    assert!(
        tp_worker_env_scratch_va(MAX_PI - 1, TP_WORKER_SLOT_COUNT - 1) + 0x4000
            <= crate::driver_launch::FSD_EXEC_BASE
    );
    assert!(tp_worker_stack_mirror_va(0, TP_WORKER_LEGACY_SLOT_COUNT) == TP_WORKER_AUX_EXEC_BASE);
    assert!(
        tp_worker_stack_mirror_va(TP_WORKER_PI_COUNT, 0)
            == TP_WORKER_AUX_EXEC_BASE
                + ((TP_WORKER_SLOT_COUNT - TP_WORKER_LEGACY_SLOT_COUNT) * TP_WORKER_PI_COUNT)
                    as u64
                    * TP_WORKER_EXEC_STRIDE
    );
};

