pub const SSN_NT_SET_SYSTEM_POWER_STATE: u64 = 250;
pub const SSN_NT_SET_UUID_SEED: u64 = 255;
/// SEH/context native services. `NtContinue` restores a kernel-delivered user context; last-chance
