pub const SSN_NT_CREATE_DEBUG_OBJECT: u64 = 35;
pub const SSN_NT_DEBUG_ACTIVE_PROCESS: u64 = 59;
pub const SSN_NT_DEBUG_CONTINUE: u64 = 60;
pub const SSN_NT_REMOVE_PROCESS_DEBUG: u64 = 199;
pub const SSN_NT_WAIT_FOR_DEBUG_EVENT: u64 = 279;
const NT_HIVE_IMAGE_MAGIC_LE: u64 = 0x3145_5649_4854_4E55; // "UNTHIVE1"
/// NtAllocateLocallyUniqueId — line 16 of `sysfuncs.lst` (0-based index 15). msgina's `MyLogonUser`
/// calls it (via `AllocateLocallyUniqueId`) to mint the interactive logon session's LUID.
pub const SSN_NT_ALLOCATE_LOCALLY_UNIQUE_ID: u64 = 15;
pub const PE_SCRATCH_VADDR: u64 = 0x0000_0100_1052_0000;
/// The loaded PE's Windows environment: TEB + PEB (in the PE's existing PT) and
/// KUSER_SHARED_DATA at its fixed low VA (its own PT chain). The thread's GS base is set to
/// TEB_VA so `GS:[0x30]` is the TEB self-pointer (NtCurrentTeb).
pub const TEB_VA: u64 = 0x0000_0100_0057_0000;
pub const PEB_VA: u64 = 0x0000_0100_0058_0000;
pub const KUSER_VA: u64 = 0x0000_0000_7FFE_0000;
static SYSTEM_TIME_ZONE_BIAS_100NS: AtomicU64 = AtomicU64::new(0);
static SYSTEM_TIME_ZONE_ID: AtomicU32 = AtomicU32::new(0);
static NT_GLOBAL_FLAG: AtomicU32 = AtomicU32::new(0);
static SYSTEM_SESSION_NEXT_ID: AtomicU32 = AtomicU32::new(0);
static SYSTEM_SESSION_ACTIVE_MASK: AtomicU64 = AtomicU64::new(0);
pub const SYSTEM_POINTER_COOKIE: u32 = 0xA3B1_C2D3;
/// The provided "ntdll" — a page of syscall stubs mapped RX in the PE VSpace; the PE's IAT is
/// resolved to point here, so the PE calls named ntdll functions like real Windows code.
pub const NTDLL_VA: u64 = 0x0000_0100_0059_0000;
/// Where the executive maps real device MMIO it claims (P1). HPET is exposed by the
/// kernel as a device untyped and isn't used by the kernel, so it's a safe first target.
pub const HPET_PADDR: u64 = 0xFED0_0000;
pub const HPET_VADDR: u64 = 0x0000_0100_105E_0000;
/// P2: the AHCI controller ABAR (BAR5) MMIO, and a DMA frame for its command structures +
/// the sector data buffer in the storage cluster before IPCBUF.
pub const AHCI_VADDR: u64 = 0x0000_0100_105F_4000;
pub const AHCI_DMA_VADDR: u64 = 0x0000_0100_105F_5000;
/// Shared word between the executive (broker) and the isolated storage host: the AHCI's
/// device address (identity paddr, or a VT-d IOVA once confined) in @0; verdict (u32) @8,
/// INITRD cluster @0x10, size @0x14 out.
pub const STORAGE_SHARED_VADDR: u64 = 0x0000_0100_1044_0000;
pub const STORAGE_SHARED_FRAMES: u64 = 8;
pub const STORAGE_HIVE_IMAGE_OFFSET: u64 = 0x1000;
pub const STORAGE_IMPORTS_IMAGE_OFFSET: u64 = 0x800;
pub const STORAGE_HIVE_IMAGE_CAP: usize =
    (STORAGE_SHARED_FRAMES as usize * 0x1000) - STORAGE_HIVE_IMAGE_OFFSET as usize;
pub const STORAGE_SHARED_END: u64 = STORAGE_SHARED_VADDR + STORAGE_SHARED_FRAMES * 0x1000;
pub const BOOT_PROOF_ALIAS_BASE: u64 = 0x0000_0100_1340_0000;
pub const BOOT_PROOF_ALIAS_END: u64 = BOOT_PROOF_ALIAS_BASE + 0x20_0000;
pub const BOOT_SEC_IMAGE_SCRATCH_BASE: u64 = BOOT_PROOF_ALIAS_BASE;
const _: () = assert!(STORAGE_SHARED_VADDR >= WORK_CLUSTER_BASE);
const _: () = assert!(STORAGE_SHARED_END <= WORK_CLUSTER_BASE + 0x20_0000);
const _: () = assert!(BOOT_PROOF_ALIAS_END <= SVC_LISTENER_STACK_MIRROR_VA);
static NEXT_BOOT_PROOF_ALIAS: AtomicU64 = AtomicU64::new(BOOT_PROOF_ALIAS_END - 0x1000);
/// A multi-frame file buffer shared between the executive and the storage host: the host reads
/// a real PE (ReactOS SMSS.EXE) off the disk into it, and the executive parses it there. 32
/// frames (128 KiB) at a fresh 2 MiB region, contiguous in both VSpaces (one shared PT).
pub const FILEBUF_VADDR: u64 = 0x0000_0100_1060_0000; // its own PT, just past the cluster region
pub const FILEBUF_FRAMES: u64 = 64; // 256 KiB — holds smss + csrss + csrsrv, still one 2 MiB PT
/// csrss.exe (~7 KiB) is staged into the FILEBUF tail, past smss.exe (~99 KiB) but well within the
/// buffer — no separate buffer needed. The storage host reads it here and writes its size
/// to STORAGE_SHARED+0x3c; the executive parses the PE from FILEBUF_VADDR+CSRSS_FILEBUF_OFFSET.
pub const CSRSS_FILEBUF_OFFSET: u64 = 0x1A000; // 104 KiB in — clear of a ~99 KiB smss
/// csrsrv.dll (~65 KiB) — csrss.exe's static-import Server DLL — is staged further into the FILEBUF
/// (past smss+csrss), size reported at STORAGE_SHARED+0x40. The loader needs it or DLL_NOT_FOUND.
pub const CSRSRV_FILEBUF_OFFSET: u64 = 0x20000; // 128 KiB in — clear of csrss (ends ~111 KiB)
/// basesrv.dll (~50 KiB) + winsrv.dll (~400 KiB) — csrss's dynamically-loaded ServerDlls — don't fit
/// in FILEBUF, so they get their own 512 KiB buffer (its own 2 MiB PT), dual-mapped host<->exec like
/// NTDLLBUF. basesrv at offset 0, winsrv at +0x10000; sizes reported at STORAGE_SHARED +0x44 / +0x48.
pub const SRVBUF_VADDR: u64 = 0x0000_0100_1400_0000;
pub const SRVBUF_FRAMES: u64 = 128; // 512 KiB
pub const BASESRV_SRVBUF_OFFSET: u64 = 0x0;
pub const WINSRV_SRVBUF_OFFSET: u64 = 0x10000; // 64 KiB in — clear of basesrv (~50 KiB)
/// winlogon.exe (~225 KiB, PE32+) — smss's SmpExecuteInitialCommand initial command. The FILEBUF
/// tail is full (smss+csrss+csrsrv), so it gets its OWN 256 KiB buffer (its own 2 MiB PT past
/// SRVBUF), dual-mapped host<->exec like SRVBUF. Size reported at STORAGE_SHARED+0x94; the executive
/// parses it PE32+ and spawns it as the 3rd hosted process when smss's RtlCreateUserProcess creates it.
pub const WINLOGONBUF_VADDR: u64 = 0x0000_0100_1420_0000; // own PT, past SRVBUF (0x1400)
pub const WINLOGONBUF_FRAMES: u64 = 64; // 256 KiB — holds the 229888 B winlogon.exe
/// The Win32 client stack (kernel32 ~2.66 MiB + user32 ~1.12 MiB + gdi32 ~326 KiB) that winsrv.dll
/// statically imports. These are too large for the SRVBUF, so they get their own fresh 6 MiB region
/// (3 PTs), dual-mapped host<->exec like SRVBUF. Sizes reported at STORAGE_SHARED +0x4c/+0x50/+0x54.
pub const WIN32BUF_VADDR: u64 = 0x0000_0100_0500_0000; // fresh 8 MiB region (4 PTs), past SRVBUF
pub const WIN32BUF_FRAMES: u64 = 2048; // 8 MiB — kernel32+user32+gdi32 + Win32 deps
pub const KERNEL32_WIN32BUF_OFFSET: u64 = 0x0; // kernel32 ~2.66 MiB
pub const USER32_WIN32BUF_OFFSET: u64 = 0x2C0000; // user32 ~1.12 MiB (clear of kernel32)
pub const GDI32_WIN32BUF_OFFSET: u64 = 0x400000; // gdi32 ~326 KiB (clear of user32)
                                                 // winsrv's transitive import closure (7 DLLs, ~1.77 MiB) — sizes at STORAGE_SHARED +0x58..+0x70.
pub const RPCRT4_WIN32BUF_OFFSET: u64 = 0x460000; // rpcrt4 ~617 KiB
pub const MSVCRT_WIN32BUF_OFFSET: u64 = 0x500000; // msvcrt ~581 KiB
pub const ADVAPI32_WIN32BUF_OFFSET: u64 = 0x5A0000; // advapi32 ~455 KiB
pub const WS2_32_WIN32BUF_OFFSET: u64 = 0x620000; // ws2_32 ~93 KiB
pub const KERNEL32_VISTA_WIN32BUF_OFFSET: u64 = 0x640000; // kernel32_vista ~32 KiB
pub const ADVAPI32_VISTA_WIN32BUF_OFFSET: u64 = 0x650000; // advapi32_vista ~23 KiB
pub const WS2HELP_WIN32BUF_OFFSET: u64 = 0x660000; // ws2help ~14 KiB
pub const NTDLL_VISTA_WIN32BUF_OFFSET: u64 = 0x670000; // ntdll_vista ~56 KiB (ends 0x67E000)
                                                       // winlogon.exe's two extra static imports (the rest of its Win32 stack is shared with csrss above).
pub const USERENV_WIN32BUF_OFFSET: u64 = 0x680000; // userenv ~166 KiB (file 0x297C0)
pub const MPR_WIN32BUF_OFFSET: u64 = 0x6C0000; // mpr ~107 KiB (ends ~0x6DAC00)
/// Raw win32k.sys staging buffer (2,208,192 B). Its own 2 MiB-aligned window past WIN32BUF, with
/// 2 page tables (544 frames = 0x220000 spans two 2 MiB PTs). The storage host reads win32k.sys
/// off disk into here; the executive parses+loads it into the win32k-service component.
pub const WIN32KBUF_VADDR: u64 = 0x0000_0100_0600_0000;
pub const WIN32KBUF_FRAMES: u64 = 544; // 0x220 — matches win32k.sys size_of_image
/// Fault-endpoint badge for the second hosted process (csrss). smss's fault cap is an unbadged
/// copy (badge 0); csrss's is minted at this badge so the single service loop can tell them apart.
pub const CSRSS_BADGE: u64 = 2;
// ★ BATCH 22 demand-fault scratch layout. The old scheme packed the early processes' scratch into the
// single 8-PT span 0x1100..0x1200 with ~512-page inter-process spacing — too tight now that the
// BATCH bulk-fill lets a process (lsass) page in its full LSA-init DLL tree (thousands of pages;
// each fill takes a UNIQUE monotonic scratch slot). Each process now gets its OWN 64 MiB window
// (0x400_0000 = 16384 pages, well above FAULT_CAP) in the free high VA region past all other
// executive mappings (POOL_VADDR 0x1500, SRVBUF 0x1400, win32k pools 0x0A00 — all far below
// 0x2000). Their page tables are mapped per-window at spawn (see `map_demand_scratch_pts`).
pub const DEMAND_SCRATCH_WINDOW: u64 = 0x0400_0000; // 64 MiB per process
                                                    // The static-process lanes begin exactly after the executive's runtime-mapped heap and the 7 ×
                                                    // 64 MiB windows remain below PRIVATE_VM_LIMIT. `ensure_executive_paging` builds every missing
                                                    // paging level, so this layout does not depend on boot-image page tables.
pub const SMSS_SCRATCH_BASE: u64 = allocator::HEAP_BASE as u64 + allocator::HEAP_FRAMES * 0x1000;
const _: () = assert!(SMSS_SCRATCH_BASE & 0x1f_ffff == 0);
/// csrss's demand-fault scratch window (own 64 MiB, PTs mapped at spawn).
pub const CSRSS_SCRATCH_BASE: u64 = SMSS_SCRATCH_BASE + DEMAND_SCRATCH_WINDOW;
/// Fault-endpoint badge for the THIRD hosted process (winlogon). Distinct from smss (0) + csrss (2).
pub const WINLOGON_BADGE: u64 = 4;
/// winlogon's demand-fault scratch window (own 64 MiB).
pub const WINLOGON_SCRATCH_BASE: u64 = SMSS_SCRATCH_BASE + 2 * DEMAND_SCRATCH_WINDOW;
/// Fault-endpoint badge for the FOURTH hosted process (services.exe). Distinct from smss (0) /
/// csrss (2) / winlogon (4).
pub const SERVICES_BADGE: u64 = 6;
/// services.exe's demand-fault scratch window (own 64 MiB).
pub const SERVICES_SCRATCH_BASE: u64 = SMSS_SCRATCH_BASE + 3 * DEMAND_SCRATCH_WINDOW;
/// Fault-endpoint badge for the FIFTH hosted process (lsass.exe). Distinct from smss(0)/csrss(2)/
/// winlogon(4)/services(6)/SVC_LISTENER(7).
pub const LSASS_BADGE: u64 = 8;
/// lsass.exe's demand-fault scratch window (own 64 MiB) — sized so lsass's full LSA-init DLL tree
/// (lsasrv/samsrv/msv1_0 + deps) can page in without overflowing into a neighbour's scratch.
pub const LSASS_SCRATCH_BASE: u64 = SMSS_SCRATCH_BASE + 4 * DEMAND_SCRATCH_WINDOW;
pub const USERINIT_SCRATCH_BASE: u64 = SMSS_SCRATCH_BASE + 5 * DEMAND_SCRATCH_WINDOW;
/// Current hosted-process runtime table budget. Static boot processes occupy `pi=0..6`; dynamic
/// hosted processes are admitted densely from `DYNAMIC_PROCESS_FIRST_PI` up to this executive budget,
/// which must remain below the badge transport limit exposed by `nt-exe-image`. The table is generic
/// over process instances, not executable names or launch order, and every pi-indexed write site
/// still guards `pi < MAX_PI` so exhaustion is explicit instead of corrupting neighbouring mechanism
/// state. Moving past this boot-image-fitting table budget needs map-backed/reclaimable process
/// runtime state, not more hardcoded image identities.
pub const HOSTED_PROCESS_RUNTIME_PI_LIMIT: usize = 24;
pub const MAX_PI: usize = HOSTED_PROCESS_RUNTIME_PI_LIMIT;
const _: () = assert!(MAX_PI <= nt_exe_image::DYNAMIC_PROCESS_PI_LIMIT);
/// Ordered image-open/section/spawn records are handle-lifetime records, not process slots. A
/// published process record is retained after its file/section handles close so later
/// `NtCreateProcessEx`/publication accounting remains ordered, while dynamic service starts can
/// consume additional transient records before winlogon reaches the shell. Keep this independent of
/// `MAX_PI`; process indices are still bounded by `MAX_PI` when dynamic images are admitted.
pub(crate) const HOSTED_PROCESS_IMAGE_CAP: usize = MAX_PI * 4;
/// Per-process VAD extents. A real NT process's VAD is an unbounded AVL tree; ours is a fixed slot
/// array, and `insert` returns STATUS_INSUFFICIENT_RESOURCES once it is full.
///
/// ★ BATCH 58 measured this and RULED IT OUT as the `CopyDirectory` frontier. The later full
/// explorer desktop path reaches 48 live/split private VAD extents while still making real forward
/// progress. Keep the reset-safe table fixed, but size it with measured runway so the headroom gate
/// remains meaningful instead of sitting exactly on its three-quarter ceiling.
const VM_REGION_CAPACITY: usize = 96;
const USER_ADDRESS_LIMIT: u64 = 0x0000_07ff_ffff_0000;
static PROCESS_VM_REGION_ALLOCATION_FAILURES: AtomicU64 = AtomicU64::new(0);
static mut PROCESS_VM_REGIONS: alloc::vec::Vec<nt_address_space::VmRegionMap<VM_REGION_CAPACITY>> =
    alloc::vec::Vec::new();
/// Non-private committed mappings owned outside the private VAD allocator.
///
/// This covers process-lifetime runtime pages plus mapped section/image views. Image views are
/// tracked at section-protection granularity, so each loaded module contributes several committed
/// ranges under one allocation base. Keep the table precharged for explorer's post-desktop DLL set
/// without allocating in the syscall-reset window.
const PROCESS_COMMITTED_MAPPING_CAPACITY: usize = 512;
static PROCESS_COMMITTED_MAPPING_ALLOCATION_FAILURES: AtomicU64 = AtomicU64::new(0);
static mut PROCESS_COMMITTED_MAPPINGS: alloc::vec::Vec<
    nt_address_space::VmCommittedRangeTable<PROCESS_COMMITTED_MAPPING_CAPACITY>,
> = alloc::vec::Vec::new();

pub(crate) unsafe fn reset_process_vm_region_maps(slots: usize) -> bool {
    let maps = &mut *core::ptr::addr_of_mut!(PROCESS_VM_REGIONS);
    maps.clear();
    if maps.try_reserve(slots).is_err() {
        PROCESS_VM_REGION_ALLOCATION_FAILURES.fetch_add(1, Ordering::Relaxed);
        return false;
    }
    while maps.len() < slots {
        maps.push(nt_address_space::VmRegionMap::new(
            SMSS_ALLOC_VA,
            PRIVATE_VM_LIMIT,
        ));
    }
    true
}

pub(crate) unsafe fn process_vm_region_map_mut(
    pi: usize,
) -> Option<&'static mut nt_address_space::VmRegionMap<VM_REGION_CAPACITY>> {
    (&mut *core::ptr::addr_of_mut!(PROCESS_VM_REGIONS)).get_mut(pi)
}

pub(crate) unsafe fn process_vm_region_map(
    pi: usize,
) -> Option<&'static nt_address_space::VmRegionMap<VM_REGION_CAPACITY>> {
    (&*core::ptr::addr_of!(PROCESS_VM_REGIONS)).get(pi)
}

pub(crate) unsafe fn process_vm_region_map_reset(pi: usize) {
    if let Some(map) = process_vm_region_map_mut(pi) {
        *map = nt_address_space::VmRegionMap::new(SMSS_ALLOC_VA, PRIVATE_VM_LIMIT);
    }
}

pub(crate) unsafe fn reset_process_committed_mappings(slots: usize) -> bool {
    let mappings = &mut *core::ptr::addr_of_mut!(PROCESS_COMMITTED_MAPPINGS);
    mappings.clear();
    if mappings.try_reserve(slots).is_err() {
        PROCESS_COMMITTED_MAPPING_ALLOCATION_FAILURES.fetch_add(1, Ordering::Relaxed);
        return false;
    }
    while mappings.len() < slots {
        mappings.push(nt_address_space::VmCommittedRangeTable::new());
    }
    true
}

unsafe fn process_committed_mapping_table_mut(
    pi: usize,
) -> Option<&'static mut nt_address_space::VmCommittedRangeTable<PROCESS_COMMITTED_MAPPING_CAPACITY>>
{
    (&mut *core::ptr::addr_of_mut!(PROCESS_COMMITTED_MAPPINGS)).get_mut(pi)
}

unsafe fn process_committed_mapping_table(
    pi: usize,
) -> Option<&'static nt_address_space::VmCommittedRangeTable<PROCESS_COMMITTED_MAPPING_CAPACITY>> {
    (&*core::ptr::addr_of!(PROCESS_COMMITTED_MAPPINGS)).get(pi)
}

pub(crate) unsafe fn process_committed_mapping_register(
    pi: u64,
    range: nt_address_space::VmCommittedRange,
) -> bool {
    let Some(table) = process_committed_mapping_table_mut(pi as usize) else {
        return false;
    };
    match table.register(range) {
        Ok(()) => {
            note_high_water(&VM_COMMITTED_MAPPING_HW, table.range_count() as u64);
            true
        }
        Err(status) => {
            if VM_COMMITTED_MAPPING_REGISTRATION_FAILS.fetch_add(1, Ordering::Relaxed) < 8 {
                print_str(b"[vm-map] committed mapping registration failed pi=");
                print_u64(pi);
                print_str(b" base=0x");
                print_hex((range.base >> 32) as u32);
                print_hex(range.base as u32);
                print_str(b" size=0x");
                print_hex((range.size >> 32) as u32);
                print_hex(range.size as u32);
                print_str(b" status=0x");
                print_hex(status);
                print_str(b"\n");
            }
            false
        }
    }
}

pub(crate) unsafe fn process_committed_mapping_reset(pi: usize) {
    // This is an address-space lifetime boundary (fresh VSpace, temporary-slot release, or final
    // teardown), so no virtual lock may survive into the next owner of this process slot.
    let _ = vm_page_lock_retire_owner(pi as u64);
    if let Some(table) = process_committed_mapping_table_mut(pi) {
        *table = nt_address_space::VmCommittedRangeTable::new();
    }
}

pub(crate) unsafe fn process_committed_mapping_snapshot(
    pi: u64,
) -> Option<nt_address_space::VmCommittedRangeTable<PROCESS_COMMITTED_MAPPING_CAPACITY>> {
    process_committed_mapping_table(pi as usize).copied()
}

pub(crate) unsafe fn process_committed_mapping_replace(
    pi: u64,
    replacement: nt_address_space::VmCommittedRangeTable<PROCESS_COMMITTED_MAPPING_CAPACITY>,
) -> bool {
    let Some(table) = process_committed_mapping_table_mut(pi as usize) else {
        return false;
    };
    *table = replacement;
    note_high_water(&VM_COMMITTED_MAPPING_HW, table.range_count() as u64);
    true
}

pub(crate) unsafe fn process_committed_mapping_unregister_range(
    pi: u64,
    base: u64,
    size: u64,
) -> bool {
    let Some(table) = process_committed_mapping_table_mut(pi as usize) else {
        return false;
    };
    table
        .unregister_range(base, size)
        .is_ok_and(|removed| removed != 0)
}

pub(crate) unsafe fn process_committed_mapping_unregister_allocation(
    pi: u64,
    allocation_base: u64,
) -> bool {
    let Some(table) = process_committed_mapping_table_mut(pi as usize) else {
        return false;
    };
    table.unregister_allocation_base(allocation_base) != 0
}

pub(crate) unsafe fn process_committed_mapping_basic_information(
    pi: u64,
    page: u64,
) -> Option<nt_address_space::VmBasicInformation> {
    process_committed_mapping_table(pi as usize).and_then(|table| table.query_basic(page))
}

pub(crate) unsafe fn process_committed_image_allocation(
    pi: u64,
    page: u64,
) -> Option<nt_address_space::VmImageAllocation> {
    process_committed_mapping_table(pi as usize)
        .and_then(|table| table.image_allocation_for_page(page))
}

pub(crate) unsafe fn process_committed_mapping_next_base_after(pi: u64, page: u64) -> Option<u64> {
    process_committed_mapping_table(pi as usize).and_then(|table| table.next_base_after(page))
}

pub(crate) unsafe fn process_committed_mapping_first_overlap(
    pi: u64,
    base: u64,
    size: u64,
) -> Option<nt_address_space::VmCommittedRange> {
    process_committed_mapping_table(pi as usize)
        .and_then(|table| table.first_overlap_range(base, size).ok().flatten())
}

fn process_vm_region_map_stats() -> (usize, usize, u64) {
    unsafe {
        let maps = &*core::ptr::addr_of!(PROCESS_VM_REGIONS);
        (
            maps.len(),
            maps.capacity(),
            PROCESS_VM_REGION_ALLOCATION_FAILURES.load(Ordering::Relaxed),
        )
    }
}

fn process_committed_mapping_stats() -> (usize, usize, u64) {
    unsafe {
        let mappings = &*core::ptr::addr_of!(PROCESS_COMMITTED_MAPPINGS);
        (
            mappings.len(),
            mappings.capacity(),
            PROCESS_COMMITTED_MAPPING_ALLOCATION_FAILURES.load(Ordering::Relaxed),
        )
    }
}

/// Read-modify-write scratch for `NtAllocateVirtualMemory` / `NtFreeVirtualMemory`. A whole
/// `VmRegionMap` is KILOBYTES, and the executive's rootserver stack floats immediately after its
/// loaded image — two on-stack copies per call overflowed it into the guard page as soon as
/// [`VM_REGION_CAPACITY`] grew. Static (the executive is single-threaded and neither snapshot
/// outlives its call), so the frame cost is a pointer.
pub(crate) static mut VM_MAP_BEFORE: nt_address_space::VmRegionMap<VM_REGION_CAPACITY> =
    nt_address_space::VmRegionMap::new(SMSS_ALLOC_VA, PRIVATE_VM_LIMIT);
pub(crate) static mut VM_MAP_AFTER: nt_address_space::VmRegionMap<VM_REGION_CAPACITY> =
    nt_address_space::VmRegionMap::new(SMSS_ALLOC_VA, PRIVATE_VM_LIMIT);
pub(crate) static mut COMMITTED_MAP_BEFORE: nt_address_space::VmCommittedRangeTable<
    PROCESS_COMMITTED_MAPPING_CAPACITY,
> = nt_address_space::VmCommittedRangeTable::new();
pub(crate) static mut COMMITTED_MAP_AFTER: nt_address_space::VmCommittedRangeTable<
    PROCESS_COMMITTED_MAPPING_CAPACITY,
> = nt_address_space::VmCommittedRangeTable::new();
const PRIVATE_VM_PT_COUNT: usize = ((PRIVATE_VM_LIMIT - SMSS_ALLOC_VA) / 0x20_0000) as usize;
static PROCESS_VM_PT_CAP_ALLOCATION_FAILURES: AtomicU64 = AtomicU64::new(0);
static mut PROCESS_VM_PT_CAPS: alloc::vec::Vec<[u64; PRIVATE_VM_PT_COUNT]> = alloc::vec::Vec::new();
static mut VM_FREE_FRAMES: nt_address_space::RecycledFramePool =
    nt_address_space::RecycledFramePool::new();
static mut VM_PAGE_LOCKS: nt_address_space::VmPageLockTable =
    nt_address_space::VmPageLockTable::new();
static VM_LOCK_RECLAIM_REFUSALS: AtomicU64 = AtomicU64::new(0);
static KUSER_PAGE_ALIAS_ALLOCATION_FAILURES: AtomicU64 = AtomicU64::new(0);
static KUSER_PAGE_ALIAS_STORE_FAILURES: AtomicU64 = AtomicU64::new(0);
static mut KUSER_PAGE_ALIASES: alloc::vec::Vec<AtomicU64> = alloc::vec::Vec::new();
/// Executive-visible aliases for persistent kernel personalities which map KUSER_SHARED_DATA.
/// This registry is component-agnostic; a newly loaded personality registers its writable alias
/// instead of adding another clock-publication special case.
static mut KERNEL_KUSER_PAGE_ALIASES: alloc::vec::Vec<u64> = alloc::vec::Vec::new();

fn vm_free_frame_stats() -> nt_address_space::RecycledFramePoolStats {
    unsafe { (&*core::ptr::addr_of!(VM_FREE_FRAMES)).stats() }
}

fn vm_page_lock_stats() -> nt_address_space::VmPageLockStats {
    unsafe { (&*core::ptr::addr_of!(VM_PAGE_LOCKS)).stats() }
}

unsafe fn vm_page_lock_range(
    owner: u64,
    range: nt_address_space::VmResidencyRangePlan,
    map_type: u32,
) -> Result<u32, u32> {
    (&mut *core::ptr::addr_of_mut!(VM_PAGE_LOCKS)).lock_range(owner, range, map_type)
}

unsafe fn vm_page_unlock_range(
    owner: u64,
    range: nt_address_space::VmResidencyRangePlan,
    map_type: u32,
) -> Result<(), u32> {
    (&mut *core::ptr::addr_of_mut!(VM_PAGE_LOCKS)).unlock_range(owner, range, map_type)
}

unsafe fn vm_page_lock_is_locked(owner: u64, page: u64) -> bool {
    (&*core::ptr::addr_of!(VM_PAGE_LOCKS)).is_locked(owner, page)
}

unsafe fn vm_page_lock_range_is_locked(owner: u64, base: u64, end: u64) -> bool {
    let mut page = base & !(nt_address_space::PAGE_SIZE - 1);
    while page < end {
        if vm_page_lock_is_locked(owner, page) {
            return true;
        }
        page = page.saturating_add(nt_address_space::PAGE_SIZE);
    }
    false
}

unsafe fn vm_page_lock_retire_range(owner: u64, base: u64, size: u64) -> usize {
    (&mut *core::ptr::addr_of_mut!(VM_PAGE_LOCKS)).retire_range(owner, base, size)
}

unsafe fn vm_page_lock_retire_owner(owner: u64) -> usize {
    (&mut *core::ptr::addr_of_mut!(VM_PAGE_LOCKS)).retire_owner(owner)
}

unsafe fn vm_page_is_resident(pi: usize, page: u64) -> bool {
    page == KUSER_VA && kuser_page_alias_get(pi) != 0
        || csrss_frame_get_exact(pi as u64, page).0 != 0
        || shared_image_mapping_contains(pi as u64, page)
}

pub(crate) unsafe fn reset_process_private_pt_caps(slots: usize) -> bool {
    let caps = &mut *core::ptr::addr_of_mut!(PROCESS_VM_PT_CAPS);
    caps.clear();
    if caps.try_reserve(slots).is_err() {
        PROCESS_VM_PT_CAP_ALLOCATION_FAILURES.fetch_add(1, Ordering::Relaxed);
        return false;
    }
    while caps.len() < slots {
        caps.push([0; PRIVATE_VM_PT_COUNT]);
    }
    true
}

unsafe fn process_private_pt_caps_mut(
    pi: usize,
) -> Option<&'static mut [u64; PRIVATE_VM_PT_COUNT]> {
    (&mut *core::ptr::addr_of_mut!(PROCESS_VM_PT_CAPS)).get_mut(pi)
}

fn process_private_pt_cap_stats() -> (usize, usize, u64) {
    unsafe {
        let caps = &*core::ptr::addr_of!(PROCESS_VM_PT_CAPS);
        (
            caps.len(),
            caps.capacity(),
            PROCESS_VM_PT_CAP_ALLOCATION_FAILURES.load(Ordering::Relaxed),
        )
    }
}

pub(crate) unsafe fn reset_process_vm_state(slots: usize) -> bool {
    (&mut *core::ptr::addr_of_mut!(VM_PAGE_LOCKS)).reset();
    VM_LOCK_RECLAIM_REFUSALS.store(0, Ordering::Relaxed);
    reset_process_vm_region_maps(slots)
        && reset_process_committed_mappings(slots)
        && reset_process_private_pt_caps(slots)
        && reset_kuser_page_aliases(slots)
}

pub(crate) unsafe fn reset_kuser_page_aliases(slots: usize) -> bool {
    let aliases = &mut *core::ptr::addr_of_mut!(KUSER_PAGE_ALIASES);
    let kernel_aliases = &mut *core::ptr::addr_of_mut!(KERNEL_KUSER_PAGE_ALIASES);
    aliases.clear();
    kernel_aliases.clear();
    if aliases.try_reserve(slots).is_err() {
        KUSER_PAGE_ALIAS_ALLOCATION_FAILURES.fetch_add(1, Ordering::Relaxed);
        return false;
    }
    if kernel_aliases.try_reserve(4).is_err() {
        KUSER_PAGE_ALIAS_ALLOCATION_FAILURES.fetch_add(1, Ordering::Relaxed);
        return false;
    }
    while aliases.len() < slots {
        aliases.push(AtomicU64::new(0));
    }
    true
}

unsafe fn kuser_kernel_alias_register(alias: u64) -> bool {
    if alias == 0 {
        KUSER_PAGE_ALIAS_STORE_FAILURES.fetch_add(1, Ordering::Relaxed);
        return false;
    }
    let aliases = &mut *core::ptr::addr_of_mut!(KERNEL_KUSER_PAGE_ALIASES);
    if aliases.contains(&alias) {
        return true;
    }
    if aliases.try_reserve(1).is_err() {
        KUSER_PAGE_ALIAS_ALLOCATION_FAILURES.fetch_add(1, Ordering::Relaxed);
        return false;
    }
    aliases.push(alias);
    true
}

unsafe fn for_each_kuser_page_alias(mut publish: impl FnMut(u64)) {
    for pi in 0..MAX_PI {
        let alias = kuser_page_alias_get(pi);
        if alias != 0 {
            publish(alias);
        }
    }
    for &alias in &*core::ptr::addr_of!(KERNEL_KUSER_PAGE_ALIASES) {
        publish(alias);
    }
}

unsafe fn kuser_page_alias_put(pi: u64, alias: u64) -> bool {
    if let Some(slot) = (&*core::ptr::addr_of!(KUSER_PAGE_ALIASES)).get(pi as usize) {
        slot.store(alias, Ordering::Release);
        true
    } else {
        KUSER_PAGE_ALIAS_STORE_FAILURES.fetch_add(1, Ordering::Relaxed);
        false
    }
}

unsafe fn kuser_page_alias_clear(pi: usize) {
    if let Some(slot) = (&*core::ptr::addr_of!(KUSER_PAGE_ALIASES)).get(pi) {
        slot.store(0, Ordering::Release);
    }
}

unsafe fn kuser_page_alias_get(pi: usize) -> u64 {
    (&*core::ptr::addr_of!(KUSER_PAGE_ALIASES))
        .get(pi)
        .map(|slot| slot.load(Ordering::Acquire))
        .unwrap_or(0)
}

fn kuser_page_alias_stats() -> (usize, usize, u64, u64) {
    unsafe {
        let aliases = &*core::ptr::addr_of!(KUSER_PAGE_ALIASES);
        (
            aliases.len(),
            aliases.capacity(),
            KUSER_PAGE_ALIAS_ALLOCATION_FAILURES.load(Ordering::Relaxed),
            KUSER_PAGE_ALIAS_STORE_FAILURES.load(Ordering::Relaxed),
        )
    }
}
/// Hosted-process DLL VA arena. Images receive stable bases at activation and pack at Windows'
/// 64 KiB granularity. The arena ends at the win32k client window, stays below NLS at 0xA000_0000,
/// and remains inside the existing 0x8000_0000..0xC000_0000 1 GiB PD range. csrsrv activates first
/// and therefore retains its preferred 0x8000_0000 base.
pub const DLL_ARENA_START: u64 = 0x0000_0000_8000_0000;
pub const DLL_ARENA_END: u64 = 0x0000_0000_9800_0000;
pub const DLL_ARENA_PT_COUNT: usize =
    ((DLL_ARENA_END - DLL_ARENA_START) / nt_dll_registry::PAGE_TABLE_SPAN) as usize;
pub const DLL_ARENA_PT_WORDS: usize = (DLL_ARENA_PT_COUNT + 63) / 64;
const _: () = assert!(DLL_ARENA_END == win32k_subsystem::CSRSS_W32_SHARED_VA);
const _: () = assert!(DLL_ARENA_PT_COUNT == 192);
const _: () = assert!(DLL_ARENA_PT_WORDS * 64 >= DLL_ARENA_PT_COUNT);
const _: () = assert!(DLL_ARENA_START >= 0x8000_0000 && DLL_ARENA_END <= 0xC000_0000);
const _: () = assert!(
    win32k_subsystem::CSRSS_W32_SHARED_VA + win32k_subsystem::WIN32K_HEAP_FRAMES * 0x1000
        <= 0xA000_0000
);

#[derive(Clone, Copy)]
pub(crate) struct DllArenaPagingStats {
    pub records: usize,
    pub capacity: usize,
    pub growths: u64,
    pub allocation_failures: u64,
}

#[derive(Clone, Copy)]
pub(crate) struct DllPeStoreStats {
    pub records: usize,
    pub capacity: usize,
    pub growths: u64,
    pub allocation_failures: u64,
}

pub(crate) struct DllPeStore {
    entries: Vec<Option<nt_pe_loader::PeFile<'static>>>,
    growths: u64,
    allocation_failures: u64,
}

impl DllPeStore {
    pub(crate) const fn new() -> Self {
        Self {
            entries: Vec::new(),
            growths: 0,
            allocation_failures: 0,
        }
    }

    pub(crate) fn reset(&mut self) {
        self.entries.clear();
        self.growths = 0;
        self.allocation_failures = 0;
    }

    pub(crate) fn ensure_slot(&mut self, slot: usize) -> Result<bool, ()> {
        if slot < self.entries.len() {
            return Ok(false);
        }
        let Some(target_len) = slot.checked_add(1) else {
            self.allocation_failures = self.allocation_failures.saturating_add(1);
            return Err(());
        };
        let old_capacity = self.entries.capacity();
        let needed = target_len - self.entries.len();
        if self.entries.try_reserve(needed).is_err() {
            self.allocation_failures = self.allocation_failures.saturating_add(1);
            return Err(());
        }
        if self.entries.capacity() != old_capacity {
            self.growths = self.growths.saturating_add(1);
        }
        while self.entries.len() <= slot {
            self.entries.push(None);
        }
        Ok(true)
    }

    pub(crate) fn set(
        &mut self,
        slot: usize,
        pe: Option<nt_pe_loader::PeFile<'static>>,
    ) -> Result<(), ()> {
        self.ensure_slot(slot)?;
        self.entries[slot] = pe;
        Ok(())
    }

    pub(crate) fn as_slice(&self) -> &[Option<nt_pe_loader::PeFile<'static>>] {
        &self.entries
    }

    pub(crate) fn stats(&self) -> DllPeStoreStats {
        DllPeStoreStats {
            records: self.entries.len(),
            capacity: self.entries.capacity(),
            growths: self.growths,
            allocation_failures: self.allocation_failures,
        }
    }
}

#[derive(Clone, Copy)]
struct DllArenaPagingRecord {
    pi: usize,
    pd_created: bool,
    pt_bits: [u64; DLL_ARENA_PT_WORDS],
}

impl DllArenaPagingRecord {
    const fn new(pi: usize) -> Self {
        Self {
            pi,
            pd_created: false,
            pt_bits: [0; DLL_ARENA_PT_WORDS],
        }
    }
}

pub(crate) struct DllArenaPagingState {
    records: Vec<DllArenaPagingRecord>,
    growths: u64,
    allocation_failures: u64,
}

impl DllArenaPagingState {
    pub(crate) const fn new() -> Self {
        Self {
            records: Vec::new(),
            growths: 0,
            allocation_failures: 0,
        }
    }

    pub(crate) fn reset(&mut self) {
        self.records.clear();
        self.growths = 0;
        self.allocation_failures = 0;
    }

    fn index_for(&self, pi: usize) -> Option<usize> {
        self.records.iter().position(|record| record.pi == pi)
    }

    fn ensure_index(&mut self, pi: usize) -> Result<usize, u32> {
        if let Some(index) = self.index_for(pi) {
            return Ok(index);
        }
        let old_capacity = self.records.capacity();
        if self.records.try_reserve(1).is_err() {
            self.allocation_failures = self.allocation_failures.saturating_add(1);
            return Err(nt_address_space::STATUS_INSUFFICIENT_RESOURCES);
        }
        if self.records.capacity() != old_capacity {
            self.growths = self.growths.saturating_add(1);
        }
        self.records.push(DllArenaPagingRecord::new(pi));
        Ok(self.records.len() - 1)
    }

    pub(crate) fn reserve_process(&mut self, pi: usize) -> Result<(), u32> {
        self.ensure_index(pi).map(|_| ())
    }

    pub(crate) fn pd_created(&self, pi: usize) -> bool {
        self.index_for(pi)
            .map(|index| self.records[index].pd_created)
            .unwrap_or(false)
    }

    pub(crate) fn mark_pd_created(&mut self, pi: usize) -> Result<(), u32> {
        let index = self.ensure_index(pi)?;
        self.records[index].pd_created = true;
        Ok(())
    }

    pub(crate) fn pt_created(&self, pi: usize, pt_index: usize) -> bool {
        if pt_index >= DLL_ARENA_PT_COUNT {
            return false;
        }
        let Some(index) = self.index_for(pi) else {
            return false;
        };
        let word = pt_index / 64;
        let bit = 1u64 << (pt_index % 64);
        self.records[index].pt_bits[word] & bit != 0
    }

    pub(crate) fn mark_pt_created(&mut self, pi: usize, pt_index: usize) -> Result<(), u32> {
        if pt_index >= DLL_ARENA_PT_COUNT {
            return Err(nt_address_space::STATUS_INVALID_PARAMETER_3);
        }
        let index = self.ensure_index(pi)?;
        let word = pt_index / 64;
        let bit = 1u64 << (pt_index % 64);
        self.records[index].pt_bits[word] |= bit;
        Ok(())
    }

    pub(crate) fn clear_process(&mut self, pi: usize) {
        if let Some(index) = self.index_for(pi) {
            self.records.swap_remove(index);
        }
    }

    pub(crate) fn stats(&self) -> DllArenaPagingStats {
        DllArenaPagingStats {
            records: self.records.len(),
            capacity: self.records.capacity(),
            growths: self.growths,
            allocation_failures: self.allocation_failures,
        }
    }
}

/// Slots PINNED (eagerly loaded + registered at BOOT, NOT demand-loaded). The FLAGGED IRREDUCIBLE
/// MINIMUM — every OTHER System32 DLL demand-loads on the fly. Two reasons a DLL must be pinned:
///   • **csrsrv** (slot 0) — needs base 0x8000_0000 (its preferred ImageBase → relocation delta 0 →
///     byte-identical shared text, loader never relocates it). Demand-load assigns slots in
///     loader-request order, which can't guarantee csrsrv lands at slot 0.
///   • **the `_vista` forwarder DLLs + ws2help** — these are loaded by ntdll's loader via the
///     FORWARDER path in `LdrpSnapThunk`/`ldrpe.c` (e.g. advapi32 exports `RegDeleteTreeW` as a
///     forwarder to `advapi32_vista.RegDeleteTreeW`). That forwarder resolution can fail BEFORE it
///     ever reaches NtOpenFile (SxS/actctx redirection returns 0xC0000034 with no implicit act ctx),
///     so the demand-load hook (which fires on the NtOpenFile resolve-miss) never sees the request →
///     the snap fails fatally (observed: "Failed to snap advapi32_vista.dll!RegDeleteTreeW for
///     rpcrt4.dll" → NtRaiseHardError). Pre-registering them means the loader finds them already
///     loaded (`LdrpCheckForLoadedDll` hits) and skips the fragile forwarder-open path. This is a
///     loader limitation, not a demand-load bug — documented pin, not a maintained content list.
/// Every leaf DLL (kernel32/user32/gdi32/advapi32/rpcrt4/msvcrt/ws2_32/basesrv/winsrv + lsass'
/// lsasrv/samsrv/msv1_0 + all P5+ binaries) demand-loads with NO edit here.
pub const DLL_PIN_COUNT: usize = 4;
/// Buffer for the generated ntdll.dll, shared host<->exec in its own 2 MiB page table.
pub const NTDLLBUF_VADDR: u64 = 0x0000_0100_1440_0000;
pub const NTDLLBUF_FRAMES: u64 = 480; // 1.875 MiB, with growth headroom below one PT window
/// NLS code-page tables (c_1252.nls/c_437.nls/l_intl.nls), shared host<->exec. They live in the
/// shared-input 2 MiB region (0xA0_0000-0xC0_0000). spawn_sec_image later shares these frames into smss + points the PEB NLS
/// fields at them so RtlInitNlsTables/RtlUnicodeToMultiByteN work.
pub const NLS_ANSI_VADDR: u64 = 0x0000_0100_10B0_0000; // c_1252.nls (66082 B = 17 pages)
pub const NLS_ANSI_FRAMES: u64 = 20;
pub const NLS_OEM_VADDR: u64 = 0x0000_0100_10B2_0000; // c_437.nls (66594 B = 17 pages)
pub const NLS_OEM_FRAMES: u64 = 20;
pub const NLS_CASE_VADDR: u64 = 0x0000_0100_10B4_0000; // l_intl.nls (4870 B = 2 pages)
pub const NLS_CASE_FRAMES: u64 = 4;
/// c_20127.nls (US-ASCII, CP20127; 66082 B = 17 pages) — csrss's Win32 client stack maps the named
/// section \Nls\NlsSectionCP20127 during a DllMain. Shares the NTDLLBUF 0xA0-0xC0 page table so it
/// needs no extra PT. Placed past the SYSTEM hive buffer.
pub const NLS_20127_VADDR: u64 = 0x0000_0100_10B9_0000;
pub const NLS_20127_FRAMES: u64 = 20;
/// The real ReactOS SYSTEM registry hive (::ROSSYS.HIV, ~204 KiB regf), read off the disk by the
/// isolated storage host into these shared frames; the executive parses it with nt-hive-regf so
/// the NT registry serves smss's real config. Shares the 0xA0-0xC0 page table (past the NLS bufs).
pub const HIVEBUF_VADDR: u64 = 0x0000_0100_10B5_0000;
pub const HIVEBUF_FRAMES: u64 = 64; // 256 KiB
/// The real ReactOS **SECURITY** hive (`\reactos\system32\config\security`, 8 KiB regf) — the LSA
/// policy database's on-disk backing store. Read BY PATH off the image by the isolated storage
/// host, exactly like the SYSTEM hive, and mounted read-only at `\Registry\Machine\SECURITY`.
/// Shares the 0xA0-0xC0 input page table (placed past NLS_20127).
pub const SECHIVEBUF_VADDR: u64 = 0x0000_0100_10BB_0000;
pub const SECHIVEBUF_FRAMES: u64 = 8; // 32 KiB (the staged hive is 8 KiB)
/// The real ReactOS **SAM** hive (`\reactos\system32\config\sam`, 8 KiB regf), mounted read-only at
/// `\Registry\Machine\SAM`. Same by-path staging as SECURITY.
pub const SAMHIVEBUF_VADDR: u64 = 0x0000_0100_10BB_8000;
pub const SAMHIVEBUF_FRAMES: u64 = 8; // 32 KiB
const _: () = assert!(SECHIVEBUF_VADDR + SECHIVEBUF_FRAMES * 0x1000 <= SAMHIVEBUF_VADDR);
const _: () = assert!(SAMHIVEBUF_VADDR + SAMHIVEBUF_FRAMES * 0x1000 <= 0x0000_0100_10BC_0000);
/// The real ReactOS **DEFAULT** hive (`\reactos\system32\config\default`, **139264 B** regf) — the
/// genuine `HKEY_USERS\.DEFAULT` prototype hive (`$$$PROTO.HIV`). Two things need it, and both are
/// what a real NT boot does with it:
///   * it is mounted at `\Registry\User\.Default`, exactly as `CmpInitializeHiveList` mounts it, so
///     `userenv!CreateUserHive`'s `RegOpenKeyExW(HKEY_USERS, L".Default")` resolves; and
///   * it is the file SETUP copies to become a new user's `ntuser.dat` — so it is the source the
///     executive uses to PROVISION `C:\Profiles\Default User\ntuser.dat` (see `writable_fs`).
/// 34 pages, which fits the leftover of the shared 0xA0-0xC0 input page table above SAMHIVEBUF.
pub const DEFHIVEBUF_VADDR: u64 = 0x0000_0100_10BC_0000;
pub const DEFHIVEBUF_FRAMES: u64 = 40; // 160 KiB (the staged hive is 139264 B = 34 pages)
const _: () = assert!(DEFHIVEBUF_FRAMES * 0x1000 >= 139_264);
const _: () = assert!(DEFHIVEBUF_VADDR + DEFHIVEBUF_FRAMES * 0x1000 <= 0x0000_0100_10C0_0000);
const _: () = assert!(NTDLLBUF_FRAMES * 0x1000 <= 0x20_0000);
/// The real ReactOS **SOFTWARE** hive (`\reactos\system32\config\software`, **471040 B** regf) —
/// the HKLM\Software backing store, mounted read-only at `\Registry\Machine\SOFTWARE`. Same by-path
/// staging as SECURITY/SAM, but it is ~57x their size (115 pages), so it does NOT fit in the
/// leftover of the shared 0xA0-0xC0 input page table: it gets its OWN 2 MiB window + dedicated PT
/// below the process-mirror region (0x1200_0000).
pub const SWHIVEBUF_VADDR: u64 = 0x0000_0100_10E0_0000;
pub const SWHIVEBUF_FRAMES: u64 = 128; // 512 KiB (the staged hive is 471040 B = 115 pages)
const _: () = assert!(SWHIVEBUF_FRAMES * 0x1000 >= 471_040);
const _: () = assert!(SWHIVEBUF_VADDR & 0x1F_FFFF == 0); // 2 MiB aligned -> exactly one PT window
const _: () = assert!(SWHIVEBUF_FRAMES * 0x1000 <= 0x20_0000);
/// The same NLS frames shared into smss (own PT at the 0xE0_0000 2 MiB region). The PEB's
/// AnsiCodePageData(@0x58)/OemCodePageData(@0x60)/UnicodeCaseTableData(@0x68) point here.
pub const NLS_SMSS_ANSI_VA: u64 = 0x0000_0100_00E0_0000;
pub const NLS_SMSS_OEM_VA: u64 = 0x0000_0100_00E2_0000;
pub const NLS_SMSS_CASE_VA: u64 = 0x0000_0100_00E4_0000;
/// The IOVA we grant the AHCI for its DMA frame. Once VT-d confinement is on, the HBA is
/// programmed with this address; VT-d maps it to the DMA frame and NOTHING else.
pub const AHCI_IOVA: u64 = 0x1000;
pub const IPCBUF_VADDR: u64 = 0x0000_0100_105F_B000;
const _: () =
    assert!(STORAGE_SHARED_END <= IPCBUF_VADDR || IPCBUF_VADDR + 0x1000 <= STORAGE_SHARED_VADDR);
const ROOT_DMA_PROOF_ID_VALUE: u32 = 0x444d_4131; // "DMA1"
const ROOT_DMA_PROOF_INTERRUPT_STATUS_OFFSET: u64 = 0x08;
const ROOT_DMA_PROOF_INTERRUPT_ACK_OFFSET: u64 = 0x0c;

pub const STACK_FRAMES: u64 = 4; // 16 KiB
pub const RING_LEN: usize = 4096;
pub const REP_DATA_LEN: usize = 4096;
const QLEN: u32 = 8;
/// Read/write, non-executable — data regions (heap, stack, rings, buffers).
const RW_NX: u64 = 3 | PAGE_EXECUTE_NEVER;

// A spawned component's own CNode cptrs.
pub const CT_PML4: u64 = 2;
pub const CT_N_SUB: u64 = 3;
pub const CT_N_COMP: u64 = 4;
pub const CT_FAULT: u64 = 6; // a user thread's own cap to its fault endpoint
pub const CT_WAIT_NTFN: u64 = 7; // a waiter thread's cap to the wait notification it parks on
pub const CT_IO_PORT_BASE: u64 = 8; // first hosted hardware-driver I/O-port cap slot
pub const CT_IO_PORT_CAPACITY: u64 = nt_pnp::PCI_NUM_BARS as u64 + 1;
pub const CT_IRQ_NTFN: u64 = 3; // the ISR host's cap to the IRQ notification
pub const CT_RESULT_NTFN: u64 = 4; // the ISR host's cap to the result notification
const CN_RADIX: u32 = 5;
const CN_GUARD_BADGE: u64 = 59;
/// Badge the isolated ISR host signals after it handles the interrupt.
const ISR_DONE_BADGE: u64 = 0x80;

// `SysReplyRecv` — reply to a pending fault + receive the next, in one syscall.
const SYS_REPLY_RECV: i64 = -2;
pub const SYS_NB_SEND_RECV: i64 = -3;
pub const SYS_NB_RECV: i64 = -8;
pub(crate) const SYS_REPLY_HANDOFF_MAGIC: u64 = 0x4e54_4f53_5245_5431;
/// `X86IRQIssueIRQHandlerIOAPIC` invocation label — issues an IRQ-handler cap AND
/// programs the IOAPIC redirection-table entry for `pin` → vector+PIC1_VECTOR_BASE.
const LBL_X86_IRQ_ISSUE_IOAPIC: u64 = 64;
/// Badge for the IRQ notification, so a delivered interrupt is distinguishable from
/// "not signalled" (badge 0) when we poll.
const IRQ_BADGE: u64 = 0x40;
/// The user-visible IRQ/vector (a legacy-range stub the kernel routes through
/// irq{V}_entry → handle_interrupt(V)); the HPET's IOAPIC pin is chosen separately.
const IRQ_VECTOR: u64 = 11;

// x86 I/O-port invocation labels + the IOPortControl cap slot (canonical slot 7).
const SLOT_IO_PORT_CONTROL: u64 = 7;
const LBL_IOPORT_CONTROL_ISSUE: u64 = 57;
const LBL_IOPORT_IN16: u64 = 59;
const LBL_IOPORT_IN32: u64 = 60;
const LBL_IOPORT_OUT16: u64 = 62;
const LBL_IOPORT_OUT32: u64 = 63;
// PCI configuration-space access ports (0xCF8 address, 0xCFC data).
const PCI_CONFIG_ADDR: u16 = 0xCF8;
const PCI_CONFIG_DATA: u16 = 0xCFC;

// VT-d confined-DMA (Phase 2): map a driver's DMA frame into a device's IO address space
// so the device can only DMA into frames we granted.
const LBL_X86_PAGE_GET_ADDRESS: u64 = 54; // returns a frame cap's physical address
const LBL_X86_IO_PAGE_TABLE_MAP: u64 = 49; // install a VT-d IO page table (builds context)
const LBL_X86_PAGE_MAP_IO: u64 = 53; // map a frame at an IOVA in a device's IO space
const OBJ_X86_IO_PAGE_TABLE: u64 = 13; // seL4_X86_IOPageTableObject
const SLOT_IO_SPACE: u64 = 8; // seL4_CapIOSpace — the master IO-space cap in the root CNode
                              // Per-device bus-master DMA aperture. Common buffers and transient map-register bounce mappings
                              // share this IOMMU-confined window; IOVA 0 stays invalid, and the rest fits under one x86 IO
                              // page-table span so every hosted PCI function can use the same per-domain address range.
const HOSTED_PCI_DMA_WINDOW_IOVA: u64 = 0x1000;
const HOSTED_PCI_DMA_WINDOW_PAGES: u64 = 68;
const HOSTED_PCI_DMA_WINDOW_LEN: u64 = HOSTED_PCI_DMA_WINDOW_PAGES * 0x1000;
const _: () = assert!(HOSTED_PCI_DMA_WINDOW_IOVA + HOSTED_PCI_DMA_WINDOW_LEN <= 0x20_0000);
const HOSTED_BOOT_FRAMEBUFFER_EAGER_MMIO_PAGES: u64 = 32;
/// Driver-host VSpace: where the executive maps the CM_RESOURCE_LIST + common-buffer
/// descriptor (also mapped at the same vaddr in the host, aliasing the frame).
pub const RESLIST_VADDR: u64 = 0x0000_0100_105F_D000;
const _: () =
    assert!(STORAGE_SHARED_END <= RESLIST_VADDR || RESLIST_VADDR + 0x1000 <= STORAGE_SHARED_VADDR);
/// The IOAPIC pins PCI INTx routes to on q35 (GSI 16..23) — the NIC's exact pin is
/// chipset-routed, so we cover them all (edge-triggered, one delivery per assertion).
const Q35_PCI_INTX_IOAPIC_ROUTE_MASK: u32 = 0x00FF_0000;
const Q35_PCI_INTX_ROUTES: nt_pnp::PciIntxRoutingTable =
    nt_pnp::PciIntxRoutingTable::new(0, [Some(16), Some(17), Some(18), Some(19)]);
/// The PIT is routed through GSI 2 on PC/q35 systems. HPET Timer 0 advertises it as legal, but
/// sharing the executive delay timer with the kernel tick gives the delay path false expiries.
const LEGACY_PIT_IOAPIC_ROUTE_MASK: u32 = 1u32 << 2;
const HPET_SHARED_IOAPIC_ROUTE_MASK: u32 =
    Q35_PCI_INTX_IOAPIC_ROUTE_MASK | LEGACY_PIT_IOAPIC_ROUTE_MASK;
const IOAPIC_ROUTE_PIN_NONE: u64 = u64::MAX;

// HPET register offsets (from the mapped MMIO base).
const HPET_GEN_CONF: u64 = 0x10;
const HPET_MAIN_COUNTER: u64 = 0xF0;
const HPET_GEN_INT_STATUS: u64 = 0x20;
const HPET_T0_CONFIG: u64 = 0x100;
/// ★ Timer N Configuration bits (IA-PC HPET spec §2.3.8). These MUST be named: the arm/disarm path
/// used to toggle bit **1** believing it was the enable, which silently left the timer ENABLED
/// FOREVER with a comparator in the past — a ~34 kHz interrupt storm (see `delay_timer_rearm`).
/// `Tn_INT_TYPE_CNF`: 0 = edge-triggered, 1 = level-triggered. The IOAPIC pin this timer is routed
/// to is issued LEVEL (`ioapic_issue_irq_handler(.., level = 1, ..)`), so this stays SET for the
/// timer's whole life — it is a wiring property, never an arm/disarm control.
const HPET_TN_INT_TYPE_LEVEL: u64 = 1 << 1;
/// `Tn_INT_ENB_CNF` — THE arm/disarm bit. Clearing it makes the timer stop delivering, full stop.
const HPET_TN_INT_ENB: u64 = 1 << 2;
const HPET_T0_COMPARATOR: u64 = 0x108;
/// The executive's own IPC buffer VA (from BootInfo) — stages reply message registers 4+.
static IPC_BUFFER: AtomicU64 = AtomicU64::new(0);
/// The executive stack-mirror base for the process whose fault/syscall is currently being serviced.
/// The 2-process service loop sets this at the top of each iteration (smss vs csrss) so the shared
/// smss_stack_read/write helpers read+write the RIGHT process's stack.
static ACTIVE_STACK_MIRROR: AtomicU64 = AtomicU64::new(SMSS_STACK_MIRROR_VA);
static ACTIVE_STACK_BASE: AtomicU64 = AtomicU64::new(STACK_BASE);
static ACTIVE_STACK_SIZE: AtomicU64 = AtomicU64::new(STACK_FRAMES * 0x1000);
/// Process identity and scratch window used when a user range falls outside the fixed mirrors.
static ACTIVE_CLIENT_PI: AtomicU64 = AtomicU64::new(0);
static ACTIVE_SCRATCH_BASE: AtomicU64 = AtomicU64::new(SMSS_SCRATCH_BASE);
/// Executive image-mirror base for the process currently being serviced (smss vs csrss), so the
/// shared copyin path reads import-descriptor DLL names etc. from the RIGHT process's image.
static ACTIVE_IMAGE_MIRROR: AtomicU64 = AtomicU64::new(IMAGE_MIRROR_VA);
/// Executive heap-mirror base for the process currently being serviced, so the copyin path reads
/// heap-resident syscall args (the loader's built-up DLL search paths) from the RIGHT process's heap.
static ACTIVE_HEAP_MIRROR: AtomicU64 = AtomicU64::new(SMSS_HEAP_MIRROR_VA);

// Registry syscalls use the REAL ntdll SSN numbers (Windows 7 SP1 x64) + the real
// `NativeService` classification via `NativeServiceTable`; a real isolated ntdll
// process registers its own numbers the same way (from_numbers(ntdll.syscall_number)).
const NT_CREATE_KEY: u64 = 0x1D; // NtCreateKey(*OBJECT_ATTRIBUTES)
const NT_QUERY_VALUE_KEY: u64 = 0x18; // NtQueryValueKey(*OBJECT_ATTRIBUTES) → value in RAX
const NT_SET_VALUE_KEY: u64 = 0x5D; // NtSetValueKey(*OBJECT_ATTRIBUTES, value in RDX)
const NT_ALLOCATE_VM: u64 = 0x15; // NtAllocateVirtualMemory(size in R10) → base in RAX
const NT_QUERY_SYSTEM_TIME: u64 = 0x57; // NtQuerySystemTime() → HPET counter in RAX
const NT_CREATE_SECTION: u64 = 0x47; // NtCreateSection(size in R10) → section handle in RAX
const NT_MAP_VIEW: u64 = 0x25; // NtMapViewOfSection(section handle in R10) → view base VA in RAX
const NT_CREATE_THREAD: u64 = 0xA5; // NtCreateThreadEx(start routine in R10) → thread handle in RAX
/// Legacy non-SEC_IMAGE selftest allocation window. Real hosted processes allocate from the
/// per-process VAD arena; these throwaway user-thread tests use the same private-VM base but get only
/// one explicit leaf PT in their VSpace, keeping ad hoc allocations out of hosted stack reservations.
pub const USER_ALLOC_BASE: u64 = SMSS_ALLOC_VA;
pub const USER_ALLOC_WINDOW_SIZE: u64 = 0x0020_0000;
const _: () = {
    assert!(USER_ALLOC_BASE & 0x1f_ffff == 0);
    assert!(USER_ALLOC_WINDOW_SIZE == 0x20_0000);
    assert!(USER_ALLOC_BASE >= SMSS_ALLOC_VA);
    assert!(USER_ALLOC_BASE + USER_ALLOC_WINDOW_SIZE <= PRIVATE_VM_LIMIT);
    assert!(ranges_are_disjoint(
        USER_ALLOC_BASE,
        USER_ALLOC_WINDOW_SIZE,
        HOSTED_MAIN_STACK_ALLOCATION_BASE,
        STACK_BASE + STACK_FRAMES * 0x1000 - HOSTED_MAIN_STACK_ALLOCATION_BASE,
    ));
};

// The Object Manager namespace ops aren't in the `NativeService` enum (a niche
// syscall surface), so they keep synthetic numbers — but now carry a real
// OBJECT_ATTRIBUTES for the by-name variants.
const SSN_OB_CREATE_DIR: u64 = 0x0100; // arg1 = directory index → \Device\Syscall<n>
const SSN_OB_LOOKUP_DIR: u64 = 0x0101; // arg1 = directory index
const SSN_OB_CREATE_BYNAME: u64 = 0x0102; // arg1 = *OBJECT_ATTRIBUTES (a user-supplied path)
const SSN_OB_LOOKUP_BYNAME: u64 = 0x0103; // arg1 = *OBJECT_ATTRIBUTES
                                          // P3 sync objects (custom SSNs; real KEVENT semantics via nt-kernel-exec EventStore).
const SSN_CREATE_EVENT: u64 = 0x0200; // arg1 = kind (0=Notification, 1=Synchronization), arg2 = initial
const SSN_SET_EVENT: u64 = 0x0201; // arg1 = event handle → previous state in RAX
const SSN_RESET_EVENT: u64 = 0x0202; // arg1 = event handle → previous state in RAX
const SSN_WAIT: u64 = 0x0203; // arg1 = handle → 0 (WAIT_OBJECT_0) or 0x102 (WAIT_TIMEOUT)
                              // P3 blocking wait dispatcher — a waiter thread parks on an event until a signaler wakes it.
const SSN_WAIT_BLOCK: u64 = 0x0210; // waiter: arg1 = event → 0 (signaled) or 0x102 (must block)
const SSN_SET_WAKE: u64 = 0x0211; // signaler: arg1 = event → set it + signal the wait notification
const SSN_DONE_A: u64 = 0x0212; // waiter reports done
const SSN_DONE_B: u64 = 0x0213; // signaler reports done
const BLOCK_EVENT_KEY: u64 = 0x9000; // the fixed event both threads reference
const SSN_DONE: u64 = 0x01FF; // arg1 = verdict (1 = all passed)

