pub(crate) static WINLOGON_DIALOG_MODAL_COMPLETED: AtomicU64 = AtomicU64::new(0);
pub(crate) static WINLOGON_DIALOG_MODAL_PAINTS: AtomicU64 = AtomicU64::new(0);
