/// ★ BYPASS SWITCH for the headless credential keystrokes. Set to `false` and the logon dialog is
/// left exactly as it was before this batch (painted, parked in its blocking `GetMessage`) — the
/// `exec_msgina_credential_*` specs then FAIL, which is the proof they assert a REAL advance.
const CREDENTIAL_INJECTION_ENABLED: bool = true;
static mut WINLOGON_CREDENTIAL_INJECTION: nt_user_callback::CredentialInjectionSequence =
    nt_user_callback::CredentialInjectionSequence::new();
pub(crate) static WINLOGON_CRED_USERNAME_HWND: AtomicU64 = AtomicU64::new(0);
pub(crate) static WINLOGON_CRED_PASSWORD_HWND: AtomicU64 = AtomicU64::new(0);
pub(crate) static WINLOGON_CRED_OK_HWND: AtomicU64 = AtomicU64::new(0);
pub(crate) static WINLOGON_CRED_POSTED_CHARS: AtomicU64 = AtomicU64::new(0);
pub(crate) static WINLOGON_CRED_POSTED_RETURN: AtomicU64 = AtomicU64::new(0);
pub(crate) static WINLOGON_CRED_RETRIEVED_CHARS: AtomicU64 = AtomicU64::new(0);
pub(crate) static WINLOGON_CRED_RETRIEVED_RETURN: AtomicU64 = AtomicU64::new(0);
pub(crate) static WINLOGON_CRED_TEXT_READBACKS: AtomicU64 = AtomicU64::new(0);
pub(crate) static WINLOGON_CRED_ROUTED_GET_MESSAGES: AtomicU64 = AtomicU64::new(0);
pub(crate) static WINLOGON_CRED_ERRORS: AtomicU64 = AtomicU64::new(0);
/// Native (non-win32k) syscalls winlogon issued AFTER the RETURN key was delivered — the
/// `WM_COMMAND(IDOK)` → `LogonDialogProc` → `DoLogon` → `DoLoginTasks` tail.
pub(crate) static WINLOGON_CRED_POST_RETURN_SSNS: AtomicU64 = AtomicU64::new(0);
/// Set when winlogon's post-credential `NtConnectPort` names `\LsaAuthenticationPort` — msgina's
/// `DoLogon → DoLoginTasks → ConnectToLsa → LsaRegisterLogonProcess`, i.e. the REAL credential
/// validation reaching lsass. Only reachable if `DoLogon`'s own `GetTextboxText` reads found a
/// non-empty user name and domain in the real controls.
pub(crate) static WINLOGON_CRED_LSA_CONNECT: AtomicU64 = AtomicU64::new(0);

/// Case-insensitive compare of an NT object-name (UTF-16) against an ASCII literal. LPC object
/// names follow the object manager's case-insensitive lookup contract.
pub(crate) fn lpc_name_is(name16: &[u16], ascii: &[u8]) -> bool {
    name16.len() == ascii.len()
        && name16
            .iter()
            .zip(ascii.iter())
            .all(|(unit, byte)| {
                u8::try_from(*unit).is_ok_and(|unit| unit.eq_ignore_ascii_case(byte))
            })
}

unsafe fn winlogon_credential_load() -> nt_user_callback::CredentialInjectionSequence {
    core::ptr::read(core::ptr::addr_of!(WINLOGON_CREDENTIAL_INJECTION))
}

unsafe fn winlogon_credential_store(state: nt_user_callback::CredentialInjectionSequence) {
    core::ptr::write(
        core::ptr::addr_of_mut!(WINLOGON_CREDENTIAL_INJECTION),
        state,
    );
    WINLOGON_CRED_USERNAME_HWND.store(state.username_hwnd(), Ordering::Relaxed);
    WINLOGON_CRED_POSTED_CHARS.store(state.posted_chars() as u64, Ordering::Relaxed);
    WINLOGON_CRED_POSTED_RETURN.store(state.is_injected() as u64, Ordering::Relaxed);
    WINLOGON_CRED_RETRIEVED_CHARS.store(state.retrieved_chars() as u64, Ordering::Relaxed);
    WINLOGON_CRED_RETRIEVED_RETURN.store(state.retrieved_return() as u64, Ordering::Relaxed);
    WINLOGON_CRED_TEXT_READBACKS.store(state.text_readbacks() as u64, Ordering::Relaxed);
}

/// Has the credential shim already started typing? (Gates the "dialog destroyed" branch: once the
/// RETURN key has been delivered, a destroyed IDD_LOGON is `EndDialog` — success, not an error.)
pub(crate) unsafe fn winlogon_credential_started() -> bool {
    winlogon_credential_load().username_hwnd() != 0
}

/// A `MSG` the REAL `GetMessageW`/`PeekMessageW` just handed to winlogon — count the injected
/// keystrokes that genuinely came back out of win32k's queue.
pub(crate) unsafe fn winlogon_credential_observe_retrieved(hwnd: u64, message: u32, wparam: u64) {
    let mut state = winlogon_credential_load();
    if state.observe_retrieved(hwnd, message, wparam) {
        winlogon_credential_store(state);
        if message == nt_user_callback::WM_KEYDOWN {
            print_str(
                b"[cred-inject] real queue delivered VK_RETURN to the IDD_LOGON edit control\n",
            );
        } else if state.retrieved_chars() as usize == nt_user_callback::LOGON_USERNAME.len() {
            print_str(b"[cred-inject] real queue delivered all ");
            print_u64(state.retrieved_chars() as u64);
            print_str(b" injected WM_CHARs\n");
        }
    }
}

/// The credential text READ BACK through the real GDI render path: the single-line edit control
/// paints itself with `EDIT_PaintText → TextOutW → NtGdiExtTextOutW(hdc, x, y, opts, rc, es->text,
/// count, …)`. Seeing our exact user name in that call's string argument is proof the REAL edit
/// control's REAL text buffer holds what the injected keystrokes typed.
pub(crate) unsafe fn winlogon_credential_observe_text_out(string: u64, count: u64) {
    let expected = &nt_user_callback::LOGON_USERNAME;
    if string == 0 || count as usize != expected.len() {
        return;
    }
    let mut bytes = [0u8; 2 * nt_user_callback::LOGON_USERNAME.len()];
    if !img_spawn::smss_copyin(string, &mut bytes) {
        return;
    }
    winlogon_credential_observe_text_bytes(&bytes, count, b"NtGdiExtTextOutW");
}

/// The same READ-BACK, from UTF-16 bytes already in the executive's hands. `via` names the transport
/// the render request arrived on, because there are now two REAL ones: a dispatched
/// `NtGdiExtTextOutW`, and a `GdiBCTextOut` record in the caller's own `GdiTebBatch` (which
/// `ke_gdi_flush_user_batch` reads through the executive's TEB alias). Both carry the SAME evidence —
/// the live `EDITSTATE.text` buffer the edit control renders — so the assertion is about the
/// control's content, not about which of gdi32's two code paths happened to carry it.
pub(crate) unsafe fn winlogon_credential_observe_text_bytes(bytes: &[u8], count: u64, via: &[u8]) {
    let expected = &nt_user_callback::LOGON_USERNAME;
    if count as usize != expected.len() || bytes.len() < 2 * expected.len() {
        return;
    }
    for (index, unit) in expected.iter().enumerate() {
        if u16::from_le_bytes([bytes[index * 2], bytes[index * 2 + 1]]) != *unit {
            return;
        }
    }
    let mut state = winlogon_credential_load();
    if state.text_readbacks() == 0 {
        print_str(b"[cred-inject] IDD_LOGON edit control RENDERED the injected user name (");
        print_u64(count);
        print_str(b" chars via ");
        print_str(via);
        print_str(b")\n");
    }
    state.record_text_readback();
    winlogon_credential_store(state);
}

/// Drive the headless credential keystrokes at the dialog's blocking `GetMessageW`.
///
/// Returns `true` when that `GetMessage` may be ROUTED into win32k (the queue is provably
/// non-empty because keystrokes were just posted), `false` when it must be parked.
pub(crate) unsafe fn winlogon_credential_injection_route(
    client: win32k_glue::Win32kClientContext,
) -> bool {
    if !CREDENTIAL_INJECTION_ENABLED {
        return false;
    }
    let dialog = WINLOGON_IDD_LOGON_HWND.load(Ordering::Relaxed);
    let mut state = winlogon_credential_load();
    if state.username_hwnd() == 0 {
        // ── PHASE 1: resolve the REAL controls (GetDlgItem over win32k's live child list) and
        // type the user name as genuine WM_CHARs through the REAL NtUserPostMessage.
        print_logon_dialog_children();
        let username = winlogon_dialog_control_hwnd(nt_user_callback::IDC_LOGON_USERNAME);
        WINLOGON_CRED_PASSWORD_HWND.store(
            winlogon_dialog_control_hwnd(nt_user_callback::IDC_LOGON_PASSWORD),
            Ordering::Relaxed,
        );
        WINLOGON_CRED_OK_HWND.store(
            winlogon_dialog_control_hwnd(nt_user_callback::IDOK),
            Ordering::Relaxed,
        );
        if state.begin(username, dialog).is_err() {
            print_str(
                b"[cred-inject] could not resolve IDC_LOGON_USERNAME in the real child list\n",
            );
            WINLOGON_CRED_ERRORS.fetch_add(1, Ordering::Relaxed);
            return false;
        }
        winlogon_credential_store(state);
        print_str(b"[cred-inject] typing the user name into the real edit control hwnd=0x");
        print_hex(username as u32);
        print_str(b" through NtUserPostMessage(WM_CHAR)\n");
        for (index, unit) in nt_user_callback::LOGON_USERNAME.iter().enumerate() {
            let post = win32k_glue::win32k_dispatch_wide(
                nt_user_callback::NTUSER_POST_MESSAGE_SSN,
                username,
                nt_user_callback::WM_CHAR as u64,
                *unit as u64,
                1, // lParam: repeat count 1, exactly as TranslateMessage synthesizes it
                0,
                &[],
                client,
            );
            if !post.1 || post.0 == 0 || state.record_char_post(username, index).is_err() {
                print_str(b"[cred-inject] WM_CHAR post rejected at index ");
                print_u64(index as u64);
                print_str(b" ret=0x");
                print_hex(post.0 as u32);
                print_str(b"\n");
                WINLOGON_CRED_ERRORS.fetch_add(1, Ordering::Relaxed);
                winlogon_credential_store(state);
                return false;
            }
        }
        winlogon_credential_store(state);
    } else if !state.is_injected() && state.username_ready_for_return() {
        // ── PHASE 2: the real edit control has the user name; press RETURN so the REAL
        // IsDialogMessageW drives WM_COMMAND(IDOK) into LogonDialogProc.
        let username = state.username_hwnd();
        let post = win32k_glue::win32k_dispatch_wide(
            nt_user_callback::NTUSER_POST_MESSAGE_SSN,
            username,
            nt_user_callback::WM_KEYDOWN as u64,
            nt_user_callback::VK_RETURN,
            0x001c_0001, // lParam: repeat count 1, scan code 0x1c (ENTER)
            0,
            &[],
            client,
        );
        if !post.1 || post.0 == 0 || state.record_return_post(username).is_err() {
            print_str(b"[cred-inject] VK_RETURN post rejected ret=0x");
            print_hex(post.0 as u32);
            print_str(b" retrieved-chars=");
            print_u64(state.retrieved_chars() as u64);
            print_str(b"\n");
            WINLOGON_CRED_ERRORS.fetch_add(1, Ordering::Relaxed);
            winlogon_credential_store(state);
            return false;
        }
        print_str(b"[cred-inject] pressed RETURN on the real IDD_LOGON edit control hwnd=0x");
        print_hex(username as u32);
        print_str(b" (readbacks=");
        print_u64(state.text_readbacks() as u64);
        print_str(b")\n");
        winlogon_credential_store(state);
    }
    if state.may_route_get_message() {
        state.record_routed_get_message();
        winlogon_credential_store(state);
        WINLOGON_CRED_ROUTED_GET_MESSAGES.fetch_add(1, Ordering::Relaxed);
        return true;
    }
    false
}

unsafe fn winlogon_dialog_correlation_load() -> nt_user_callback::WinlogonDialogCorrelation {
    core::ptr::read(core::ptr::addr_of!(WINLOGON_DIALOG_CORRELATION))
}

unsafe fn winlogon_dialog_correlation_store(state: nt_user_callback::WinlogonDialogCorrelation) {
    core::ptr::write(core::ptr::addr_of_mut!(WINLOGON_DIALOG_CORRELATION), state);
    WINLOGON_IDD_LOGON_HWND.store(state.idd_logon_hwnd(), Ordering::Relaxed);
    WINLOGON_DIALOG_MODAL_READY.store(state.modal_ready() as u64, Ordering::Relaxed);
}

unsafe fn winlogon_dialog_correlation_commit(
    state: nt_user_callback::WinlogonDialogCorrelation,
    result: Result<(), nt_user_callback::ValidationError>,
) -> bool {
    if result.is_ok() {
        winlogon_dialog_correlation_store(state);
        true
    } else {
        WINLOGON_DIALOG_CORRELATION_ERRORS.fetch_add(1, Ordering::Relaxed);
        false
    }
}

pub(crate) unsafe fn winlogon_dialog_observe_sas_message(
    session: u64,
    hwnd: u64,
    message: u32,
    wparam: u64,
) -> bool {
    if WINLOGON_DIALOG_MODAL_READY.load(Ordering::Relaxed) != 0 {
        return true;
    }
    let mut state = winlogon_dialog_correlation_load();
    if state.sas_hwnd() == 0 {
        if state.latch_sas_window(session, hwnd).is_err() {
            WINLOGON_DIALOG_CORRELATION_ERRORS.fetch_add(1, Ordering::Relaxed);
            return false;
        }
    }
    let result = state.observe_sas_message(session, hwnd, message, wparam);
    winlogon_dialog_correlation_commit(state, result)
}

pub(crate) unsafe fn winlogon_dialog_observe_logged_off(session: u64, state_value: u32) -> bool {
    let mut state = winlogon_dialog_correlation_load();
    if state.logged_off() {
        return true;
    }
    let result = state.observe_logged_off(session, state_value);
    winlogon_dialog_correlation_commit(state, result)
}

pub(crate) unsafe fn winlogon_dialog_capture_idd_logon(
    session: u64,
    hwnd: u64,
    class_atom: u64,
    caption: &[u16],
    top_level: bool,
    winlogon_key_advanced: bool,
) -> bool {
    let was_ready = WINLOGON_DIALOG_MODAL_READY.load(Ordering::Relaxed) != 0;
    let mut state = winlogon_dialog_correlation_load();
    if state.modal_ready() {
        return state.idd_logon_hwnd() == hwnd;
    }
    let result = state.capture_idd_logon(
        session,
        hwnd,
        class_atom,
        caption,
        top_level,
        winlogon_key_advanced,
    );
    let ok = winlogon_dialog_correlation_commit(state, result);
    if ok && !was_ready && state.modal_ready() {
        print_str(b"[dialog-correlation] IDD_LOGON hwnd=");
        print_hex(hwnd as u32);
        print_str(b" modal-ready=1\n");
    }
    ok
}

unsafe fn winlogon_dialog_modal_load() -> nt_user_callback::DialogModalPumpSequence {
    core::ptr::read(core::ptr::addr_of!(WINLOGON_DIALOG_MODAL_PUMP))
}

unsafe fn winlogon_dialog_modal_store(state: nt_user_callback::DialogModalPumpSequence) {
    core::ptr::write(core::ptr::addr_of_mut!(WINLOGON_DIALOG_MODAL_PUMP), state);
    WINLOGON_DIALOG_MODAL_STEPS.store(state.completed_steps() as u64, Ordering::Relaxed);
    WINLOGON_DIALOG_MODAL_COMPLETED.store(state.is_complete() as u64, Ordering::Relaxed);
    WINLOGON_DIALOG_MODAL_PAINTS.store(state.paint_dispatches() as u64, Ordering::Relaxed);
    WINLOGON_DIALOG_MODAL_DRAINED.store(state.is_drained() as u64, Ordering::Relaxed);
}

pub(crate) unsafe fn winlogon_dialog_modal_expected_ssn() -> u64 {
    if WINLOGON_DIALOG_MODAL_READY.load(Ordering::Relaxed) == 0
        || WINLOGON_IDD_LOGON_HWND.load(Ordering::Relaxed) == 0
        || WINLOGON_DIALOG_MODAL_DRAINED.load(Ordering::Relaxed) != 0
    {
        return 0;
    }
    winlogon_dialog_modal_load().expected_ssn().unwrap_or(0)
}

pub(crate) fn winlogon_dialog_modal_thread_matches(badge: u64, tid: u64, message: u64) -> bool {
    if badge != WINLOGON_BADGE || tid == 0 || message == 0 {
        return false;
    }
    let observed_tid = WINLOGON_DIALOG_MODAL_TID.load(Ordering::Relaxed);
    if observed_tid == 0 {
        WINLOGON_DIALOG_MODAL_BADGE.store(badge, Ordering::Relaxed);
        WINLOGON_DIALOG_MODAL_TID.store(tid, Ordering::Relaxed);
        WINLOGON_DIALOG_MODAL_MSG.store(message, Ordering::Relaxed);
        return true;
    }
    WINLOGON_DIALOG_MODAL_BADGE.load(Ordering::Relaxed) == badge
        && observed_tid == tid
        && WINLOGON_DIALOG_MODAL_MSG.load(Ordering::Relaxed) == message
}

/// Match the thread that owns the correlated IDD_LOGON modal pump after its initial message
/// sequence has been established. `MSG *` is per-call scratch storage and user32 may move it when
/// nested callbacks unwind, so it is not part of the pump's stable identity beyond that sequence.
pub(crate) fn winlogon_dialog_modal_thread_is_owner(badge: u64, tid: u64) -> bool {
    badge == WINLOGON_BADGE
        && tid != 0
        && WINLOGON_DIALOG_MODAL_BADGE.load(Ordering::Relaxed) == badge
        && WINLOGON_DIALOG_MODAL_TID.load(Ordering::Relaxed) == tid
}

pub(crate) unsafe fn winlogon_pwnd_for_hwnd(hwnd: u64) -> u64 {
    let ahelist = core::ptr::read_volatile(
        (win32k_subsystem::WIN32K_SHARED_VADDR + win32k_subsystem::SH_SAS_AHELIST) as *const u64,
    );
    if ahelist == 0 || (hwnd & 0xffff) < 0x20 {
        return 0;
    }
    let handles = core::ptr::read_volatile(ahelist as *const u64);
    let count = core::ptr::read_volatile((ahelist + 0x10) as *const u32) as u64;
    let index = ((hwnd & 0xffff) - 0x20) >> 1;
    if handles == 0 || index >= count {
        return 0;
    }
    let entry = handles + index * 0x18;
    if core::ptr::read_volatile((entry + 0x10) as *const u8) != 1
        || core::ptr::read_volatile((entry + 0x12) as *const u16) != (hwnd >> 16) as u16
    {
        return 0;
    }
    core::ptr::read_volatile(entry as *const u64)
}

pub(crate) unsafe fn winlogon_dialog_contains_hwnd(hwnd: u64) -> bool {
    const WND_PARENT_OFFSET: u64 = 0x58;
    let dialog = WINLOGON_IDD_LOGON_HWND.load(Ordering::Relaxed);
    if hwnd == 0 || dialog == 0 {
        return false;
    }
    let mut pwnd = winlogon_pwnd_for_hwnd(hwnd);
    for _ in 0..32 {
        if pwnd == 0 {
            break;
        }
        if core::ptr::read_volatile(pwnd as *const u64) == dialog {
            return true;
        }
        pwnd = core::ptr::read_volatile((pwnd + WND_PARENT_OFFSET) as *const u64);
    }
    false
}

/// `GetDlgItem` against win32k's LIVE window tree.
///
/// user32's `GetDlgItem` enumerates the dialog's child windows (`WIN_ListChildren`) and returns the
/// one whose `GWLP_ID` matches — and `GWLP_ID` *is* `WND.IDMenu`. This walks exactly that list in
/// the desktop heap (`spwndChild` then `spwndNext`), so the handle it returns is the real control's
/// real handle, minted by the real `CreateWindowExW` inside `DIALOG_CreateIndirect`. Offsets are
/// x64 `_WND` (`references/reactos/win32ss/include/ntuser.h:693`); three of them (`state` 0x28,
/// `spwndParent` 0x58, `rcWindow` 0x70) are already cross-checked by the correlation/paint gates.
pub(crate) unsafe fn winlogon_dialog_control_hwnd(control_id: u64) -> u64 {
    const WND_CHILD_OFFSET: u64 = 0x60;
    const WND_NEXT_OFFSET: u64 = 0x48;
    const WND_IDMENU_OFFSET: u64 = 0xd0;
    let dialog = WINLOGON_IDD_LOGON_HWND.load(Ordering::Relaxed);
    let dialog_pwnd = winlogon_pwnd_for_hwnd(dialog);
    if dialog_pwnd == 0 {
        return 0;
    }
    let mut child = core::ptr::read_volatile((dialog_pwnd + WND_CHILD_OFFSET) as *const u64);
    for _ in 0..64 {
        if child == 0 {
            break;
        }
        let hwnd = core::ptr::read_volatile(child as *const u64);
        // Only trust a child whose handle round-trips through win32k's OWN handle table.
        if hwnd != 0
            && winlogon_pwnd_for_hwnd(hwnd) == child
            && core::ptr::read_volatile((child + WND_IDMENU_OFFSET) as *const u64) == control_id
        {
            return hwnd;
        }
        child = core::ptr::read_volatile((child + WND_NEXT_OFFSET) as *const u64);
    }
    0
}

/// One-shot diagnostic: the dialog's real child list (control id -> real HWND), the same walk
/// `winlogon_dialog_control_hwnd` uses. Printed once, when the credential keystrokes are injected.
unsafe fn print_logon_dialog_children() {
    const WND_CHILD_OFFSET: u64 = 0x60;
    const WND_NEXT_OFFSET: u64 = 0x48;
    const WND_IDMENU_OFFSET: u64 = 0xd0;
    let dialog = WINLOGON_IDD_LOGON_HWND.load(Ordering::Relaxed);
    let dialog_pwnd = winlogon_pwnd_for_hwnd(dialog);
    print_str(b"[cred-inject] IDD_LOGON hwnd=0x");
    print_hex(dialog as u32);
    print_str(b" children (id:hwnd):");
    if dialog_pwnd == 0 {
        print_str(b" <no PWND>\n");
        return;
    }
    let mut child = core::ptr::read_volatile((dialog_pwnd + WND_CHILD_OFFSET) as *const u64);
    for _ in 0..64 {
        if child == 0 {
            break;
        }
        print_str(b" ");
        print_u64(core::ptr::read_volatile(
            (child + WND_IDMENU_OFFSET) as *const u64,
        ));
        print_str(b":0x");
        print_hex(core::ptr::read_volatile(child as *const u64) as u32);
        child = core::ptr::read_volatile((child + WND_NEXT_OFFSET) as *const u64);
    }
    print_str(b"\n");
}

pub(crate) unsafe fn winlogon_dialog_modal_target_alive() -> bool {
    const WND_STATE_OFFSET: u64 = 0x28;
    const WNDS_DESTROYED: u32 = 0x8000_0000;
    let pwnd = winlogon_pwnd_for_hwnd(WINLOGON_IDD_LOGON_HWND.load(Ordering::Relaxed));
    pwnd != 0
        && core::ptr::read_volatile((pwnd + WND_STATE_OFFSET) as *const u32) & WNDS_DESTROYED == 0
}

pub(crate) unsafe fn winlogon_dialog_modal_observe(
    ssn: u64,
    result: u64,
    hwnd: u64,
    message: u32,
) -> bool {
    let idd_hwnd = WINLOGON_IDD_LOGON_HWND.load(Ordering::Relaxed);
    if WINLOGON_DIALOG_MODAL_READY.load(Ordering::Relaxed) == 0 || idd_hwnd == 0 {
        print_str(b"[dialog-pump] ERROR observe before correlated dialog\n");
        WINLOGON_DIALOG_MODAL_ERRORS.fetch_add(1, Ordering::Relaxed);
        return false;
    }
    let dialog_paint = message == nt_user_callback::WM_PAINT && winlogon_dialog_contains_hwnd(hwnd);
    let mut state = winlogon_dialog_modal_load();
    let message = if ssn == nt_user_callback::NTUSER_PEEK_MESSAGE_SSN && result == 0 {
        None
    } else if message == nt_user_callback::WM_PAINT && !dialog_paint {
        // A thread-modal pump drains the whole thread queue. Desktop and unrelated-window paints
        // must still be dispatched before an IDD_LOGON paint can become the next queue entry, but
        // they are not evidence that the credential dialog itself painted.
        Some(u32::MAX)
    } else {
        Some(message)
    };
    if state.complete(ssn, result as u32 as i32, message).is_err() {
        print_str(b"[dialog-pump] ERROR invalid completion expected=");
        print_hex(state.expected_ssn().unwrap_or(0) as u32);
        print_str(b" actual=");
        print_hex(ssn as u32);
        print_str(b" result=");
        print_hex(result as u32);
        print_str(b" message=");
        print_hex(message.unwrap_or(0) as u32);
        print_str(b"\n");
        WINLOGON_DIALOG_MODAL_ERRORS.fetch_add(1, Ordering::Relaxed);
        return false;
    }
    winlogon_dialog_modal_store(state);
    if let Some(message) = message {
        if message == nt_user_callback::WM_PAINT && dialog_paint && hwnd != 0 {
            WINLOGON_DIALOG_MODAL_HWND.store(hwnd, Ordering::Relaxed);
            WINLOGON_DIALOG_MODAL_MESSAGE.store(message as u64, Ordering::Relaxed);
        }
    }
    print_str(b"[dialog-pump] completed step=");
    print_u64(state.completed_steps() as u64);
    print_str(b"/3 SSN=");
    print_hex(ssn as u32);
    print_str(b" ret=");
    print_hex(result as u32);
    if let Some(message) = message {
        print_str(b" hwnd=");
        print_hex(hwnd as u32);
        print_str(b" message=");
        print_hex(message);
    }
    if state.is_complete() {
        print_str(b" paints=");
        print_u64(state.paint_dispatches() as u64);
    }
    if state.is_drained() {
        print_str(b" queue-drained=1");
    }
    print_str(b"\n");
    true
}

#[inline(never)]
unsafe fn verify_logon_dialog_framebuffer() -> bool {
    const WND_RC_WINDOW_OFFSET: u64 = 0x70;
    const DESKTOP_COLOR: u32 = 0x003a_6ea5;
    let Some((width, height, scanline, _size_bytes)) = active_framebuffer_geometry() else {
        return false;
    };
    if scanline % 4 != 0 {
        return false;
    }
    let hwnd = WINLOGON_IDD_LOGON_HWND.load(Ordering::Relaxed);
    let pwnd = winlogon_pwnd_for_hwnd(hwnd);
    if pwnd == 0 {
        return false;
    }
    let mut rect = [0i32; 4];
    for (index, value) in rect.iter_mut().enumerate() {
        *value = core::ptr::read_volatile(
            (pwnd + WND_RC_WINDOW_OFFSET + index as u64 * 4) as *const i32,
        );
    }
    let width_i32 = width as i32;
    let height_i32 = height as i32;
    let left = rect[0].clamp(0, width_i32) as u64;
    let top = rect[1].clamp(0, height_i32) as u64;
    let right = rect[2].clamp(left as i32, width_i32) as u64;
    let bottom = rect[3].clamp(top as i32, height_i32) as u64;
    let mut pixels = 0u64;
    let mut non_desktop = 0u64;
    let mut colors = [0u32; 16];
    let mut color_count = 0usize;
    let fb = framebuffer_scanout_va() as *const u32;
    let stride_pixels = scanline / 4;
    for y in top..bottom {
        for x in left..right {
            let pixel = core::ptr::read_volatile(fb.add((y * stride_pixels + x) as usize));
            pixels += 1;
            non_desktop += (pixel != DESKTOP_COLOR) as u64;
            if color_count < colors.len() && !colors[..color_count].contains(&pixel) {
                colors[color_count] = pixel;
                color_count += 1;
            }
        }
    }
    WINLOGON_DIALOG_FB_PIXELS.store(pixels, Ordering::Relaxed);
    WINLOGON_DIALOG_FB_NON_DESKTOP.store(non_desktop, Ordering::Relaxed);
    WINLOGON_DIALOG_FB_COLORS.store(color_count as u64, Ordering::Relaxed);
    print_str(b"[winlogon] IDD_LOGON framebuffer rect=");
    for value in rect {
        print_u64(value as u32 as u64);
        print_str(b" ");
    }
    print_str(b"pixels=");
    print_u64(pixels);
    print_str(b" non-desktop=");
    print_u64(non_desktop);
    print_str(b" colors>=");
    print_u64(color_count as u64);
    print_str(b"\n");
    WINLOGON_DIALOG_MODAL_DRAINED.load(Ordering::Relaxed) != 0
        && pixels >= 4096
        && non_desktop > pixels / 20
        && color_count >= 4
        && WINLOGON_DIALOG_MODAL_PAINTS.load(Ordering::Relaxed) >= 2
        && WINLOGON_DIALOG_MODAL_HWND.load(Ordering::Relaxed) != hwnd
}

/// ═══ Logon-dialog evidence LATCH ═══════════════════════════════════════════════════════════════
///
/// Three of the msgina gates resolve LIVE window state: the modal window's membership in winlogon's
/// window list, the username edit control's membership, and the framebuffer rectangle of the
/// IDD_LOGON window itself. All three are only resolvable **while the dialog exists** — and a
/// SUCCESSFUL logon destroys it (`EndDialog(WLX_SAS_ACTION_LOGON)`).
///
/// So they are measured at the last instant they are guaranteed to hold: the delivery of the real
/// `LsaLogonUser` reply, after every keystroke, readback and paint the gates assert. The measurement
/// functions are unchanged; only *when* they run moved. If the latch never fires (a boot where the
/// logon does not complete) the gates fall back to the live sample exactly as before.
pub(crate) static WINLOGON_DIALOG_EVIDENCE_LATCHED: AtomicU64 = AtomicU64::new(0);
pub(crate) static WINLOGON_DIALOG_MODAL_HWND_LIVE: AtomicU64 = AtomicU64::new(0);
pub(crate) static WINLOGON_DIALOG_USERNAME_HWND_LIVE: AtomicU64 = AtomicU64::new(0);
pub(crate) static WINLOGON_DIALOG_FB_VERIFIED: AtomicU64 = AtomicU64::new(0);

/// Take the three live-window measurements once. Idempotent.
pub(crate) unsafe fn latch_logon_dialog_evidence() {
    if WINLOGON_DIALOG_EVIDENCE_LATCHED.swap(1, Ordering::Relaxed) != 0 {
        return;
    }
    let modal = winlogon_dialog_contains_hwnd(WINLOGON_DIALOG_MODAL_HWND.load(Ordering::Relaxed));
    let username =
        winlogon_dialog_contains_hwnd(WINLOGON_CRED_USERNAME_HWND.load(Ordering::Relaxed));
    let framebuffer = verify_logon_dialog_framebuffer();
    WINLOGON_DIALOG_MODAL_HWND_LIVE.store(modal as u64, Ordering::Relaxed);
    WINLOGON_DIALOG_USERNAME_HWND_LIVE.store(username as u64, Ordering::Relaxed);
    WINLOGON_DIALOG_FB_VERIFIED.store(framebuffer as u64, Ordering::Relaxed);
    print_str(b"[winlogon] IDD_LOGON evidence LATCHED at the LsaLogonUser reply: modal-hwnd-live=");
    print_u64(modal as u64);
    print_str(b" username-hwnd-live=");
    print_u64(username as u64);
    print_str(b" framebuffer-verified=");
    print_u64(framebuffer as u64);
    print_str(b"\n");
}

/// Return the latched measurement when the latch fired, else take it live.
unsafe fn latched_or_live(latched: &AtomicU64, live: impl FnOnce() -> bool) -> bool {
    if WINLOGON_DIALOG_EVIDENCE_LATCHED.load(Ordering::Relaxed) != 0 {
        latched.load(Ordering::Relaxed) != 0
    } else {
        live()
    }
}

#[inline(never)]
unsafe fn check_logon_dialog_gates(passed: &mut u64) {
    print_str(b"[winlogon] msgina dialog windows created (post-SAS-notify #32770): ");
    print_u64(WINLOGON_DIALOG_WINDOWS.load(Ordering::Relaxed));
    print_str(b" (client GDI handle table mapped=");
    print_u64(WINLOGON_GDI_MAPPED.load(Ordering::Relaxed));
    print_str(b")\n");
    check(
        b"exec_msgina_logon_dialog_created",
        WINLOGON_GDI_MAPPED.load(Ordering::Relaxed) != 0
            && WINLOGON_DIALOG_WINDOWS.load(Ordering::Relaxed) != 0
            && WINLOGON_DIALOG_MODAL_READY.load(Ordering::Relaxed) != 0
            && WINLOGON_IDD_LOGON_HWND.load(Ordering::Relaxed) != 0
            && WINLOGON_DIALOG_CORRELATION_ERRORS.load(Ordering::Relaxed) == 0,
        passed,
    );
    print_str(b"[winlogon] IDD_LOGON correlation ready=");
    print_u64(WINLOGON_DIALOG_MODAL_READY.load(Ordering::Relaxed));
    print_str(b" hwnd=");
    print_hex(WINLOGON_IDD_LOGON_HWND.load(Ordering::Relaxed) as u32);
    print_str(b" errors=");
    print_u64(WINLOGON_DIALOG_CORRELATION_ERRORS.load(Ordering::Relaxed));
    print_str(b"\n");
    check(
        b"exec_msgina_idd_logon_correlated",
        WINLOGON_DIALOG_MODAL_READY.load(Ordering::Relaxed) != 0
            && WINLOGON_IDD_LOGON_HWND.load(Ordering::Relaxed) != 0
            && WINLOGON_DIALOG_CORRELATION_ERRORS.load(Ordering::Relaxed) == 0,
        passed,
    );
    print_str(b"[winlogon] IDD_LOGON modal pump steps=");
    print_u64(WINLOGON_DIALOG_MODAL_STEPS.load(Ordering::Relaxed));
    print_str(b"/3 completed=");
    print_u64(WINLOGON_DIALOG_MODAL_COMPLETED.load(Ordering::Relaxed));
    print_str(b" paints=");
    print_u64(WINLOGON_DIALOG_MODAL_PAINTS.load(Ordering::Relaxed));
    print_str(b" drained=");
    print_u64(WINLOGON_DIALOG_MODAL_DRAINED.load(Ordering::Relaxed));
    print_str(b" hwnd=");
    print_hex(WINLOGON_DIALOG_MODAL_HWND.load(Ordering::Relaxed) as u32);
    print_str(b" message=");
    print_hex(WINLOGON_DIALOG_MODAL_MESSAGE.load(Ordering::Relaxed) as u32);
    print_str(b" errors=");
    print_u64(WINLOGON_DIALOG_MODAL_ERRORS.load(Ordering::Relaxed));
    print_str(b"\n");
    check(
        b"exec_msgina_modal_paint_prefix",
        WINLOGON_DIALOG_MODAL_COMPLETED.load(Ordering::Relaxed) != 0
            && WINLOGON_DIALOG_MODAL_PAINTS.load(Ordering::Relaxed) != 0
            && WINLOGON_DIALOG_MODAL_DRAINED.load(Ordering::Relaxed) != 0
            && latched_or_live(&WINLOGON_DIALOG_MODAL_HWND_LIVE, || {
                winlogon_dialog_contains_hwnd(WINLOGON_DIALOG_MODAL_HWND.load(Ordering::Relaxed))
            })
            && WINLOGON_DIALOG_MODAL_MESSAGE.load(Ordering::Relaxed)
                == nt_user_callback::WM_PAINT as u64
            && WINLOGON_DIALOG_MODAL_ERRORS.load(Ordering::Relaxed) == 0,
        passed,
    );
    check(
        b"exec_msgina_logon_dialog_painted",
        latched_or_live(&WINLOGON_DIALOG_FB_VERIFIED, || {
            verify_logon_dialog_framebuffer()
        }),
        passed,
    );
    print_str(b"[winlogon] IDD_LOGON credential input: username-hwnd=0x");
    print_hex(WINLOGON_CRED_USERNAME_HWND.load(Ordering::Relaxed) as u32);
    print_str(b" password-hwnd=0x");
    print_hex(WINLOGON_CRED_PASSWORD_HWND.load(Ordering::Relaxed) as u32);
    print_str(b" ok-hwnd=0x");
    print_hex(WINLOGON_CRED_OK_HWND.load(Ordering::Relaxed) as u32);
    print_str(b" posted-chars=");
    print_u64(WINLOGON_CRED_POSTED_CHARS.load(Ordering::Relaxed));
    print_str(b" retrieved-chars=");
    print_u64(WINLOGON_CRED_RETRIEVED_CHARS.load(Ordering::Relaxed));
    print_str(b" return posted/retrieved=");
    print_u64(WINLOGON_CRED_POSTED_RETURN.load(Ordering::Relaxed));
    print_str(b"/");
    print_u64(WINLOGON_CRED_RETRIEVED_RETURN.load(Ordering::Relaxed));
    print_str(b" gdi-readbacks=");
    print_u64(WINLOGON_CRED_TEXT_READBACKS.load(Ordering::Relaxed));
    print_str(b" routed-getmessages=");
    print_u64(WINLOGON_CRED_ROUTED_GET_MESSAGES.load(Ordering::Relaxed));
    print_str(b" post-return-native-ssns=");
    print_u64(WINLOGON_CRED_POST_RETURN_SSNS.load(Ordering::Relaxed));
    print_str(b" errors=");
    print_u64(WINLOGON_CRED_ERRORS.load(Ordering::Relaxed));
    print_str(b"\n");
    let username_hwnd = WINLOGON_CRED_USERNAME_HWND.load(Ordering::Relaxed);
    check(
        b"exec_msgina_credential_keystrokes_delivered",
        username_hwnd != 0
            && username_hwnd != WINLOGON_IDD_LOGON_HWND.load(Ordering::Relaxed)
            && latched_or_live(&WINLOGON_DIALOG_USERNAME_HWND_LIVE, || {
                winlogon_dialog_contains_hwnd(username_hwnd)
            })
            && WINLOGON_CRED_POSTED_CHARS.load(Ordering::Relaxed)
                == nt_user_callback::LOGON_USERNAME.len() as u64
            && WINLOGON_CRED_RETRIEVED_CHARS.load(Ordering::Relaxed)
                == nt_user_callback::LOGON_USERNAME.len() as u64
            && WINLOGON_CRED_POSTED_RETURN.load(Ordering::Relaxed) != 0
            && WINLOGON_CRED_RETRIEVED_RETURN.load(Ordering::Relaxed) != 0
            && WINLOGON_CRED_ERRORS.load(Ordering::Relaxed) == 0,
        passed,
    );
    check(
        b"exec_msgina_credentials_entered",
        WINLOGON_CRED_TEXT_READBACKS.load(Ordering::Relaxed) != 0
            && WINLOGON_CRED_ERRORS.load(Ordering::Relaxed) == 0,
        passed,
    );
    // msgina's OWN `DoLogon` read the controls (`GetTextboxText` on IDC_LOGON_USERNAME /
    // IDC_LOGON_DOMAIN / IDC_LOGON_PASSWORD) and only calls `DoLoginTasks → ConnectToLsa` when the
    // user name and domain came back NON-EMPTY — so reaching `\LsaAuthenticationPort` is proof the
    // real `LogonDialogProc` ran its real validation path over the injected credentials.
    check(
        b"exec_msgina_logon_validation_reached_lsa",
        WINLOGON_CRED_LSA_CONNECT.load(Ordering::Relaxed) != 0
            && WINLOGON_CRED_RETRIEVED_RETURN.load(Ordering::Relaxed) != 0
            && WINLOGON_CRED_ERRORS.load(Ordering::Relaxed) == 0,
        passed,
    );
    lsa_authentication_port_specs(passed);
}

/// ═══ `\LsaAuthenticationPort` transport specs ═══════════════════════════════════════════════════
///
/// Every value below is produced by REAL code running on the real paths: lsass' own `NtCreatePort`,
/// its `AuthPortThreadRoutine` genuinely blocked in `NtReplyWaitReceivePort`, its
/// `LsapHandlePortConnection` issuing `NtOpenProcess`/`NtOpenProcessToken`/`NtQueryInformationToken`
/// and its OWN `NtAcceptConnectPort(Accept)` decision, the broker's real comm-port handles, and the
/// `LSA_API_MSG`s winlogon's `LsaLookupAuthenticationPackage`/`LsaLogonUser` marshalled.
fn lsa_authentication_port_specs(passed: &mut u64) {
    let server_port = LSA_AUTH_PORT_OBJECT_HANDLE.load(Ordering::Relaxed);
    let client_port = WINLOGON_LSA_PORT_HANDLE.load(Ordering::Relaxed);
    let connects_delivered = LSA_CONNECT_DELIVERED.load(Ordering::Relaxed);
    let connects_completed = LSA_CONNECT_COMPLETED.load(Ordering::Relaxed);
    let requests = LSA_REQUESTS_DELIVERED.load(Ordering::Relaxed);
    let replies = LSA_REPLIES_DELIVERED.load(Ordering::Relaxed);
    let api_mask = LSA_API_MASK.load(Ordering::Relaxed);
    let lookup_status = LSA_LOOKUP_REPLY_STATUS.load(Ordering::Relaxed);
    let logon_status = LSA_LOGON_REPLY_STATUS.load(Ordering::Relaxed);
    let logon_client_reads = LSA_LOGON_CLIENT_READS.load(Ordering::Relaxed);
    let last_api = LSA_LAST_API_NUMBER.load(Ordering::Relaxed);
    print_str(b"[lsa] \\LsaAuthenticationPort: server-port=0x");
    print_hex(server_port as u32);
    print_str(b" server-receive-parks=");
    print_u64(LSA_SERVER_PARKS.load(Ordering::Relaxed));
    print_str(b" connects-delivered=");
    print_u64(connects_delivered);
    print_str(b" accept-decision=");
    print_u64(LSA_ACCEPT_DECISION.load(Ordering::Relaxed));
    print_str(b" completed=");
    print_u64(connects_completed);
    print_str(b" winlogon-client-port=0x");
    print_hex(client_port as u32);
    print_str(b" OperationalMode=0x");
    print_hex(LSA_OPERATIONAL_MODE.load(Ordering::Relaxed) as u32);
    print_str(b" server-wall-ssn=");
    print_u64(LSA_SERVER_WALL_SSN.load(Ordering::Relaxed));
    print_str(b"\n");
    // One or more clients may connect to `\LsaAuthenticationPort` during a full desktop boot. The
    // gate therefore checks dynamic port invariants instead of the historical one-client sequence:
    // lsass published the real port, at least one connection was delivered and completed, winlogon's
    // accepted comm-port handle remains latched, and the server did not wall while a client was
    // blocked. `OperationalMode = 0x43218765` is the constant the real server wrote into its own
    // `ConnectInfo` (`references/reactos/dll/win32/lsasrv/authport.c:181`) and we copied back.
    check(
        b"exec_lsa_auth_port_connected",
        server_port != 0
            && LSA_SERVER_PARKS.load(Ordering::Relaxed) >= 1
            && connects_delivered >= 1
            && LSA_ACCEPT_DECISION.load(Ordering::Relaxed) == 2
            && connects_completed >= 1
            && connects_completed == connects_delivered
            && WINLOGON_LSA_CONNECTED.load(Ordering::Relaxed) != 0
            && client_port != 0
            && client_port != server_port
            && LSA_OPERATIONAL_MODE.load(Ordering::Relaxed) == 0x4321_8765
            // ★ THE WALL IS GONE (this batch). The previous form asserted the wall was EXACTLY
            // `NtCreateToken` — the last step the LSA server could not take. With SSN 57 serviced
            // the server runs `LsapLogonUser` to completion and walls NOWHERE, so the assertion is
            // the strictly stronger `u64::MAX` sentinel: ANY wall, at `NtCreateToken` or anywhere
            // else, now fails this spec.
            && LSA_SERVER_WALL_SSN.load(Ordering::Relaxed) == u64::MAX,
        passed,
    );
    print_str(b"[lsa] data plane: requests=");
    print_u64(requests);
    print_str(b" replies=");
    print_u64(replies);
    print_str(b" api-mask=0x");
    print_hex(api_mask as u32);
    print_str(b" lookup-status=0x");
    print_hex(lookup_status as u32);
    print_str(b" logon-status=0x");
    print_hex(logon_status as u32);
    print_str(b" logon-client-reads=");
    print_u64(logon_client_reads);
    print_str(b" last-api=");
    print_u64(last_api);
    print_str(b"\n");
    // msgina's `ConnectToLsa` tail: `LsaLookupAuthenticationPackage(MSV1_0_PACKAGE_NAME)` (api 3)
    // went over the real port to the real server and came back SUCCESS — the auth package is loaded
    // and resolvable — and `LsaLogonUser` (api 2) was then delivered and answered by that same server.
    const API_LOGON_USER: u64 = 1 << 2;
    const API_LOOKUP_PACKAGE: u64 = 1 << 3;
    // `LsaLookupAuthenticationPackage` (api 3) and `LsaLogonUser` (api 2) both round-trip
    // completely. Later services can issue additional successful lookup requests, so the proof is the
    // observed API mask plus successful per-API reply statuses and client-memory reads during the real
    // logon request, not "api 2 was the last request seen globally".
    check(
        b"exec_lsa_logon_user_reached",
        requests >= 2
            && replies == requests
            && api_mask & API_LOOKUP_PACKAGE != 0
            && api_mask & API_LOGON_USER != 0
            && lookup_status == 0
            && logon_status == 0
            && logon_client_reads >= 4,
        passed,
    );
    // ★ HONEST WALL — and it MOVED (batch 51). The real MSV1_0 authentication package runs
    // `SamValidateNormalUser` on credentials copied out of winlogon's own address space (lsasrv's
    // `LsapCopyFromClient`). Its first step, `GetAccountDomainSid` (`msv1_0/sam.c:267`), succeeds
    // against the real LSA policy database. It used to fail ONE step later in `SamIConnect`
    // (`samsrv!SampOpenDbObject(NULL, NULL, L"SAM")` with a NULL `SamKeyHandle`, because
    // `SamIInitialize` had blocked forever in `SampGetAccountDomainInfo` → `LsaOpenPolicy`, the
    // `\pipe\lsarpc` SELF-RPC lsass hosted no worker for) and return
    // STATUS_OBJECT_NAME_NOT_FOUND. `LSA_WORKER_ROUTE_ENABLED` supplies that worker, so
    // `SampInitDatabase` now runs and `SamIConnect` SUCCEEDS — asserted as the null-root miss being
    // GONE, which the OLDEST form of this spec asserted the presence of.
    //
    // ★ AND THE CHAIN NOW FINISHES. The previous form asserted the reply status was UNSET
    // (`u64::MAX`) because the server walled at `NtCreateToken` before it could answer. With the
    // service in place `SamValidateNormalUser` validates `Administrator` against the real
    // `SampInitDatabase`, `LsapLogonUser` mints the token, and the real `LSA_API_MSG.Status` comes
    // back **STATUS_SUCCESS** — the strictly stronger assertion, and the one that says the
    // credential validation actually SUCCEEDED rather than merely being reached.
    check(
        b"exec_lsa_msv1_0_sam_validation_reached",
        LSA_LOGON_CLIENT_READS.load(Ordering::Relaxed) >= 4
            && LSA_LOGON_REPLY_STATUS.load(Ordering::Relaxed) == 0
            && SAM_CONNECT_NULL_ROOT_MISS.load(Ordering::Relaxed) == 0
            && WINLOGON_LSA_CONNECTED.load(Ordering::Relaxed) != 0,
        passed,
    );
    se_create_token_specs(passed);
    lsa_security_database_specs(passed);
    unsafe { activation_context_stack_spec(passed) };
    winlogon_logon_action_spec(passed);
    unsafe { software_hive_mount_spec(passed) };
    unsafe { writable_overlay_spec(passed) };
}

/// ═══ THE WRITABLE FILESYSTEM OVERLAY IS A REAL FILE SYSTEM ═════════════════════════════════════
///
/// The host booted for 55 batches with a READ-ONLY filesystem: `fs_loader`'s FAT32 reader resolves
/// any `\reactos\…` path to bytes and nothing more. The instant the interactive logon completed,
/// that became the wall — `userenv!CreateUserProfileW` calls `CreateDirectoryW("C:\Profiles")`
/// (`profile.c:929`), and with no writable filesystem the `NtCreateFile` behind it failed as an
/// invalid-function error at `profile.c:933`.
///
/// A writable volume is now MOUNTED over the declared writable namespace prefixes
/// (`writable_fs::WRITABLE_PREFIXES`, today `%SystemDrive%\Profiles`), backed by `nt-fs`'s `MemFs`
/// behind its `Zw*` facade. **It is a real file system, not a "return SUCCESS" fake**, and this
/// spec proves that two independent ways:
///
///  1. **The mount-time self-test** (`writable_fs::selftest`), which runs the whole surface on a
///     scratch subtree — directory create; the SAME create again COLLIDING (so the volume has real
///     state, it is not saying yes to everything); a file create; a write; a read-back of the same
///     bytes; metadata that agrees with what was written; a directory ENUMERATION through the
///     native record encoder that finds `.`, `..` and the file; delete-on-close that really
///     unlinks both and makes the by-path attribute queries MISS; and a volume left with exactly
///     its root, so nothing was left behind. All nine bits must be set.
///  2. **The live counters** — real directories created, bytes written and read back by REAL
///     hosted-process syscalls during the boot.
///
/// Installed files remain visible below the writable namespace too: the overlay wins once a file is
/// created or modified, while unmodified `FILE_OPEN` and attribute probes read through to the FAT
/// source. Boot hive source files use that path until Configuration Manager flushes live mutable
/// checkpoints into `system32\config`.
///
/// **NOT PERSISTENT.** The backing is RAM: everything written is gone at the next boot. That is a
/// deliberate staging step — persistent FAT32 write-through is a separate, tracked milestone, and
/// when it lands only the backing behind `writable_fs` changes because every caller is above the
/// `Zw*` seam.
unsafe fn writable_overlay_spec(passed: &mut u64) {
    use crate::writable_fs::*;
    let selftest = OVERLAY_SELFTEST.load(Ordering::Relaxed);
    let dirs = OVERLAY_DIRS_CREATED.load(Ordering::Relaxed);
    let creates = OVERLAY_CREATES.load(Ordering::Relaxed);
    let writes = OVERLAY_WRITES.load(Ordering::Relaxed);
    let bytes_written = OVERLAY_BYTES_WRITTEN.load(Ordering::Relaxed);
    let bytes_read = OVERLAY_BYTES_READ.load(Ordering::Relaxed);
    let dir_queries = OVERLAY_DIR_QUERIES.load(Ordering::Relaxed);
    let attr_queries = OVERLAY_ATTR_QUERIES.load(Ordering::Relaxed);
    let restored = snapshot_restore_seen();
    let restored_profile_source =
        restored && PROFILE_SOURCE_DIRS.load(Ordering::Relaxed) >= 45 && copied_profile_probe_ok();
    print_str(b"[writable-fs] mounted=");
    print_u64(writable_fs_mounted() as u64);
    print_str(b" restored=");
    print_u64(restored as u64);
    print_str(b" selftest=0x");
    print_hex(selftest as u32);
    print_str(b"/0x");
    print_hex(OVERLAY_SELFTEST_ALL as u32);
    print_str(b" live: creates=");
    print_u64(creates);
    print_str(b" dirs=");
    print_u64(dirs);
    print_str(b" opens=");
    print_u64(OVERLAY_OPENS.load(Ordering::Relaxed));
    print_str(b" writes=");
    print_u64(writes);
    print_str(b" bytes-written=");
    print_u64(bytes_written);
    print_str(b" reads=");
    print_u64(OVERLAY_READS.load(Ordering::Relaxed));
    print_str(b" bytes-read=");
    print_u64(bytes_read);
    print_str(b" dir-queries=");
    print_u64(dir_queries);
    print_str(b" attr-queries=");
    print_u64(attr_queries);
    print_str(b" attr-hits=");
    print_u64(OVERLAY_ATTR_HITS.load(Ordering::Relaxed));
    print_str(b" set-info=");
    print_u64(OVERLAY_SET_INFO.load(Ordering::Relaxed));
    print_str(b" closes=");
    print_u64(OVERLAY_CLOSES.load(Ordering::Relaxed));
    print_str(b" dir-query-refusals: misaligned=");
    print_u64(QUERY_DIR_MISALIGNED.load(Ordering::Relaxed));
    print_str(b" iosb-unreachable=");
    print_u64(QUERY_DIR_IOSB_UNREACHABLE.load(Ordering::Relaxed));
    print_str(b" buffer-unreachable=");
    print_u64(QUERY_DIR_BUFFER_UNREACHABLE.load(Ordering::Relaxed));
    print_str(b"\n");
    check(
        b"exec_writable_overlay_mounted",
        // The volume was really mounted — i.e. a real syscall path resolved into it …
        writable_fs_mounted()
            // … every one of the nine real-filesystem checks passed on the live volume …
            && selftest == OVERLAY_SELFTEST_ALL
            // … and either this boot created a directory through NtCreateFile, or this is a later
            // boot over a restored volume whose profile tree is present and readable by content.
            && ((dirs >= 1 && creates >= dirs) || restored_profile_source),
        passed,
    );
    unsafe { default_user_profile_spec(passed) };
    winlogon_profile_directories_spec(passed);
    unsafe { winlogon_profile_copied_spec(passed) };
    get_message_guard_spec(passed);
    vspace_asid_unmap_spec(passed);
    root_cap_ownership_spec(passed);
    mapped_section_writeback_spec(passed);
    mapped_section_writecopy_cow_spec(passed);
    image_writecopy_cow_spec(passed);
    vm_pool_headroom_spec(passed);
    unsafe { teb_tail_protected_spec(passed) };
    unsafe { lsarpc_connection_worker_spec(passed) };
    unsafe { gdi_user_batch_flush_spec(passed) };
    unsafe { profile_ntuser_dat_spec(passed) };
    unsafe { nt_load_key_spec(passed) };
    user_shell_activation_spec(passed);
}

/// ═══ winlogon RAN ITS WHOLE `HandleLogon` AND ASKED FOR `userinit.exe` ══════════════════════════
///
/// The batch's user-visible advance, named for exactly what was MEASURED. `HandleLogon`
/// (`sas.c:571`) is a chain in which EVERY step is fatal: `LoadUserProfileW` →
/// `CreateUserEnvironment` → `UpdatePerUserSystemParameters` → `SetDefaultLanguage` →
/// `AllowAccessOnSession` → `StartUserShell` → `WlxActivateUserShell` → `CreateProcessAsUserW`.
/// Reaching the LAST link is therefore a structural witness that every earlier one succeeded.
///
/// The generic image lane accepts its open, creates SEC_IMAGE, answers SectionImageInformation, and
/// publishes a real pi=5 process. The separate gate below proves every stage plus the live VSpace.
///
/// The Winlogon key is now read from the real SOFTWARE hive. This proof keeps the essential shell
/// frontier facts: msgina read the real `Userinit` value, winlogon attempted `userinit.exe`, and the
/// logon token carried a real logon SID. Other Winlogon-key values are counted as real hive traffic,
/// not suppressed by executive policy.
fn user_shell_activation_spec(passed: &mut u64) {
    let reads = WINLOGON_USERINIT_READS.load(Ordering::Relaxed);
    let ty = WINLOGON_USERINIT_TYPE.load(Ordering::Relaxed);
    let bytes = WINLOGON_USERINIT_BYTES.load(Ordering::Relaxed);
    let opens = WINLOGON_USERINIT_IMAGE_OPENS.load(Ordering::Relaxed);
    let served = WINLOGON_KEY_VALUES_SERVED.load(Ordering::Relaxed);
    let defpwd = WINLOGON_DEFAULT_PASSWORD_READS.load(Ordering::Relaxed);
    let logon_sids = SE_CREATE_TOKEN_LOGON_SIDS.load(Ordering::Relaxed);
    print_str(b"[wl-shell] WlxActivateUserShell: Userinit reads=");
    print_u64(reads);
    print_str(b" (REG type ");
    print_u64(ty);
    print_str(b", ");
    print_u64(bytes);
    print_str(b" bytes) -> CreateProcessAsUserW image opens for userinit.exe=");
    print_u64(opens);
    print_str(b" | Winlogon-key values served=");
    print_u64(served);
    print_str(b" (real SOFTWARE hive; DefaultPassword reads=");
    print_u64(defpwd);
    print_str(b") | logon-SID groups in the token=");
    print_u64(logon_sids);
    print_str(b" | user locale bytes=");
    print_u64(DEFAULT_USER_LOCALE_BYTES.load(Ordering::Relaxed));
    print_str(b" (REG type ");
    print_u64(DEFAULT_USER_LOCALE_TYPE.load(Ordering::Relaxed));
    print_str(b")");
    print_str(b"\n");
    check(
        b"exec_winlogon_user_shell_activated",
        // `WlxActivateUserShell` really read `Userinit`, and got the REAL hive value:
        // `%SystemRoot%\system32\userinit.exe` is 35 chars => 70 bytes with its NUL, and
        // the hive stores it as REG_EXPAND_SZ (2) — the type msgina insists on.
        reads >= 1
            && ty == 2
            && bytes == 70
            // winlogon's OWN CreateProcessAsUserW then reached the shell binary.
            && opens >= 1
            // The key was not an executive-owned two-value surface; all served values are real hive
            // values and at least include Userinit.
            && served >= reads
            // `AllowAccessOnSession` could only have been passed with a real logon SID in
            // TOKEN_GROUPS (it dereferences an uninitialised local otherwise).
            && logon_sids >= 1
            // Setup's locale step really seeded the value `SetDefaultLanguage` needs.
            && (!PROVISION_DEFAULT_USER_LOCALE
                || (DEFAULT_USER_LOCALE_TYPE.load(Ordering::Relaxed) == 1
                    && DEFAULT_USER_LOCALE_BYTES.load(Ordering::Relaxed) > 0)),
        passed,
    );
    userinit_image_pipeline_spec(passed);
}

