unsafe fn cnode_mint_r(cnode: u64, dest: u64, src: u64, badge: u64) -> u64 {
    let reply: u64;
    core::arch::asm!(
        "syscall",
        inout("rdx") SYS_CALL as u64 => _,
        inout("rdi") cnode => _,
        inout("rsi") LBL_CNODE_MINT << 12 => reply,
        inout("r10") dest => _,
        inout("r8") src => _,
        inout("r9") badge => _,
        in("r12") 0u64,
        in("r13") 0u64,
        lateout("r15") _, lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
    let label = reply >> 12;
    if label == 0 && cnode == CAP_INIT_THREAD_CNODE {
        root_slot_note_occupied(dest);
    }
    label
}
const LBL_CNODE_MOVE: u64 = 27;
#[track_caller]
unsafe fn cnode_move_root_to_cnode_r(dest_cnode: u64, dest_index: u64, src_root_slot: u64) -> u64 {
    if root_slot_is_pinned(src_root_slot) {
        let caller = core::panic::Location::caller();
        ROOT_SLOT_PIN_MOVE_REFUSALS.fetch_add(1, Ordering::Relaxed);
        print_str(b"[cap-owner] refused move of pinned root slot=0x");
        print_hex((src_root_slot >> 32) as u32);
        print_hex(src_root_slot as u32);
        print_str(b" caller=");
        print_str(caller.file().as_bytes());
        print_str(b":");
        print_u64(caller.line() as u64);
        print_str(b"\n");
        return u64::MAX;
    }
    let reply: u64;
    core::arch::asm!(
        "syscall",
        inout("rdx") SYS_CALL as u64 => _,
        inout("rdi") dest_cnode => _,
        inout("rsi") LBL_CNODE_MOVE << 12 => reply,
        inout("r10") dest_index => _,
        inout("r8") src_root_slot => _,
        inout("r9") 0u64 => _,
        in("r12") 0u64,
        in("r13") 0u64,
        lateout("r15") _, lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
    reply >> 12
}

unsafe fn cnode_move_cnode_to_root_r(dest_root_slot: u64, src_cnode: u64, src_index: u64) -> u64 {
    let ipc = IPC_BUFFER.load(Ordering::Relaxed);
    core::ptr::write_volatile((ipc + 122 * 8) as *mut u64, src_cnode);
    let msginfo = (LBL_CNODE_MOVE << 12) | (1 << 9) | (1 << 7) | 4;
    let reply: u64;
    core::arch::asm!(
        "syscall",
        inout("rdx") SYS_CALL as u64 => _,
        inout("rdi") CAP_INIT_THREAD_CNODE => _,
        inout("rsi") msginfo => reply,
        inout("r10") dest_root_slot => _,
        inout("r8") 64u64 => _,
        inout("r9") src_index => _,
        inout("r15") 64u64 => _,
        in("r12") 0u64,
        in("r13") 0u64,
        lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
    let label = reply >> 12;
    if label == 0 {
        root_slot_note_occupied(dest_root_slot);
    }
    label
}
