/// Allocate a fresh 4 KiB frame, returning (slot, retype-error-label).
unsafe fn alloc_frame_r() -> (u64, u64) {
    let Some(s) = try_alloc_slot() else {
        return (0, 4);
    };
    let e = untyped_retype_r(CAP_INIT_UNTYPED, OBJ_X86_4K_PAGE, PAGING_BITS, 1, s);
    (s, e)
}

unsafe fn alloc_seeded_root_dma_mmio_frame(owner: &mut HostedPnpContextOwner, seed_va: u64) -> u64 {
    let (frame, frame_err) = alloc_frame_r();
    if frame_err != 0 {
        recycle_deleted_root_slot(frame);
        return 0;
    }
    owner.adopt_root_frame(frame, false);
    if !ensure_executive_paging(seed_va) {
        return 0;
    }
    if page_map_r(frame, seed_va, RW_NX, CAP_INIT_THREAD_VSPACE) != 0 {
        return 0;
    }
    if !owner.mark_root_frame_mapped(frame) {
        return 0;
    }
    let mut offset = 0u64;
    while offset < 0x1000 {
        core::ptr::write_volatile((seed_va + offset) as *mut u8, 0);
        offset += 1;
    }
    core::ptr::write_volatile(seed_va as *mut u32, ROOT_DMA_PROOF_ID_VALUE);
    frame
}

unsafe fn map_hosted_pci_resource_root_alias(
    owner: &mut HostedPnpContextOwner,
    frame_base: u64,
    pages: u64,
    alias_va: u64,
) -> bool {
    if frame_base == 0 || pages == 0 || alias_va == 0 {
        return false;
    }
    let Ok(pages_usize) = usize::try_from(pages) else {
        return false;
    };
    if !owner.reserve_alias_caps(pages_usize) {
        return false;
    }
    for window in 0..pages.div_ceil(512).max(1) {
        if !ensure_executive_paging(alias_va + window * 0x20_0000) {
            return false;
        }
    }
    let mut page = 0u64;
    while page < pages {
        let source_cap = frame_base + page;
        let (map_cap, copy_error) = copy_cap_r(source_cap);
        if copy_error != 0 {
            print_str(b"[driver-launch] hosted PCI resource root alias copy failed page=");
            print_u64(page);
            print_str(b"/");
            print_u64(pages);
            print_str(b" label=");
            print_u64(copy_error);
            print_str(b"\n");
            return false;
        }
        let map_error = page_map_r(
            map_cap,
            alias_va + page * 0x1000,
            RW_NX,
            CAP_INIT_THREAD_VSPACE,
        );
        if map_error != 0 {
            owner.adopt_alias_cap(map_cap, false);
            print_str(b"[driver-launch] hosted PCI resource root alias map failed page=");
            print_u64(page);
            print_str(b"/");
            print_u64(pages);
            print_str(b" label=");
            print_u64(map_error);
            print_str(b"\n");
            return false;
        }
        owner.adopt_alias_cap(map_cap, true);
        page += 1;
    }
    true
}

enum HostedDevnodeGrantKind {
    Pci { dev: u8, func: u8 },
    RootBus,
}

struct HostedDevnodeGrant {
    kind: HostedDevnodeGrantKind,
    pci_interrupt_line: Option<PciInterruptLineProgramming>,
    raw_resource_list: alloc::vec::Vec<u8>,
    translated_resource_list: alloc::vec::Vec<u8>,
    mmio_phys: u64,
    mmio_len: u64,
    io_port_base: u64,
    io_port_len: u32,
    vector: u32,
    dma_len: u64,
}

fn hosted_pci_grant_error(
    device_id: u64,
    stage: &[u8],
    status: nt_status::NtStatus,
) -> nt_status::NtStatus {
    print_str(b"[driver-launch] PCI resource grant rejected device_id=");
    print_u64(device_id);
    print_str(b" stage=");
    print_str(stage);
    print_str(b" status=0x");
    print_hex(status.raw() as u32);
    print_str(b"\n");
    status
}

fn print_hosted_devnode_grant(service: &[u8], devnode: &[u8], grant: &HostedDevnodeGrant) {
    match grant.kind {
        HostedDevnodeGrantKind::Pci { dev, func } => {
            print_str(b"[driver-launch] assigned PCI resources service=");
            print_str(service);
            print_str(b" devnode=");
            print_str(devnode);
            print_str(b" pci=0:");
            print_u64(dev as u64);
            print_str(b".");
            print_u64(func as u64);
        }
        HostedDevnodeGrantKind::RootBus => {
            print_str(b"[driver-launch] assigned root-bus resources service=");
            print_str(service);
            print_str(b" devnode=");
            print_str(devnode);
        }
    }
    print_str(b" mmio=0x");
    print_hex(grant.mmio_phys as u32);
    print_str(b" len=");
    print_u64(grant.mmio_len);
    if grant.io_port_len != 0 {
        print_str(b" io=0x");
        print_hex(grant.io_port_base as u32);
        print_str(b" io_len=");
        print_u64(grant.io_port_len as u64);
    }
    print_str(b" vector=");
    print_u64(grant.vector as u64);
    print_str(b" dma_len=");
    print_u64(grant.dma_len);
    print_str(b"\n");
}

unsafe fn settle_hosted_pnp_context_grant(
    device_id: u64,
    context_lease: nt_pnp_context::ContextLeaseIdentity,
    result: Result<Option<HostedDevnodeGrant>, nt_status::NtStatus>,
) -> Result<Option<HostedDevnodeGrant>, nt_status::NtStatus> {
    let retained =
        driver_launch::hosted_pnp_context_lease_for_device(device_id) == Some(context_lease);
    match (result, retained) {
        (Ok(grant), true) => Ok(grant),
        (Ok(_), false) => {
            release_hosted_pnp_context_lease(context_lease)?;
            Err(nt_status::NtStatus::UNSUCCESSFUL)
        }
        (Err(status), true) => Err(status),
        (Err(status), false) => {
            release_hosted_pnp_context_lease(context_lease)?;
            Err(status)
        }
    }
}

unsafe fn grant_hosted_pci_devnode_resources(
    device_id: u64,
    bus_resources: DevnodePciBusResources,
    window: HostedPnpPciResourceDescriptor,
    context_lease: nt_pnp_context::ContextLeaseIdentity,
) -> Result<Option<HostedDevnodeGrant>, nt_status::NtStatus> {
    let interrupt_required = bus_resources.device.irq_pin != 0;
    let interrupt = if interrupt_required {
        if !window.interrupt_routed {
            return Err(hosted_pci_grant_error(
                device_id,
                b"interrupt-route",
                nt_status::NtStatus::INVALID_DEVICE_REQUEST,
            ));
        }
        Some(nt_pnp::PciInterruptAssignment {
            bus_level: window.interrupt_vector,
            vector: window.interrupt_vector,
            latched: window.interrupt_latched,
            affinity: 1,
        })
    } else {
        None
    };
    let grant = build_devnode_pci_resource_grant(bus_resources, interrupt, window.dma_len)
        .ok_or_else(|| {
            hosted_pci_grant_error(
                device_id,
                b"assignment",
                nt_status::NtStatus::INVALID_DEVICE_REQUEST,
            )
        })?;
    if let Err(status) = driver_launch::commit_hosted_filtered_resource_requirements(
        device_id,
        &grant.resource_requirements,
    ) {
        return Err(hosted_pci_grant_error(
            device_id,
            b"requirements-commit",
            status,
        ));
    }
    if !window.matches(&grant.device) {
        return Err(hosted_pci_grant_error(
            device_id,
            b"identity",
            nt_status::NtStatus::INVALID_DEVICE_REQUEST,
        ));
    }
    let memory = grant
        .assignment
        .memory_resources(nt_pnp::ResourceView::Translated)
        .next();
    let port = grant
        .assignment
        .port_resources(nt_pnp::ResourceView::Translated)
        .next();
    let interrupt = grant
        .assignment
        .interrupt_resource(nt_pnp::ResourceView::Translated);
    let has_mmio = memory.is_some();
    let memory_bars: Vec<_> = grant
        .device
        .bars
        .iter()
        .filter(|bar| bar.is_present() && !bar.is_io)
        .collect();
    let assigned_memory: Vec<_> = grant
        .assignment
        .memory_resources(nt_pnp::ResourceView::Translated)
        .collect();
    if assigned_memory.len() != memory_bars.len()
        || assigned_memory.len() != window.memory.len()
        || memory_bars
            .iter()
            .zip(&assigned_memory)
            .any(|(bar, assigned)| {
                window.memory_window(bar.index).is_none_or(|mapped| {
                    mapped.phys != assigned.start || mapped.len != assigned.length as u64
                })
            })
    {
        return Err(hosted_pci_grant_error(
            device_id,
            b"memory-window",
            nt_status::NtStatus::INVALID_DEVICE_REQUEST,
        ));
    }
    if !has_mmio && !window.memory.is_empty() {
        return Err(hosted_pci_grant_error(
            device_id,
            b"unexpected-memory-window",
            nt_status::NtStatus::INVALID_DEVICE_REQUEST,
        ));
    }
    if !window.dma_grant_valid() {
        return Err(hosted_pci_grant_error(
            device_id,
            b"dma-window",
            nt_status::NtStatus::INVALID_DEVICE_REQUEST,
        ));
    }
    let primary_window = window.memory.first();
    let mmio_len = memory.map(|memory| memory.length as u64).unwrap_or(0);
    if has_mmio && primary_window.is_none_or(|window| window.mapped_len() == 0) {
        return Err(hosted_pci_grant_error(
            device_id,
            b"mapped-memory-window",
            nt_status::NtStatus::INVALID_DEVICE_REQUEST,
        ));
    }
    let pci_interrupt_line = if let Some(interrupt) = interrupt {
        program_pci_interrupt_line(&grant.device, interrupt.vector)?
    } else {
        None
    };
    let raw_memory: Vec<_> = grant
        .assignment
        .memory_resources(nt_pnp::ResourceView::Raw)
        .collect();
    let raw_ports: Vec<_> = grant
        .assignment
        .port_resources(nt_pnp::ResourceView::Raw)
        .collect();
    let translated_ports: Vec<_> = grant
        .assignment
        .port_resources(nt_pnp::ResourceView::Translated)
        .collect();
    if raw_memory.len() != memory_bars.len()
        || raw_ports.len() != translated_ports.len()
        || raw_ports.len()
            != grant
                .device
                .bars
                .iter()
                .filter(|bar| bar.is_present() && bar.is_io)
                .count()
    {
        return Err(hosted_pci_grant_error(
            device_id,
            b"resource-pairing",
            nt_status::NtStatus::INVALID_DEVICE_REQUEST,
        ));
    }
    let mut memory_grants = Vec::new();
    memory_grants
        .try_reserve_exact(memory_bars.len())
        .map_err(|_| nt_status::NtStatus::INSUFFICIENT_RESOURCES)?;
    for ((bar, raw), translated) in memory_bars.iter().zip(&raw_memory).zip(&assigned_memory) {
        let mapped = window
            .memory_window(bar.index)
            .ok_or(nt_status::NtStatus::INVALID_DEVICE_REQUEST)?;
        memory_grants.push(driver_launch::HostedMemoryResourceGrant {
            bar_index: bar.index,
            raw_start: raw.start,
            translated_start: translated.start,
            length: translated.length as u64,
            flags: translated.flags,
            share: translated.share,
            pci_flags: (u32::from(bar.is_64bit) << 2) | (u32::from(bar.prefetchable) << 3),
            component_va: mapped.va,
            broker_va: mapped.seed_va,
            frame_base: mapped.frame_base,
            map_pages: mapped.map_pages,
            video_memory_caller_va: if grant.device.base_class() == nt_pnp::PCI_CLASS_DISPLAY
                && translated.start == FB_BAR_PADDR.load(Ordering::Relaxed)
            {
                win32k_subsystem::WIN32K_FB_VA
            } else {
                0
            },
        });
    }
    let io_bars: Vec<_> = grant
        .device
        .bars
        .iter()
        .filter(|bar| bar.is_present() && bar.is_io)
        .collect();
    let mut port_grants = Vec::new();
    port_grants
        .try_reserve_exact(io_bars.len())
        .map_err(|_| nt_status::NtStatus::INSUFFICIENT_RESOURCES)?;
    for ((bar, raw), translated) in io_bars.iter().zip(&raw_ports).zip(&translated_ports) {
        port_grants.push(driver_launch::HostedPortResourceGrant {
            bar_index: bar.index,
            raw_start: raw.start,
            translated_start: translated.start,
            length: translated.length,
            flags: translated.flags,
            share: translated.share,
            pci_flags: 1,
        });
    }
    let resource_grant = driver_launch::grant_hosted_device_resources(
        device_id,
        driver_launch::HostedBusIdentity::pci(
            grant.device.bus,
            grant.device.dev,
            grant.device.func,
            grant.device.vendor,
            grant.device.device,
            grant.device.class,
            interrupt
                .map(|interrupt| interrupt.vector as u8)
                .unwrap_or(0),
            grant.device.irq_pin,
        ),
        &memory_grants,
        &port_grants,
        interrupt.map(|interrupt| interrupt.vector).unwrap_or(0),
        interrupt
            .map(|interrupt| interrupt.share == nt_cm_resources::CM_RESOURCE_SHARE_SHARED)
            .unwrap_or(false),
        interrupt
            .map(|interrupt| interrupt.flags == nt_pnp::CM_RESOURCE_INTERRUPT_LATCHED)
            .unwrap_or(false),
        interrupt.map(|interrupt| interrupt.affinity).unwrap_or(0),
        window.dma_va,
        window.dma_seed_va,
        window.dma_frame_base,
        window.dma_pages,
        window.dma_logical,
        grant.assignment.dma_len,
        context_lease,
    );
    if let Err(status) = resource_grant {
        if let Some(programming) = pci_interrupt_line {
            let _ = restore_pci_interrupt_line(programming);
        }
        return Err(status);
    }
    Ok(Some(HostedDevnodeGrant {
        kind: HostedDevnodeGrantKind::Pci {
            dev: grant.device.dev,
            func: grant.device.func,
        },
        pci_interrupt_line,
        raw_resource_list: grant.raw_resource_list,
        translated_resource_list: grant.translated_resource_list,
        mmio_phys: memory.map(|memory| memory.start).unwrap_or(0),
        mmio_len,
        io_port_base: port.map(|port| port.start).unwrap_or(0),
        io_port_len: port.map(|port| port.length).unwrap_or(0),
        vector: interrupt.map(|interrupt| interrupt.vector).unwrap_or(0),
        dma_len: grant.assignment.dma_len,
    }))
}

unsafe fn grant_hosted_root_devnode_resources(
    device_id: u64,
    grant: DevnodeRootResourceGrant,
    window: HostedPnpRootResourceDescriptor,
    context_lease: nt_pnp_context::ContextLeaseIdentity,
) -> Result<Option<HostedDevnodeGrant>, nt_status::NtStatus> {
    let raw_memory = grant
        .assignment
        .memory_resources(nt_pnp::ResourceView::Raw)
        .next()
        .ok_or(nt_status::NtStatus::INVALID_DEVICE_REQUEST)?;
    let memory = grant
        .assignment
        .memory_resources(nt_pnp::ResourceView::Translated)
        .next()
        .ok_or(nt_status::NtStatus::INVALID_DEVICE_REQUEST)?;
    let interrupt = grant
        .assignment
        .interrupt_resource(nt_pnp::ResourceView::Translated)
        .ok_or(nt_status::NtStatus::INVALID_DEVICE_REQUEST)?;
    if memory.start != window.mmio_phys || window.mmio_frame_base == 0 || window.dma_frame_base == 0
    {
        return Err(nt_status::NtStatus::INVALID_DEVICE_REQUEST);
    }
    let mmio_len = memory.length as u64;
    if mmio_len == 0 || mmio_len > window.mmio_pages * 0x1000 {
        return Err(nt_status::NtStatus::INVALID_DEVICE_REQUEST);
    }
    let memory_grants = [driver_launch::HostedMemoryResourceGrant {
        bar_index: 0,
        raw_start: raw_memory.start,
        translated_start: memory.start,
        length: mmio_len,
        flags: memory.flags,
        share: memory.share,
        pci_flags: 0,
        component_va: window.mmio_va,
        broker_va: window.mmio_seed_va,
        frame_base: window.mmio_frame_base,
        map_pages: window.mmio_pages,
        video_memory_caller_va: 0,
    }];
    driver_launch::grant_hosted_device_resources(
        device_id,
        driver_launch::HostedBusIdentity::root_bus(),
        &memory_grants,
        &[],
        interrupt.vector,
        interrupt.share == nt_cm_resources::CM_RESOURCE_SHARE_SHARED,
        interrupt.flags == nt_pnp::CM_RESOURCE_INTERRUPT_LATCHED,
        interrupt.affinity,
        window.dma_va,
        0,
        window.dma_frame_base,
        window.dma_pages,
        window.dma_logical,
        grant.assignment.dma_len,
        context_lease,
    )?;
    Ok(Some(HostedDevnodeGrant {
        kind: HostedDevnodeGrantKind::RootBus,
        pci_interrupt_line: None,
        raw_resource_list: grant.raw_resource_list,
        translated_resource_list: grant.translated_resource_list,
        mmio_phys: memory.start,
        mmio_len,
        io_port_base: 0,
        io_port_len: 0,
        vector: interrupt.vector,
        dma_len: grant.assignment.dma_len,
    }))
}

unsafe fn grant_hosted_devnode_resources(
    device_id: u64,
    plan: PreparedHostedResourcePlan,
) -> Result<Option<HostedDevnodeGrant>, nt_status::NtStatus> {
    match plan {
        PreparedHostedResourcePlan::Pci {
            bus_resources,
            window,
            lease,
        } => {
            let context_lease = lease.into_identity();
            let result =
                grant_hosted_pci_devnode_resources(device_id, bus_resources, window, context_lease);
            settle_hosted_pnp_context_grant(device_id, context_lease, result)
        }
        PreparedHostedResourcePlan::Root {
            grant,
            window,
            lease,
        } => {
            let context_lease = lease.into_identity();
            let result =
                grant_hosted_root_devnode_resources(device_id, grant, window, context_lease);
            settle_hosted_pnp_context_grant(device_id, context_lease, result)
        }
        PreparedHostedResourcePlan::None => Ok(None),
    }
}

unsafe fn make_object(obj: u64) -> u64 {
    let s = alloc_slot();
    let _ = untyped_retype(CAP_INIT_UNTYPED, obj, 0, 1, s);
    s
}

static mut EXEC_PAGING_SEEN: Option<Vec<u64>> = None;
const EXEC_PAGING_SEEN_PDPT: u64 = 1u64 << 60;
const EXEC_PAGING_SEEN_PD: u64 = 2u64 << 60;
const EXEC_PAGING_SEEN_PT: u64 = 3u64 << 60;
const SEL4_RANGE_ERROR: u64 = 4;
const SEL4_FAILED_LOOKUP: u64 = 6;
const SEL4_DELETE_FIRST: u64 = 8;

unsafe fn exec_paging_seen_mut() -> &'static mut Vec<u64> {
    let slot = &mut *core::ptr::addr_of_mut!(EXEC_PAGING_SEEN);
    if slot.is_none() {
        *slot = Some(Vec::new());
    }
    slot.as_mut().expect("initialized above")
}

unsafe fn exec_paging_seen(key: u64) -> bool {
    (&*core::ptr::addr_of!(EXEC_PAGING_SEEN))
        .as_ref()
        .is_some_and(|entries| entries.iter().any(|entry| *entry == key))
}

unsafe fn exec_paging_prepare_mark(key: u64, page: u64, level: &[u8]) -> bool {
    let entries = exec_paging_seen_mut();
    if entries.iter().any(|entry| *entry == key) {
        return true;
    }
    if entries.try_reserve(1).is_err() {
        print_str(b"[exec-paging] seen-set allocation failed ");
        print_str(level);
        print_str(b" page=0x");
        print_hex((page >> 32) as u32);
        print_hex(page as u32);
        print_str(b" key=0x");
        print_hex((key >> 32) as u32);
        print_hex(key as u32);
        print_str(b"\n");
        return false;
    }
    true
}

unsafe fn exec_paging_mark(key: u64) {
    let entries = exec_paging_seen_mut();
    if !entries.iter().any(|entry| *entry == key) {
        entries.push(key);
    }
}

#[inline]
fn exec_paging_keys(page: u64) -> (u64, u64, u64) {
    (
        EXEC_PAGING_SEEN_PDPT | (page >> 39),
        EXEC_PAGING_SEEN_PD | (page >> 30),
        EXEC_PAGING_SEEN_PT | (page >> 21),
    )
}

unsafe fn ensure_executive_paging_level(
    key: u64,
    object_type: u64,
    map_label: u64,
    page: u64,
    level: &[u8],
) -> bool {
    if exec_paging_seen(key) {
        return true;
    }
    if !exec_paging_prepare_mark(key, page, level) {
        return false;
    }
    let slot = alloc_slot();
    let retype = untyped_retype_r(CAP_INIT_UNTYPED, object_type, PAGING_BITS, 1, slot);
    if retype != 0 {
        print_str(b"[exec-paging] retype ");
        print_str(level);
        print_str(b" failed page=0x");
        print_hex((page >> 32) as u32);
        print_hex(page as u32);
        print_str(b" error=");
        print_u64(retype);
        print_str(b"\n");
        let _ = cnode_delete_recycle_r(slot);
        return false;
    }
    let map = paging_struct_map_r(slot, map_label, page, CAP_INIT_THREAD_VSPACE);
    if map == 0 {
        exec_paging_mark(key);
        return true;
    }
    if map == SEL4_DELETE_FIRST {
        let _ = cnode_delete_recycle_r(slot);
        exec_paging_mark(key);
        return true;
    }
    print_str(b"[exec-paging] map ");
    print_str(level);
    print_str(b" failed page=0x");
    print_hex((page >> 32) as u32);
    print_hex(page as u32);
    print_str(b" error=");
    print_u64(map);
    print_str(b"\n");
    let _ = cnode_delete_recycle_r(slot);
    false
}

pub(crate) unsafe fn ensure_executive_paging(page: u64) -> bool {
    let (pdpt, pd, pt) = exec_paging_keys(page);
    ensure_executive_paging_level(pdpt, OBJ_X86_PDPT, LBL_X86_PDPT_MAP, page, b"pdpt")
        && ensure_executive_paging_level(
            pd,
            OBJ_X86_PAGE_DIRECTORY,
            LBL_X86_PAGE_DIRECTORY_MAP,
            page,
            b"pd",
        )
        && ensure_executive_paging_level(
            pt,
            OBJ_X86_PAGE_TABLE,
            LBL_X86_PAGE_TABLE_MAP,
            page,
            b"pt",
        )
}

unsafe fn map_boot_proof_alias(frame: u64) -> (u64, u64) {
    for _ in 0..512 {
        let alias = NEXT_BOOT_PROOF_ALIAS.fetch_sub(0x1000, Ordering::Relaxed);
        if !(BOOT_PROOF_ALIAS_BASE..BOOT_PROOF_ALIAS_END).contains(&alias) {
            return (0, SEL4_RANGE_ERROR);
        }
        if !ensure_executive_paging(alias) {
            return (0, SEL4_FAILED_LOOKUP);
        }
        let map = page_map_r(frame, alias, RW_NX, CAP_INIT_THREAD_VSPACE);
        if map == 0 {
            return (alias, 0);
        }
        if map != SEL4_DELETE_FIRST {
            return (0, map);
        }
    }
    (0, SEL4_DELETE_FIRST)
}

/// Map the page tables backing one hosted process's 64 MiB demand-fault scratch window
/// (`*_SCRATCH_BASE`) in the executive's own VSpace. Each demand fill takes a UNIQUE monotonic
/// scratch slot within this window (`scratch_base + faults*0x1000`), so it must cover FAULT_CAP
/// pages; 16 PTs = 8192 pages > FAULT_CAP (6000). Called once per process at spawn.
pub(crate) unsafe fn map_demand_scratch_pts(base: u64) {
    // 32 PTs × 2 MiB = the FULL 64 MiB DEMAND_SCRATCH_WINDOW (16384 scratch slots). Raised from 16
    // (32 MiB / 8192 slots) for (A) EAGER IMAGE-MAP: an eager whole-image fill front-loads every
    // per-process page of a process's DLL tree into scratch in one pass, so a service (lsass loads
    // ~57 DLLs) can need well over 8192 slots. Backing the full window keeps the fresh-fill's unique
    // monotonic scratch slot (`scratch_base + faults*0x1000`) inside mapped PTs. Cheap (16 extra PTs).
    for k in 0..32u64 {
        assert!(ensure_executive_paging(base + k * 0x20_0000));
    }
}
// --- ITEM 2b: seL4 MECHANISM teardown (reclamation) invocations, SYS_CALL so they RETURN the error
// label (0 = success). `TCBSuspend`=12 / `CNodeDelete`=23 (kernel InvocationLabel). CNodeDelete on a
// slot under the ROOT CNode is the FULL reclamation primitive — the kernel (src/invocation.rs
// cnode_delete) does, in one call: (1) suspend the TCB on a Thread-cap delete; (2) unmap a mapped
// Frame's PTE + TLB-shootdown; (3) release the object's pool slot when it was the last reference;
// (4) `reclaim_untyped_chain_at_tail` = roll the parent Untyped's `free_index` back so the bytes
// become allocatable again (return-to-Untyped). So full Untyped-return needs NO new kernel primitive.
const LBL_TCB_SUSPEND: u64 = 12;
const LBL_CNODE_DELETE: u64 = 23;
unsafe fn tcb_suspend_r(tcb: u64) -> u64 {
    let reply: u64;
    core::arch::asm!(
        "syscall",
        inout("rdx") SYS_CALL as u64 => _,
        inout("rdi") tcb => _,
        inout("rsi") LBL_TCB_SUSPEND << 12 => reply,
        inout("r10") 0u64 => _,
        inout("r8") 0u64 => _,
        inout("r9") 0u64 => _,
        in("r12") 0u64,
        in("r13") 0u64,
        lateout("r15") _, lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
    reply >> 12
}
/// `CNodeDelete` slot `idx` under the caller's ROOT CNode. Same legacy invocation shape as
/// `copy_cap_r`/`cnode_copy` (index in a2=r10, msginfo length 0 → the kernel defaults depth to
/// WORD_BITS, which resolves a direct root-CNode slot). Returns the error label (0 = success).
#[track_caller]
unsafe fn cnode_delete_r(idx: u64) -> u64 {
    if root_slot_is_pinned(idx) {
        let caller = core::panic::Location::caller();
        ROOT_SLOT_PIN_DELETE_REFUSALS.fetch_add(1, Ordering::Relaxed);
        print_str(b"[cap-owner] refused delete of pinned root slot=0x");
        print_hex((idx >> 32) as u32);
        print_hex(idx as u32);
        print_str(b" caller=");
        print_str(caller.file().as_bytes());
        print_str(b":");
        print_u64(caller.line() as u64);
        print_str(b"\n");
        return u64::MAX;
    }
    let reply: u64;
    core::arch::asm!(
        "syscall",
        inout("rdx") SYS_CALL as u64 => _,
        inout("rdi") CAP_INIT_THREAD_CNODE => _,
        inout("rsi") LBL_CNODE_DELETE << 12 => reply,
        inout("r10") idx => _, // a2 = slot index under the root CNode
        inout("r8") 0u64 => _, // a3 = depth (ignored; msginfo length 0 → WORD_BITS)
        inout("r9") 0u64 => _,
        in("r12") 0u64,
        in("r13") 0u64,
        lateout("r15") _, lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
    reply >> 12
}

pub(crate) unsafe fn cnode_delete_in_cnode_r(cnode: u64, idx: u64) -> u64 {
    let reply: u64;
    core::arch::asm!(
        "syscall",
        inout("rdx") SYS_CALL as u64 => _,
        inout("rdi") cnode => _,
        inout("rsi") LBL_CNODE_DELETE << 12 => reply,
        inout("r10") idx => _,
        inout("r8") 0u64 => _,
        inout("r9") 0u64 => _,
        in("r12") 0u64,
        in("r13") 0u64,
        lateout("r15") _, lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
    reply >> 12
}

#[track_caller]
pub(crate) unsafe fn cnode_delete_recycle_r(idx: u64) -> u64 {
    let label = cnode_delete_r(idx);
    if label == 0 {
        recycle_deleted_root_slot(idx);
    }
    label
}
/// CNodeRevoke on the cap at `idx` under the root CNode: delete all its descendants (and, for an
/// Untyped cap, roll its `free_index` back to 0 = full-capacity reclamation). Mirror of
/// `cnode_delete_r`; used by the reclamation self-test to definitively reset a throwaway child
/// untyped between fill rounds (plain per-object delete didn't reset free_index under a deeper boot).
const LBL_CNODE_REVOKE: u64 = 22;
pub(crate) unsafe fn cnode_revoke_r(idx: u64) -> u64 {
    let reply: u64;
    core::arch::asm!(
        "syscall",
        inout("rdx") SYS_CALL as u64 => _,
        inout("rdi") CAP_INIT_THREAD_CNODE => _,
        inout("rsi") LBL_CNODE_REVOKE << 12 => reply,
        inout("r10") idx => _, // a2 = slot index under the root CNode
        inout("r8") 0u64 => _, // a3 = depth (ignored; msginfo length 0 → WORD_BITS)
        inout("r9") 0u64 => _,
        in("r12") 0u64,
        in("r13") 0u64,
        lateout("r15") _, lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
    reply >> 12
}
/// Retype `num` objects of `obj` (size `bits`) from an ARBITRARY untyped cap `untyped` into `dest`.
/// (`untyped_retype_r` hardcodes `CAP_INIT_UNTYPED`; the reclamation self-test carves + fills a
/// throwaway CHILD untyped.) Returns the error label (0 = success; non-zero once the untyped is
/// exhausted).
unsafe fn untyped_retype_from_r(untyped: u64, obj: u64, bits: u32, num: u32, dest: u64) -> u64 {
    let size_num = ((bits as u64) << 32) | (num as u64);
    let reply: u64;
    core::arch::asm!(
        "syscall",
        inout("rdx") SYS_CALL as u64 => _,
        inout("rdi") untyped => _,
        inout("rsi") LBL_UNTYPED_RETYPE << 12 => reply,
        inout("r10") obj => _,
        inout("r8") size_num => _,
        inout("r9") dest => _,
        in("r12") 0u64,
        in("r13") 0u64,
        lateout("r15") _, lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
    let label = reply >> 12;
    if label == 0 {
        root_slot_note_occupied(dest);
    }
    label
}

unsafe fn sched_control_configure_r(sc: u64, budget: u64, period: u64) -> u64 {
    let reply: u64;
    core::arch::asm!(
        "syscall",
        inout("rdx") SYS_CALL as u64 => _,
        inout("rdi") SLOT_SCHED_CONTROL => _,
        inout("rsi") LBL_SCHED_CONTROL_CONFIGURE << 12 => reply,
        inout("r10") sc => _,
        inout("r8") budget => _,
        inout("r9") period => _,
        in("r12") 0u64,
        in("r13") 0u64,
        lateout("r15") _, lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
    reply >> 12
}

unsafe fn sched_context_bind_r(sc: u64, tcb: u64) -> u64 {
    let reply: u64;
    core::arch::asm!(
        "syscall",
        inout("rdx") SYS_CALL as u64 => _,
        inout("rdi") sc => _,
        inout("rsi") LBL_SCHED_CONTEXT_BIND << 12 => reply,
        inout("r10") tcb => _,
        inout("r8") 0u64 => _,
        inout("r9") 0u64 => _,
        in("r12") 0u64,
        in("r13") 0u64,
        lateout("r15") _, lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
    reply >> 12
}

unsafe fn attach_sched_context(tcb: u64) -> Result<u64, u64> {
    let Some(sc) = try_alloc_slot() else {
        return Err(u64::MAX);
    };
    let e_retype = untyped_retype_r(
        CAP_INIT_UNTYPED,
        OBJ_SCHED_CONTEXT,
        SCHED_CONTEXT_BITS,
        1,
        sc,
    );
    if e_retype != 0 {
        recycle_deleted_root_slot(sc);
        return Err(e_retype);
    }
    let e_configure = sched_control_configure_r(sc, 10, 10);
    if e_configure != 0 {
        let _ = cnode_delete_recycle_r(sc);
        return Err(e_configure);
    }
    let e_bind = sched_context_bind_r(sc, tcb);
    if e_bind != 0 {
        let _ = cnode_delete_recycle_r(sc);
        return Err(e_bind);
    }
    Ok(sc)
}

/// Build the page table for the relocated shared "cluster" region (rings, stack, IPC buffer,
/// sysarg, device MMIO, driver code/arena) at `WORK_CLUSTER_BASE` in `pml4`. The cluster used to
/// piggyback the image's 2 MiB PT; now that the working VAs moved high (out of the 64 MiB ELF
/// reserve) it needs its own PT in every executive-image VSpace and in the executive's own.
unsafe fn map_required_page_table(pml4: u64, base: u64, stage: &[u8]) -> u64 {
    let pt = alloc_slot();
    let retype = untyped_retype_r(CAP_INIT_UNTYPED, OBJ_X86_PAGE_TABLE, PAGING_BITS, 1, pt);
    if retype != 0 {
        print_str(b"[paging] retype ");
        print_str(stage);
        print_str(b" failed pml4=0x");
        print_hex((pml4 >> 32) as u32);
        print_hex(pml4 as u32);
        print_str(b" pt=0x");
        print_hex((pt >> 32) as u32);
        print_hex(pt as u32);
        print_str(b" error=");
        print_u64(retype);
        print_str(b"\n");
        panic!("required page-table retype failed");
    }

    let map = paging_struct_map_r(pt, LBL_X86_PAGE_TABLE_MAP, base, pml4);
    if map != 0 {
        let _ = cnode_delete_recycle_r(pt);
        print_str(b"[paging] map ");
        print_str(stage);
        print_str(b" failed pml4=0x");
        print_hex((pml4 >> 32) as u32);
        print_hex(pml4 as u32);
        print_str(b" base=0x");
        print_hex((base >> 32) as u32);
        print_hex(base as u32);
        print_str(b" error=");
        print_u64(map);
        print_str(b"\n");
        panic!("required page-table map failed");
    }
    if pml4 == CAP_INIT_THREAD_VSPACE {
        root_slot_pin(pt);
    }
    pt
}

unsafe fn map_required_paging_struct(
    pml4: u64,
    object_type: u64,
    map_label: u64,
    base: u64,
    stage: &[u8],
) {
    let cap = alloc_slot();
    let retype = untyped_retype_r(CAP_INIT_UNTYPED, object_type, PAGING_BITS, 1, cap);
    if retype != 0 {
        print_str(b"[paging] retype ");
        print_str(stage);
        print_str(b" failed pml4=0x");
        print_hex((pml4 >> 32) as u32);
        print_hex(pml4 as u32);
        print_str(b" cap=0x");
        print_hex((cap >> 32) as u32);
        print_hex(cap as u32);
        print_str(b" type=");
        print_u64(object_type);
        print_str(b" error=");
        print_u64(retype);
        print_str(b"\n");
        panic!("required paging-structure retype failed");
    }

    let map = paging_struct_map_r(cap, map_label, base, pml4);
    if map != 0 {
        let _ = cnode_delete_recycle_r(cap);
        print_str(b"[paging] map ");
        print_str(stage);
        print_str(b" failed pml4=0x");
        print_hex((pml4 >> 32) as u32);
        print_hex(pml4 as u32);
        print_str(b" base=0x");
        print_hex((base >> 32) as u32);
        print_hex(base as u32);
        print_str(b" label=");
        print_u64(map_label);
        print_str(b" error=");
        print_u64(map);
        print_str(b"\n");
        panic!("required paging-structure map failed");
    }
}

pub(crate) unsafe fn map_cluster_pt(pml4: u64) {
    map_required_page_table(pml4, WORK_CLUSTER_BASE, b"cluster-pt");
}

pub(crate) unsafe fn map_tp_worker_target_lane_pts(pml4: u64) {
    let mut base = TP_WORKER_SLOT0_REGION_BASE & !0x1f_ffff;
    let end =
        (tp_worker_high_region_base(TP_WORKER_SLOT_COUNT - 1) + TP_WORKER_EXEC_STRIDE + 0x1f_ffff)
            & !0x1f_ffff;
    while base < end {
        map_required_page_table(pml4, base, b"tp-worker-lane-pt");
        base += 0x20_0000;
    }
}

/// Build enough leaf page tables at `HEAP_BASE` to cover `frames` 4 KiB pages (one PT per 2 MiB).
/// The executive's own heap is larger than a spawned service's, so the two callers differ only in
/// how many they ask for.
unsafe fn map_heap_pts(pml4: u64, frames: u64) {
    let windows = frames.div_ceil(512).max(1);
    for window in 0..windows {
        map_required_page_table(
            pml4,
            allocator::HEAP_BASE as u64 + window * 0x20_0000,
            b"heap-pt",
        );
    }
}

pub(crate) unsafe fn map_hosted_client_env_pt(pml4: u64) {
    map_required_page_table(pml4, HOSTED_CLIENT_ENV_BASE, b"hosted-client-env-pt");
}

unsafe fn map_user_alloc_pt(pml4: u64) {
    map_required_page_table(pml4, USER_ALLOC_BASE, b"user-alloc-pt");
}

/// Build the standard executive-image paging skeleton in `pml4`: pdpt + pd for the image's 1 GiB
/// slot, one PT per 2 MiB of image (so the ELF can grow into its 64 MiB reserve), and the
/// relocated cluster PT. Callers then map the image frames + any region-specific buffer PTs. The
/// pd is 1 GiB-granular, so it also covers the cluster / heap / buffer PTs (all < 512 MiB).
pub(crate) unsafe fn map_image_skeleton(pml4: u64, img_count: u64) {
    map_required_paging_struct(
        pml4,
        OBJ_X86_PDPT,
        LBL_X86_PDPT_MAP,
        IMAGE_BASE,
        b"image-pdpt",
    );
    map_required_paging_struct(
        pml4,
        OBJ_X86_PAGE_DIRECTORY,
        LBL_X86_PAGE_DIRECTORY_MAP,
        IMAGE_BASE,
        b"image-pd",
    );
    // One PT per 2 MiB of image (512 4 KiB pages each). `.max(1)` keeps at least one even for a
    // trivially small image.
    let npt = ((img_count + 511) / 512).max(1);
    for k in 0..npt {
        map_required_page_table(pml4, IMAGE_BASE + k * 0x20_0000, b"image-pt");
    }
    map_cluster_pt(pml4);
}

/// Map the executive's OWN heap (so its front-end can allocate). Builds the heap PT first (the
/// heap is relocated far above the image, so — unlike before — the kernel's ELF PTs don't cover
/// it), then maps all HEAP_FRAMES at the relocated `HEAP_BASE`.
unsafe fn map_own_heap() {
    map_heap_pts(CAP_INIT_THREAD_VSPACE, allocator::HEAP_FRAMES);
    let Some(frame_base) = try_alloc_slot_run(allocator::HEAP_FRAMES) else {
        panic!("required executive heap cap run allocation failed");
    };
    let mut retyped = 0u64;
    while retyped < allocator::HEAP_FRAMES {
        let batch = (allocator::HEAP_FRAMES - retyped).min(ROOT_RETYPE_FAN_OUT_LIMIT);
        let error = untyped_retype_r(
            CAP_INIT_UNTYPED,
            OBJ_X86_4K_PAGE,
            PAGING_BITS,
            batch as u32,
            frame_base + retyped,
        );
        if error != 0 {
            print_str(b"[paging] retype executive-heap-frame-run failed base=0x");
            print_hex((frame_base >> 32) as u32);
            print_hex(frame_base as u32);
            print_str(b" index=");
            print_u64(retyped);
            print_str(b" batch=");
            print_u64(batch);
            print_str(b" error=");
            print_u64(error);
            print_str(b"\n");
            panic!("required executive heap frame retype failed");
        }
        retyped += batch;
    }
    root_slot_pin_run(frame_base, allocator::HEAP_FRAMES);
    for i in 0..allocator::HEAP_FRAMES {
        let f = frame_base + i;
        let va = allocator::HEAP_BASE as u64 + i * 0x1000;
        let map = page_map_r(f, va, RW_NX, CAP_INIT_THREAD_VSPACE);
        if map != 0 {
            let _ = cnode_delete_recycle_r(f);
            print_str(b"[paging] map executive-heap-page failed frame=0x");
            print_hex((f >> 32) as u32);
            print_hex(f as u32);
            print_str(b" va=0x");
            print_hex((va >> 32) as u32);
            print_hex(va as u32);
            print_str(b" error=");
            print_u64(map);
            print_str(b"\n");
            panic!("required executive heap page map failed");
        }
        // The initial rootserver has no external pager. Touch every page while the mapping
        // operation and cap are still in scope so a bad kernel mapping cannot survive until a
        // late allocator memcpy and appear as an unserviceable user fault.
        core::ptr::write_volatile(va as *mut u8, 0);
    }
}

/// Build a spawned service's VSpace: image RO+X, private heap, private stack, and
/// the four shared SURT frames at the shared vaddrs.
unsafe fn build_service_vspace(sub: u64, comp: u64, req: u64, rep: u64, heap_frames: u64) -> u64 {
    assert!(heap_frames != 0 && heap_frames <= allocator::HEAP_FRAMES);
    let img_start = IMAGE_FRAMES_START.load(Ordering::Relaxed);
    let img_count = IMAGE_FRAMES_COUNT.load(Ordering::Relaxed);
    let pml4 = alloc_slot();
    let retype = untyped_retype_r(CAP_INIT_UNTYPED, OBJ_X86_PML4, PAGING_BITS, 1, pml4);
    if retype != 0 {
        panic!("required service VSpace retype failed");
    }
    require_vspace_asid(pml4, b"isolated-service");
    map_image_skeleton(pml4, img_count);
    map_heap_pts(pml4, heap_frames);
    for i in 0..img_count {
        let cp = alloc_slot();
        let _ = syscall5(
            SYS_SEND,
            CAP_INIT_THREAD_CNODE,
            LBL_CNODE_COPY << 12,
            cp,
            img_start + i,
            0,
        );
        let _ = page_map(cp, IMAGE_BASE + i * 0x1000, /* RO */ 2, pml4);
    }
    for i in 0..heap_frames {
        let f = alloc_slot();
        let _ = untyped_retype(CAP_INIT_UNTYPED, OBJ_X86_4K_PAGE, PAGING_BITS, 1, f);
        let _ = page_map(f, allocator::HEAP_BASE as u64 + i * 0x1000, RW_NX, pml4);
    }
    for i in 0..STACK_FRAMES {
        let f = alloc_slot();
        let _ = untyped_retype(CAP_INIT_UNTYPED, OBJ_X86_4K_PAGE, PAGING_BITS, 1, f);
        let _ = page_map(f, STACK_BASE + i * 0x1000, RW_NX, pml4);
    }
    let _ = page_map(sub, SUB_RING_VADDR, RW_NX, pml4);
    let _ = page_map(comp, COMP_RING_VADDR, RW_NX, pml4);
    let _ = page_map(req, REQ_DATA_VADDR, RW_NX, pml4);
    let _ = page_map(rep, REP_DATA_VADDR, RW_NX, pml4);
    pml4
}

const KERNEL_SERVICE_PRIORITY: u64 = 200;

/// Spawn one isolated service component at `entry`, seeded with `seeds`.
unsafe fn spawn_service(
    entry: unsafe extern "C" fn(u64) -> !,
    seeds: &[(u64, u64)],
    sub: u64,
    comp: u64,
    req: u64,
    rep: u64,
    heap_frames: u64,
) {
    let pml4 = build_service_vspace(sub, comp, req, rep, heap_frames);
    let ipcbuf = alloc_slot();
    let _ = untyped_retype(CAP_INIT_UNTYPED, OBJ_X86_4K_PAGE, PAGING_BITS, 1, ipcbuf);
    let _ = page_map(ipcbuf, IPCBUF_VADDR, RW_NX, pml4);
    let raw = alloc_slot();
    let _ = untyped_retype(CAP_INIT_UNTYPED, OBJ_CNODE, CN_RADIX, 1, raw);
    let cnode = alloc_slot();
    let _ = syscall5(
        SYS_SEND,
        CAP_INIT_THREAD_CNODE,
        LBL_CNODE_MINT << 12,
        cnode,
        raw,
        CN_GUARD_BADGE,
    );
    let _ = syscall5(SYS_SEND, cnode, LBL_CNODE_COPY << 12, CT_PML4, pml4, 0);
    for &(slot, src) in seeds {
        let _ = syscall5(SYS_SEND, cnode, LBL_CNODE_COPY << 12, slot, src, 0);
    }
    let tcb = alloc_slot();
    let _ = untyped_retype(CAP_INIT_UNTYPED, OBJ_TCB, 0, 1, tcb);
    let _ = tcb_set_space(tcb, 0, cnode, pml4);
    let _ = syscall5(
        SYS_SEND,
        tcb,
        LBL_TCB_SET_IPC_BUFFER << 12,
        IPCBUF_VADDR,
        ipcbuf,
        0,
    );
    let stack_top = STACK_BASE + STACK_FRAMES * 0x1000 - 16;
    let _ = tcb_write_registers(tcb, entry as u64, stack_top, heap_frames);
    let _ = tcb_set_priority(tcb, KERNEL_SERVICE_PRIORITY);
    if let Err(e_sc) = attach_sched_context(tcb) {
        print_str(b"[thread-life] service SC attach failed tcb=0x");
        print_hex(tcb as u32);
        print_str(b" error=");
        print_u64(e_sc);
        print_str(b"\n");
        park();
    }
    let _ = tcb_resume(tcb);
}

// --- The executive's front-end: an ObjectClient over the SURT ring to the
// isolated Object Manager service. -------------------------------------------

/// One request/reply SURT channel to an isolated service, parameterized by its data
/// frame vaddrs — so the executive can hold several (one per service).
struct RingChannel<'a> {
    sq: Producer<SurtSqe>,
    cq: Consumer<SurtCqe>,
    signal: Sel4Notify<'a, KernelEnv>,
    wait_cptr: CPtr,
    req_vaddr: u64,
    rep_vaddr: u64,
    next_id: u64,
}
static SURT_CLIENT_TIMER_TICKS: AtomicU64 = AtomicU64::new(0);
static SURT_CLIENT_TIMER_DRAINS: AtomicU64 = AtomicU64::new(0);
static SURT_CLIENT_WAIT_WAKES: AtomicU64 = AtomicU64::new(0);

impl RingChannel<'_> {
    /// One synchronous request/reply: stage `in_buf` in the request frame, push the
    /// SQE, wait for the matching completion, copy the reply payload out. Returns
    /// `(status, flags, information, detail0, detail1)`.
    fn raw(&mut self, opcode: u16, in_buf: &[u8], out_buf: &mut [u8]) -> (i32, u32, u64, u64, u64) {
        // SAFETY: single request in flight; the ring push/pop orders these writes.
        unsafe {
            let dst = self.req_vaddr as *mut u8;
            for (i, b) in in_buf.iter().enumerate() {
                core::ptr::write_volatile(dst.add(i), *b);
            }
        }
        let id = self.next_id;
        self.next_id += 1;
        let sqe = SurtSqe {
            opcode,
            len: in_buf.len() as u32,
            request_id: id,
            offset: 0,
            ..Default::default()
        };
        while self.sq.try_push(sqe).is_err() {
            yield_now();
        }
        let _ = self.sq.notify_consumer(&self.signal);
        let mut out = (0i32, 0u32, 0u64, 0u64, 0u64);
        loop {
            match self.cq.try_pop() {
                Ok(Some(cqe)) => {
                    if cqe.request_id == id {
                        out = (
                            cqe.status,
                            cqe.flags,
                            cqe.information,
                            cqe.detail0,
                            cqe.detail1,
                        );
                        break;
                    }
                }
                Ok(None) => match self.cq.prepare_wait() {
                    Ok(WaitDecision::Ready) => {}
                    Ok(WaitDecision::Block) => unsafe {
                        self.wait_completion_timer_aware();
                    },
                    Err(_) => break,
                },
                Err(_) => break,
            }
        }
        let n = (out.2 as usize).min(out_buf.len());
        // SAFETY: reply frame holds `n` result bytes.
        unsafe {
            let src = self.rep_vaddr as *const u8;
            for (i, slot) in out_buf.iter_mut().enumerate().take(n) {
                *slot = core::ptr::read_volatile(src.add(i));
            }
        }
        out
    }

    unsafe fn wait_completion_timer_aware(&self) {
        let (_rax, badge, _info, _payload) = ep_recv(self.wait_cptr);
        if EXEC_DEADMAN_WATCHDOG {
            if badge == DELAY_TIMER_BADGE {
                watchdog_on_tick();
            } else {
                WATCHDOG_MSGS.fetch_add(1, Ordering::Relaxed);
            }
        }
        if badge == DELAY_TIMER_BADGE {
            let n = SURT_CLIENT_TIMER_TICKS.fetch_add(1, Ordering::Relaxed);
            DELAY_TIMER_TICKS_PENDING.fetch_add(1, Ordering::Relaxed);
            if drain_nested_pump_timer_delivery() {
                let drains = SURT_CLIENT_TIMER_DRAINS.fetch_add(1, Ordering::Relaxed);
                if drains < 8 {
                    print_str(b"[surt-client] timer-aware wait drained delay tick\n");
                }
            } else {
                delay_timer_nested_ack();
            }
            if n < 8 {
                print_str(b"[surt-client] HPET tick landed while waiting for completion\n");
            }
        } else {
            let n = SURT_CLIENT_WAIT_WAKES.fetch_add(1, Ordering::Relaxed);
            if n < 8 {
                print_str(b"[surt-client] completion notification woke client wait\n");
            }
        }
    }
}

/// The Object Manager transport wrapper.
struct ObChan<'a>(RingChannel<'a>);
impl nt_object_client::Backend for ObChan<'_> {
    fn call(&mut self, opcode: u16, in_buf: &[u8], out_buf: &mut [u8]) -> ObReply {
        let (status, _flags, information, detail0, detail1) = self.0.raw(opcode, in_buf, out_buf);
        ObReply {
            status,
            information: information as u32,
            detail0,
            detail1,
        }
    }
}

static mut OBJECT_CLIENT_PTR: *mut ObjectClient<ObChan<'static>> = core::ptr::null_mut();

unsafe fn install_object_manager_client(client: &mut ObjectClient<ObChan<'static>>) {
    OBJECT_CLIENT_PTR = client as *mut _;
}

pub(crate) unsafe fn object_manager_create_driver_path(
    path: &str,
    owner_component: u64,
    owner_local_id: u64,
) -> Result<u64, nt_status::NtStatus> {
    let client = OBJECT_CLIENT_PTR
        .as_mut()
        .ok_or(nt_status::NtStatus::DEVICE_NOT_READY)?;
    client
        .create_driver(path, owner_component, owner_local_id, true)
        .map(|id| id.0)
}

pub(crate) unsafe fn object_manager_create_device_path(
    path: &str,
    owner_component: u64,
    owner_local_id: u64,
) -> Result<u64, nt_status::NtStatus> {
    let client = OBJECT_CLIENT_PTR
        .as_mut()
        .ok_or(nt_status::NtStatus::DEVICE_NOT_READY)?;
    client
        .create_device(path, owner_component, owner_local_id, true)
        .map(|id| id.0)
}

pub(crate) unsafe fn object_manager_delete_path(path: &str) -> Result<(), nt_status::NtStatus> {
    let client = OBJECT_CLIENT_PTR
        .as_mut()
        .ok_or(nt_status::NtStatus::DEVICE_NOT_READY)?;
    client.delete_object(path, true)
}

pub(crate) unsafe fn object_manager_lookup_path(path: &str) -> Result<u64, nt_status::NtStatus> {
    let client = OBJECT_CLIENT_PTR
        .as_mut()
        .ok_or(nt_status::NtStatus::DEVICE_NOT_READY)?;
    client.lookup(path, true).map(|id| id.0)
}

pub(crate) unsafe fn object_manager_create_symbolic_link_path(
    link: &str,
    target: &str,
) -> Result<(), nt_status::NtStatus> {
    object_manager_create_symbolic_link_path_with_permanence(link, target, true).map(|_| ())
}

pub(crate) unsafe fn object_manager_create_symbolic_link_path_with_permanence(
    link: &str,
    target: &str,
    permanent: bool,
) -> Result<u64, nt_status::NtStatus> {
    let client = OBJECT_CLIENT_PTR
        .as_mut()
        .ok_or(nt_status::NtStatus::DEVICE_NOT_READY)?;
    client
        .create_symbolic_link(link, target, permanent)
        .map(|id| id.0)
}

pub(crate) unsafe fn object_manager_delete_symbolic_link_path(
    link: &str,
) -> Result<(), nt_status::NtStatus> {
    object_manager_delete_path(link)
}

pub(crate) unsafe fn object_manager_reparse_file_path(
    path: &[u16],
    output: &mut [u16],
) -> Result<usize, nt_status::NtStatus> {
    let client = OBJECT_CLIENT_PTR
        .as_mut()
        .ok_or(nt_status::NtStatus::DEVICE_NOT_READY)?;
    let reparsed = client.reparse_file_path(path, true)?;
    if reparsed.len() > output.len() {
        return Err(nt_status::NtStatus::OBJECT_NAME_INVALID);
    }
    output[..reparsed.len()].copy_from_slice(&reparsed);
    Ok(reparsed.len())
}

pub(crate) unsafe fn object_manager_create_file_handle(
    owner_component: u64,
    owner_local_id: u64,
    device_object: u64,
    desired_access: nt_types::AccessMask,
) -> Result<(u64, u64), nt_status::NtStatus> {
    let client = OBJECT_CLIENT_PTR
        .as_mut()
        .ok_or(nt_status::NtStatus::DEVICE_NOT_READY)?;
    client
        .create_file_handle(
            owner_component,
            owner_local_id,
            nt_types::ObjectId(device_object),
            desired_access,
        )
        .map(|(file, handle)| (file.0, handle.0))
}

pub(crate) unsafe fn object_manager_reference_file_handle(
    handle: nt_types::HandleValue,
    desired_access: nt_types::AccessMask,
) -> Result<u64, nt_status::NtStatus> {
    let client = OBJECT_CLIENT_PTR
        .as_mut()
        .ok_or(nt_status::NtStatus::DEVICE_NOT_READY)?;
    client
        .reference_file_handle(handle, desired_access)
        .map(|id| id.0)
}

