/// The executive's client to the isolated `lpc-server` component. Set once in
/// `_start` after `stand_up_service`; the LPC syscall handlers reach it via
/// [`lpc_client`] (single-threaded executive → the `static mut` is race-free).
static mut LPC_CLIENT: Option<LpcClient<LpcChan<'static>>> = None;

/// Borrow the LPC client (None until the service is stood up).
///
/// # Safety
/// Single-threaded executive; no aliasing across the one service loop.
unsafe fn lpc_client() -> Option<&'static mut LpcClient<LpcChan<'static>>> {
    (*core::ptr::addr_of_mut!(LPC_CLIENT)).as_mut()
}

// --- Native syscall trap front-end -----------------------------------------
// The executive catches a user thread's `syscall` (delivered as a seL4
// UnknownSyscall fault), routes it to the owning isolated service over SURT, and
// replies register-accurately so the user resumes past the syscall. (Trap/reply
// mechanics ported from driver-host-ntdll, which services real ntdll.)

unsafe fn ep_recv_full(ep: u64) -> (u64, u64, u64, u64, u64, u64) {
    let badge: u64;
    let msginfo: u64;
    let mr0: u64;
    let mr1: u64;
    let mr2: u64;
    let mr3: u64;
    core::arch::asm!(
        "syscall",
        in("rdx") SYS_RECV as u64,
        inout("rdi") ep => badge,
        in("r12") 0u64,
        in("r13") 0u64,
        lateout("rsi") msginfo,
        lateout("r10") mr0,
        lateout("r8") mr1,
        lateout("r9") mr2,
        lateout("r15") mr3,
        lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
    (badge, msginfo, mr0, mr1, mr2, mr3)
}

/// Reply to the pending fault (resume the faulter with the staged registers) + recv
/// the next fault. `r0..r3` → reply MRs 0..3 (RAX,RBX,RCX,RDX); MRs 4+ from `set_reply_mr`.
unsafe fn reply_recv_full(
    recv_ep: u64,
    reply_len: u64,
    r0: u64,
    r1: u64,
    r2: u64,
    r3: u64,
) -> (u64, u64, u64, u64, u64) {
    let msginfo: u64;
    let mr0: u64;
    let mr1: u64;
    let mr2: u64;
    let mr3: u64;
    core::arch::asm!(
        "syscall",
        in("rdx") SYS_REPLY_RECV as u64,
        inout("rdi") recv_ep => _,
        inout("rsi") reply_len => msginfo,
        inout("r10") r0 => mr0,
        inout("r8") r1 => mr1,
        inout("r9") r2 => mr2,
        inout("r15") r3 => mr3,
        in("r12") 0u64,
        in("r13") 0u64,
        lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
    (msginfo, mr0, mr1, mr2, mr3)
}

/// Resume the current caller and receive the next event, ALWAYS through the caller's **bound MCS
/// reply object** (`REPLY_MAIN`) — never through the legacy per-TCB `reply_to`. Also returns the
/// RECEIVED cap's badge (rdi on return): the service loop mints each hosted thread's fault-endpoint
/// cap with a distinct badge (smss=0, csrss=CSRSS_BADGE) so it can tell whose fault/syscall this is
/// and select that process's VSpace/image/scratch state.
///
/// ★ PHASE 3 (`docs/transport-migration.md` §7 item "the legacy `reply_to` reply"). This used to be
/// ONE `SYS_REPLY_RECV`, whose reply half targets `current.reply_to` (`syscall_handler.rs` →
/// `handle_reply`). That single per-TCB slot is written on the RECEIVER by every incoming `Call`, so
/// any component `Call` serviced while this client's syscall was in flight (an IRP/win32k dispatch
/// completion or one of its demand-page faults) silently re-pointed it at the COMPONENT — the
/// clobber that hung the first Phase-1 boot and that `COMPONENT_CALL_CLOBBERED_REPLY_TO` existed to
/// dodge. It is now a bound-reply `SYS_NB_SEND_RECV`: the send half targets the object the kernel
/// BOUND to this caller (`decode_reply` -> `replies[idx].bound_tcb`, which nothing else can
/// re-point), and the recv half
/// re-registers it for the next caller. That preserves the essential ReplyRecv property: the
/// executive has already armed its receive before the replied user thread can run arbitrary
/// user-mode code.
unsafe fn reply_recv_badge(
    recv_ep: u64,
    reply_len: u64,
    r0: u64,
    r1: u64,
    r2: u64,
    r3: u64,
) -> (u64, u64, u64, u64, u64, u64) {
    let reply_cptr = REPLY_MAIN_SLOT.load(Ordering::Relaxed);
    if reply_cptr == 0 {
        // Pre-retype (the demo/no-ntdll path reaches the loop before the reply objects exist):
        // fall back to the legacy `reply_to` reply. No component can have run yet, so `reply_to`
        // still names this caller.
        let badge: u64;
        let msginfo: u64;
        let mr0: u64;
        let mr1: u64;
        let mr2: u64;
        let mr3: u64;
        core::arch::asm!(
            "syscall",
            in("rdx") SYS_REPLY_RECV as u64,
            inout("rdi") recv_ep => badge,
            inout("rsi") reply_len => msginfo,
            inout("r10") r0 => mr0,
            inout("r8") r1 => mr1,
            inout("r9") r2 => mr2,
            inout("r15") r3 => mr3,
            in("r12") 0u64,
            in("r13") 0u64,
            lateout("rax") _, lateout("rcx") _, lateout("r11") _,
            options(nostack),
        );
        return (badge, msginfo, mr0, mr1, mr2, mr3);
    }
    client_reply_recv_badge(recv_ep, reply_cptr, reply_len, r0, r1, r2, r3)
}

/// `seL4_Recv(ep)` that ALSO registers a reply capability via the MCS `replyRegister` (r12): the
/// kernel binds `reply_cptr`'s Reply object to whichever thread's Call pairs with this recv
/// (finish_call -> replies[idx].bound_tcb = caller). A later Send on `reply_cptr` (decode_reply)
/// then resumes exactly that caller regardless of the single per-TCB `reply_to` slot — so a nested
/// faulting dispatch can't orphan an outer caller's pending reply. The kernel preserves the user's
/// r12 across the syscall (it reads it, never writes it), so `in` is sufficient.
unsafe fn recv_full_r12(ep: u64, reply_cptr: u64) -> (u64, u64, u64, u64, u64, u64) {
    let recv_started = disk_census_ticks();
    let badge: u64;
    let msginfo: u64;
    let mr0: u64;
    let mr1: u64;
    let mr2: u64;
    let mr3: u64;
    core::arch::asm!(
        "syscall",
        in("rdx") SYS_RECV as u64,
        inout("rdi") ep => badge,
        lateout("rsi") msginfo,
        lateout("r10") mr0,
        lateout("r8") mr1,
        lateout("r9") mr2,
        lateout("r15") mr3,
        in("r12") reply_cptr,
        in("r13") 0u64,
        lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
    RECV_BLOCKED_TICKS.fetch_add(
        disk_census_ticks().wrapping_sub(recv_started),
        Ordering::Relaxed,
    );
    RECV_CALLS.fetch_add(1, Ordering::Relaxed);
    // ★ THE DEADMAN LIVES HERE for hosted-thread endpoint receives, not at the service-loop top, so
    // it also covers nested rendezvous receives. Executive-side SURT client waits mirror this same
    // HPET-badge handling in `RingChannel::wait_completion_timer_aware`.
    if EXEC_DEADMAN_WATCHDOG {
        if badge == DELAY_TIMER_BADGE {
            watchdog_on_tick();
        } else {
            WATCHDOG_MSGS.fetch_add(1, Ordering::Relaxed);
        }
    }
    (badge, msginfo, mr0, mr1, mr2, mr3)
}

/// Reply through a caller-bound Reply cap and receive the next executive event in one kernel entry.
/// This is the bound-reply replacement for legacy `ReplyRecv`: r13 names the Reply cap consumed by
/// the send half, and r12 offers the same Reply cap to the receive half for the next client `Call`.
unsafe fn client_reply_recv_badge(
    recv_ep: u64,
    reply_cptr: u64,
    reply_len: u64,
    r0: u64,
    r1: u64,
    r2: u64,
    r3: u64,
) -> (u64, u64, u64, u64, u64, u64) {
    let recv_started = disk_census_ticks();
    let badge: u64;
    let msginfo: u64;
    let mr0: u64;
    let mr1: u64;
    let mr2: u64;
    let mr3: u64;
    core::arch::asm!(
        "syscall",
        in("rdx") SYS_NB_SEND_RECV as u64,
        inout("rdi") recv_ep => badge,
        inout("rsi") reply_len => msginfo,
        inout("r10") r0 => mr0,
        inout("r8") r1 => mr1,
        inout("r9") r2 => mr2,
        inout("r15") r3 => mr3,
        in("r12") reply_cptr,
        in("r13") reply_cptr,
        lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
    RECV_BLOCKED_TICKS.fetch_add(
        disk_census_ticks().wrapping_sub(recv_started),
        Ordering::Relaxed,
    );
    RECV_CALLS.fetch_add(1, Ordering::Relaxed);
    CLIENT_REPLY_BOUND.fetch_add(1, Ordering::Relaxed);
    if EXEC_DEADMAN_WATCHDOG {
        if badge == DELAY_TIMER_BADGE {
            watchdog_on_tick();
        } else {
            WATCHDOG_MSGS.fetch_add(1, Ordering::Relaxed);
        }
    }
    (badge, msginfo, mr0, mr1, mr2, mr3)
}

/// ★ THE reply primitive: resume a `Cap::Reply` object's BOUND caller (kernel `decode_reply`),
/// applying `apply_fault_reply` when that caller is blocked on a fault (the win32k/csrss demand-page
/// and syscall replies are all fault replies) and a full message transfer otherwise. MR0..3 ride in
/// r10/r8/r9/r15; MR4+ come from the IPC buffer (`set_reply_mr`).
///
/// It NEVER blocks: `decode_reply` either wakes `replies[idx].bound_tcb` or fails immediately. That
/// non-blocking property is the whole point of the migration — it is what replaced the executive's
/// blocking wake `Send` (`docs/transport-migration.md` defect 3).
///
/// Issued as **`SYS_CALL`**, not `SYS_SEND`, so the kernel's non-endpoint invocation arm
/// (`syscall_handler.rs` `handle_send`'s `other =>` → `decode_invocation` →
/// `invocation.rs::decode_reply`) writes the invocation's error label into `rsi` and this function
/// can RETURN it. `tasks/lessons.md`: *"seL4 SYS_SEND invocations HIDE ALL errors — use SYS_CALL
/// when a failure would be silent."* Replying to an UNBOUND reply object is exactly such a failure:
/// it means we believed a thread was blocked awaiting this reply when it was not, i.e. an invariant
/// break. This form returns `seL4_InvalidCapability` (**2**, `rust-micro/src/types.rs`) for it
/// instead of vanishing. `SYS_SEND`'s error-swallowing predecessor (`send_on_reply`) is DELETED —
/// kill-list item 3, the last of the 34.
///
/// Two wrappers add the bookkeeping their plane needs: [`client_reply_on`] (hosted clients) and
/// `spawn_hosts::pump_reply_on` (components). Nothing else calls this directly except the
/// deliberately-unbound negative-control probe in the gate.
unsafe fn reply_on(reply_cptr: u64, msginfo: u64, r0: u64, r1: u64, r2: u64, r3: u64) -> u64 {
    let reply: u64;
    core::arch::asm!(
        "syscall",
        inout("rdx") SYS_CALL as u64 => _,
        inout("rdi") reply_cptr => _,
        inout("rsi") msginfo => reply,
        inout("r10") r0 => _,
        inout("r8") r1 => _,
        inout("r9") r2 => _,
        inout("r15") r3 => _,
        in("r12") 0u64,
        in("r13") 0u64,
        lateout("rax") _, lateout("rcx") _, lateout("r11") _,
        options(nostack),
    );
    reply >> 12
}

/// ★ Non-zero `reply_on` labels on the **client** plane (`REPLY_MAIN` + the stolen/parked reply
/// objects), the counterpart of `spawn_hosts::PUMP_REPLY_ERRORS` for the component plane. A non-zero
/// label means we replied to an UNBOUND object — we believed a hosted thread was blocked awaiting
/// this reply and it was not. Reported by `exec_client_reply_bound`.
pub(crate) static CLIENT_REPLY_ERRORS: AtomicU64 = AtomicU64::new(0);
/// Client-plane replies issued through a bound reply object (`decode_reply`). Post-Phase-3 this is
/// EVERY reply the service loop makes: the legacy `reply_to` reply is retired.
pub(crate) static CLIENT_REPLY_BOUND: AtomicU64 = AtomicU64::new(0);

/// ★ THE ONE client-plane reply primitive (`docs/transport-migration.md` §7 item 3). Replaces the
/// error-SWALLOWING `send_on_reply` (a `SYS_SEND`, whose invocation errors vanish) with the
/// error-RETURNING [`reply_on`], counting any non-zero label into [`CLIENT_REPLY_ERRORS`] and
/// logging the first few. Identical register layout and identical kernel path
/// (`decode_invocation` → `decode_reply`); only the syscall number and the error visibility differ.
/// Every call site replies with message LABEL 0 (`msginfo` carries a length only) — a non-zero label
/// would be parsed as an `InvocationLabel` by `decode_invocation` and rejected before reaching
/// `decode_reply` (migration correction 1).
unsafe fn client_reply_on(
    reply_cptr: u64,
    msginfo: u64,
    r0: u64,
    r1: u64,
    r2: u64,
    r3: u64,
) -> bool {
    let label = reply_on(reply_cptr, msginfo, r0, r1, r2, r3);
    CLIENT_REPLY_BOUND.fetch_add(1, Ordering::Relaxed);
    if label != 0 && CLIENT_REPLY_ERRORS.fetch_add(1, Ordering::Relaxed) < 8 {
        print_str(b"[client-reply] UNBOUND reply object cptr=");
        print_u64(reply_cptr);
        print_str(b" label=");
        print_u64(label);
        print_str(b" mi=");
        print_u64(msginfo);
        print_str(b"\n");
    }
    label == 0
}

/// Resume a parked NT syscall without borrowing register words from the caller currently being
/// serviced. Hosted `syscall` faults require the complete saved register file; native seL4 calls
/// require only the terminal status word.
unsafe fn reply_parked_syscall(
    reply_cptr: u64,
    continuation: nt_syscall_abi::ParkedSyscallReply,
    status: u64,
) -> bool {
    let registers = continuation.registers_with_status(status);
    let length = continuation.message_length();
    for (index, value) in registers.iter().copied().enumerate().take(length).skip(4) {
        set_reply_mr(index, value);
    }
    client_reply_on(
        reply_cptr,
        length as u64,
        registers[0],
        registers[1],
        registers[2],
        registers[3],
    )
}

#[inline]
fn fallback_monotonic_time_100ns() -> u64 {
    unsafe { core::arch::x86_64::_rdtsc() / 10 }
}

#[inline]
unsafe fn hpet_counter_time_100ns(period_fs: u64) -> u64 {
    let ticks = core::ptr::read_volatile((HPET_VADDR + HPET_MAIN_COUNTER) as *const u64);
    nt_delay_execution::ticks_to_100ns(ticks, period_fs)
}

unsafe fn initialize_hpet_monotonic_epoch(period_fs: u64) {
    if period_fs == 0 || HPET_MONOTONIC_READY.load(Ordering::Acquire) {
        return;
    }
    let fallback_now = fallback_monotonic_time_100ns();
    let counter_now = hpet_counter_time_100ns(period_fs);
    let offset = nt_delay_execution::counter_epoch_offset(fallback_now, counter_now);
    HPET_MONOTONIC_OFFSET_100NS.store(offset, Ordering::Relaxed);
    HPET_MONOTONIC_READY.store(true, Ordering::Release);
    print_str(b"[hpet-clock] monotonic epoch fallback=");
    print_u64(fallback_now);
    print_str(b" counter=");
    print_u64(counter_now);
    print_str(b" offset=");
    if offset < 0 {
        print_str(b"-");
        print_u64(offset.unsigned_abs());
    } else {
        print_u64(offset as u64);
    }
    print_str(b"\n");
}

#[inline]
fn hpet_counter_deadline_100ns(deadline_100ns: u64) -> u64 {
    let offset = HPET_MONOTONIC_OFFSET_100NS.load(Ordering::Relaxed);
    nt_delay_execution::counter_time_from_epoch(deadline_100ns, offset)
}

fn monotonic_time_100ns() -> u64 {
    let period = HPET_PERIOD_FS.load(Ordering::Relaxed);
    if period != 0 && HPET_MONOTONIC_READY.load(Ordering::Acquire) {
        let offset = HPET_MONOTONIC_OFFSET_100NS.load(Ordering::Relaxed);
        unsafe {
            nt_delay_execution::epoch_time_from_counter(hpet_counter_time_100ns(period), offset)
        }
    } else {
        fallback_monotonic_time_100ns()
    }
}

fn nt_time_snapshot_at(monotonic_100ns: u64) -> nt_delay_execution::TimeSnapshot {
    unsafe { (&*core::ptr::addr_of!(NT_SYSTEM_CLOCK)).snapshot(monotonic_100ns) }
}

fn nt_time_snapshot() -> nt_delay_execution::TimeSnapshot {
    nt_time_snapshot_at(monotonic_time_100ns())
}

fn nt_system_time_100ns() -> u64 {
    nt_time_snapshot().system_time_100ns
}

fn nt_system_boot_time_100ns() -> u64 {
    NT_SYSTEM_BOOT_TIME_100NS.load(Ordering::Acquire) as u64
}

unsafe fn nt_set_system_time_100ns(
    new_system_time_100ns: u64,
) -> Result<nt_time::SystemTimeChange, nt_time::ClockError> {
    let monotonic_100ns = monotonic_time_100ns();
    let change = (&mut *core::ptr::addr_of_mut!(NT_SYSTEM_CLOCK))
        .set_system_time(monotonic_100ns, new_system_time_100ns)?;
    let previous_boot = NT_SYSTEM_BOOT_TIME_100NS.load(Ordering::Relaxed) as i128;
    let adjusted_boot = previous_boot + change.delta_100ns;
    debug_assert!(adjusted_boot >= i64::MIN as i128 && adjusted_boot <= i64::MAX as i128);
    NT_SYSTEM_BOOT_TIME_100NS.store(adjusted_boot as i64, Ordering::Release);
    Ok(change)
}

unsafe fn publish_kuser_clocks() {
    let now = nt_time_snapshot();
    for_each_kuser_page_alias(|alias| {
        nt_ntdll_layout::kuser::publish_clocks(
            alias as *mut u8,
            now.monotonic_100ns,
            now.system_time_100ns,
        );
    });
    KUSER_CLOCK_PUBLISH_COUNT.fetch_add(1, Ordering::Relaxed);
}

fn print_hex_u64(value: u64) {
    print_hex((value >> 32) as u32);
    print_hex(value as u32);
}

unsafe fn wait_reply_pool_mut() -> &'static mut Vec<WaitReplyPoolRecord> {
    &mut *core::ptr::addr_of_mut!(WAIT_REPLY_POOL)
}

unsafe fn wait_reply_pool_ref() -> &'static Vec<WaitReplyPoolRecord> {
    &*core::ptr::addr_of!(WAIT_REPLY_POOL)
}

fn wait_reply_pool_initialize(active_reply_cap: u64, initial_reserve: usize) -> bool {
    if active_reply_cap == 0 {
        WAIT_REPLY_POOL_STORE_FAILURES.fetch_add(1, Ordering::Relaxed);
        return false;
    }
    unsafe {
        let pool = wait_reply_pool_mut();
        pool.clear();
        if pool.capacity() < initial_reserve {
            let additional = initial_reserve - pool.capacity();
            if pool.try_reserve_exact(additional).is_err() {
                WAIT_REPLY_POOL_ALLOCATION_FAILURES.fetch_add(1, Ordering::Relaxed);
                WAIT_REPLY_POOL_STORE_FAILURES.fetch_add(1, Ordering::Relaxed);
                return false;
            }
        }
        pool.push(WaitReplyPoolRecord {
            cap: active_reply_cap,
            used: true,
        });
    }
    true
}

fn wait_reply_pool_insert_cap(cap: u64, used: bool) -> Option<usize> {
    if cap == 0 {
        WAIT_REPLY_POOL_STORE_FAILURES.fetch_add(1, Ordering::Relaxed);
        return None;
    }
    unsafe {
        let pool = wait_reply_pool_mut();
        if let Some(index) = pool.iter().position(|record| record.cap == 0) {
            pool[index] = WaitReplyPoolRecord { cap, used };
            return Some(index);
        }
        if pool.len() == pool.capacity() && pool.try_reserve(1).is_err() {
            WAIT_REPLY_POOL_ALLOCATION_FAILURES.fetch_add(1, Ordering::Relaxed);
            WAIT_REPLY_POOL_STORE_FAILURES.fetch_add(1, Ordering::Relaxed);
            return None;
        }
        pool.push(WaitReplyPoolRecord { cap, used });
        Some(pool.len() - 1)
    }
}

fn wait_reply_pool_allocate_spare() -> Option<(usize, u64)> {
    let cap = match try_alloc_slot() {
        Some(cap) => cap,
        None => {
            WAIT_REPLY_POOL_SLOT_FAILURES.fetch_add(1, Ordering::Relaxed);
            return None;
        }
    };
    let retype = unsafe { untyped_retype_r(CAP_INIT_UNTYPED, OBJ_REPLY, 0, 1, cap) };
    if retype != 0 {
        WAIT_REPLY_POOL_RETYPE_FAILURES.fetch_add(1, Ordering::Relaxed);
        unsafe {
            recycle_deleted_root_slot(cap);
        }
        return None;
    }
    match wait_reply_pool_insert_cap(cap, false) {
        Some(index) => Some((index, cap)),
        None => {
            let _ = unsafe { cnode_delete_recycle_r(cap) };
            None
        }
    }
}

fn wait_reply_pool_find_free() -> Option<(usize, u64)> {
    unsafe {
        let pool = wait_reply_pool_ref();
        if let Some((index, record)) = pool
            .iter()
            .enumerate()
            .find(|(_, record)| record.cap != 0 && !record.used)
        {
            return Some((index, record.cap));
        }
    }
    wait_reply_pool_allocate_spare()
}

fn wait_reply_pool_has_free() -> bool {
    if REPLY_MAIN_SLOT.load(Ordering::Relaxed) == 0 {
        return false;
    }
    wait_reply_pool_find_free().is_some()
}

fn wait_reply_pool_find_cap(cap: u64) -> Option<usize> {
    if cap == 0 {
        return None;
    }
    unsafe {
        wait_reply_pool_ref()
            .iter()
            .position(|record| record.cap == cap)
    }
}

fn wait_reply_pool_mark_used(index: usize) {
    unsafe {
        if let Some(record) = wait_reply_pool_mut().get_mut(index) {
            if record.cap != 0 {
                record.used = true;
            }
        }
    }
}

fn wait_reply_pool_mark_free(index: usize) {
    unsafe {
        if let Some(record) = wait_reply_pool_mut().get_mut(index) {
            record.used = false;
        }
    }
}

fn wait_reply_pool_clear_cap(index: usize) {
    unsafe {
        if let Some(record) = wait_reply_pool_mut().get_mut(index) {
            record.cap = 0;
            record.used = false;
        }
    }
}

fn wait_reply_pool_used_count() -> u64 {
    unsafe {
        wait_reply_pool_ref()
            .iter()
            .filter(|record| record.cap != 0 && record.used)
            .count() as u64
    }
}

fn wait_reply_pool_live_count() -> u64 {
    unsafe {
        wait_reply_pool_ref()
            .iter()
            .filter(|record| record.cap != 0)
            .count() as u64
    }
}

fn wait_reply_pool_record_count() -> u64 {
    unsafe { wait_reply_pool_ref().len() as u64 }
}

fn wait_reply_pool_capacity() -> u64 {
    unsafe { wait_reply_pool_ref().capacity() as u64 }
}

fn wait_reply_pool_stats() -> (u64, u64, u64, u64, u64, u64, u64, u64) {
    (
        wait_reply_pool_used_count(),
        wait_reply_pool_live_count(),
        wait_reply_pool_record_count(),
        wait_reply_pool_capacity(),
        WAIT_REPLY_POOL_ALLOCATION_FAILURES.load(Ordering::Relaxed),
        WAIT_REPLY_POOL_SLOT_FAILURES.load(Ordering::Relaxed),
        WAIT_REPLY_POOL_RETYPE_FAILURES.load(Ordering::Relaxed),
        WAIT_REPLY_POOL_STORE_FAILURES.load(Ordering::Relaxed),
    )
}

fn release_reply_pool_cap(cap: u64) {
    if let Some(index) = wait_reply_pool_find_cap(cap) {
        wait_reply_pool_mark_free(index);
    }
}

fn ioapic_route_pin_mask(pin: u64) -> u32 {
    if pin < 32 {
        1u32 << (pin as u32)
    } else {
        0
    }
}

fn highest_ioapic_route_pin(mask: u32) -> Option<u64> {
    if mask == 0 {
        None
    } else {
        Some((31 - mask.leading_zeros()) as u64)
    }
}

fn select_delay_hpet_route_pin(route_cap: u32, used_mask: u32) -> Option<u64> {
    highest_ioapic_route_pin(route_cap & !used_mask & !HPET_SHARED_IOAPIC_ROUTE_MASK)
}

unsafe fn delay_timer_init() -> bool {
    if DELAY_TIMER_HANDLER.load(Ordering::Relaxed) != 0 {
        let notification = DELAY_TIMER_NOTIFICATION.load(Ordering::Relaxed);
        if notification != 0 {
            // `delay_timer_shutdown` may temporarily unbind the root TCB when no timed waits are
            // live. Re-establish the production binding whenever a later wait reuses the timer.
            let _ = syscall5(
                SYS_SEND,
                1,
                LBL_TCB_BIND_NOTIFICATION << 12,
                notification,
                0,
                0,
            );
        }
        return true;
    }
    let period = HPET_PERIOD_FS.load(Ordering::Relaxed);
    if period == 0 {
        print_str(b"[delay] HPET unavailable; refusing nonzero immediate-success fallback\n");
        return false;
    }
    let initial_config = core::ptr::read_volatile((HPET_VADDR + HPET_T0_CONFIG) as *const u64);
    let route_cap = (initial_config >> 32) as u32;
    if route_cap == 0 {
        return false;
    }
    core::ptr::write_volatile(
        (HPET_VADDR + HPET_T0_CONFIG) as *mut u64,
        initial_config & !HPET_TN_INT_ENB,
    );
    core::ptr::write_volatile((HPET_VADDR + HPET_GEN_INT_STATUS) as *mut u64, 1);
    let used_mask = ioapic_route_pin_mask(HPET_PROBE_IOAPIC_PIN.load(Ordering::Relaxed));
    let Some(pin) = select_delay_hpet_route_pin(route_cap, used_mask) else {
        print_str(b"[delay] HPET timer0 has no non-shared IOAPIC route route_cap=0x");
        print_hex(route_cap);
        print_str(b" used=0x");
        print_hex(used_mask);
        print_str(b" shared=0x");
        print_hex(HPET_SHARED_IOAPIC_ROUTE_MASK);
        print_str(b"\n");
        return false;
    };
    let notification = make_object(OBJ_NOTIFICATION);
    let badged = alloc_slot();
    let _ = syscall5(
        SYS_SEND,
        CAP_INIT_THREAD_CNODE,
        LBL_CNODE_MINT << 12,
        badged,
        notification,
        DELAY_TIMER_BADGE,
    );
    let handler = alloc_slot();
    ioapic_issue_irq_handler(handler, pin, DELAY_TIMER_IRQ, 1, 0);
    let _ = irq_handler_set_notification(handler, badged);
    // The initial root TCB cap is slot 1. Binding lets an HPET signal cancel the executive's
    // blocking Recv on the hosted-process endpoint, returning DELAY_TIMER_BADGE with empty msginfo.
    let _ = syscall5(
        SYS_SEND,
        1,
        LBL_TCB_BIND_NOTIFICATION << 12,
        notification,
        0,
        0,
    );
    core::ptr::write_volatile((HPET_VADDR + HPET_GEN_INT_STATUS) as *mut u64, 1);
    // LEVEL-triggered (matching the IOAPIC pin we just issued) and DISARMED: the timer delivers
    // only while `delay_timer_rearm` has a real deadline to arm it with. Init used to set
    // `Tn_INT_ENB` here and never clear it again, which is what made the disarm path a no-op.
    let config = HPET_TN_INT_TYPE_LEVEL | (pin << 9);
    core::ptr::write_volatile((HPET_VADDR + HPET_T0_CONFIG) as *mut u64, config);
    let general = core::ptr::read_volatile((HPET_VADDR + HPET_GEN_CONF) as *const u64);
    initialize_hpet_monotonic_epoch(period);
    core::ptr::write_volatile((HPET_VADDR + HPET_GEN_CONF) as *mut u64, general | 1);
    DELAY_TIMER_HANDLER.store(handler, Ordering::Relaxed);
    DELAY_TIMER_NOTIFICATION.store(notification, Ordering::Relaxed);
    DELAY_TIMER_BADGED_NOTIFICATION.store(badged, Ordering::Relaxed);
    DELAY_TIMER_IOAPIC_PIN.store(pin, Ordering::Relaxed);
    print_str(b"[delay] timer ready pin=");
    print_u64(pin);
    print_str(b" irq=");
    print_u64(DELAY_TIMER_IRQ);
    print_str(b" period_fs=");
    print_u64(period);
    print_str(b" bound_badge=0x");
    print_hex_u64(DELAY_TIMER_BADGE);
    print_str(b"\n");
    true
}

unsafe fn delay_timer_next_deadline(
    queue: &nt_delay_execution::Queue,
    handler: &ExecNtHandler,
) -> Option<(u64, u64)> {
    let now = nt_time_snapshot();
    let delay_deadline = queue.next_deadline(now);
    let event_deadline = object_waiter_next_deadline(now);
    let keyed_deadline = unsafe { (&*core::ptr::addr_of!(KEYED_WAITERS)).next_deadline(now) };
    let keyed_release_deadline =
        unsafe { (&*core::ptr::addr_of!(KEYED_RELEASE_WAITERS)).next_deadline(now) };
    let io_completion_deadline =
        unsafe { (&*core::ptr::addr_of!(IO_COMPLETION_WAITERS)).next_deadline(now) };
    let user_timer_deadline = handler.user_timer_next_deadline(now);
    let hosted_kernel_timer_deadline = driver_launch::hosted_driver_timer_next_deadline();
    let hosted_driver_deadline = driver_launch::hosted_driver_wait_next_deadline();
    let deadman_deadline = watchdog_deadline();
    let deadline = delay_deadline
        .into_iter()
        .chain(event_deadline)
        .chain(keyed_deadline)
        .chain(keyed_release_deadline)
        .chain(io_completion_deadline)
        .chain(user_timer_deadline)
        .chain(hosted_kernel_timer_deadline)
        .chain(hosted_driver_deadline)
        .chain(deadman_deadline)
        .min()?;
    let source = if delay_deadline == Some(deadline) {
        DELAY_TIMER_SOURCE_DELAY_QUEUE
    } else if event_deadline == Some(deadline) {
        DELAY_TIMER_SOURCE_EVENT_WAIT
    } else if keyed_deadline == Some(deadline) {
        DELAY_TIMER_SOURCE_KEYED_WAIT
    } else if keyed_release_deadline == Some(deadline) {
        DELAY_TIMER_SOURCE_KEYED_RELEASE
    } else if io_completion_deadline == Some(deadline) {
        DELAY_TIMER_SOURCE_IO_COMPLETION
    } else if user_timer_deadline == Some(deadline) {
        DELAY_TIMER_SOURCE_USER_TIMER
    } else if hosted_kernel_timer_deadline == Some(deadline) {
        DELAY_TIMER_SOURCE_HOSTED_KERNEL_TIMER
    } else if hosted_driver_deadline == Some(deadline) {
        DELAY_TIMER_SOURCE_HOSTED_DRIVER
    } else {
        DELAY_TIMER_SOURCE_WATCHDOG
    };
    Some((deadline, source))
}

unsafe fn delay_timer_rearm(queue: &nt_delay_execution::Queue, handler: &ExecNtHandler) {
    let timer_handler = DELAY_TIMER_HANDLER.load(Ordering::Relaxed);
    if timer_handler == 0 {
        return;
    }
    let mut config = core::ptr::read_volatile((HPET_VADDR + HPET_T0_CONFIG) as *const u64);
    config &= !HPET_TN_INT_ENB;
    core::ptr::write_volatile((HPET_VADDR + HPET_T0_CONFIG) as *mut u64, config);
    core::ptr::write_volatile((HPET_VADDR + HPET_GEN_INT_STATUS) as *mut u64, 1);
    if let Some((deadline, source)) = delay_timer_next_deadline(queue, handler) {
        let period = HPET_PERIOD_FS.load(Ordering::Relaxed);
        let guard_ticks = delay_timer_min_arm_ticks(period);
        let now = core::ptr::read_volatile((HPET_VADDR + HPET_MAIN_COUNTER) as *const u64);
        let counter_deadline = hpet_counter_deadline_100ns(deadline);
        let deadline_target =
            nt_delay_execution::hundred_ns_to_ticks_ceil(counter_deadline, period);
        let target =
            nt_delay_execution::timer_arm_target_ticks(counter_deadline, period, now, guard_ticks);
        // Keep the comparator safely ahead of the enable edge. For accounting, still record when
        // the original deadline target has already passed; that means a wake path failed to drain
        // its due waiter promptly and the guarded rearm is only preventing a lost one-shot.
        if deadline_target <= now {
            TIMER_PAST_DEADLINE_REARMS.fetch_add(1, Ordering::Relaxed);
            TIMER_PAST_DEADLINE_SOURCE.store(source, Ordering::Relaxed);
        }
        LAST_REARM_DEADLINE.store(deadline, Ordering::Relaxed);
        LAST_REARM_SOURCE.store(source, Ordering::Relaxed);
        LAST_REARM_TARGET.store(target, Ordering::Relaxed);
        LAST_REARM_NOW.store(now, Ordering::Relaxed);
        LAST_REARM_ARMED.store(1, Ordering::Relaxed);
        core::ptr::write_volatile((HPET_VADDR + HPET_T0_COMPARATOR) as *mut u64, target);
        core::ptr::write_volatile((HPET_VADDR + HPET_GEN_INT_STATUS) as *mut u64, 1);
        if source == DELAY_TIMER_SOURCE_IO_COMPLETION {
            let trace = DELAY_TIMER_REARM_TRACE_N.fetch_add(1, Ordering::Relaxed);
            if trace < 16 {
                let completion_waiters = &*core::ptr::addr_of!(IO_COMPLETION_WAITERS);
                print_str(b"[delay-rearm] source=iocp deadline=");
                print_u64(deadline);
                print_str(b" now100=");
                print_u64(monotonic_time_100ns());
                print_str(b" hpet-now=0x");
                print_hex_u64(now);
                print_str(b" target=0x");
                print_hex_u64(target);
                print_str(b" waiters=");
                print_u64(completion_waiters.len() as u64);
                print_str(b"\n");
            }
        }
        // ARM. The comparator is written before the enable edge, with stale level status cleared on
        // both sides of the comparator write so an old assertion cannot storm as soon as we unmask.
        config |= HPET_TN_INT_ENB;
        core::ptr::write_volatile((HPET_VADDR + HPET_T0_CONFIG) as *mut u64, config);
    } else {
        // DISARM — nothing is waiting on time, so the timer must stop delivering entirely.
        // This used to clear `Tn_INT_TYPE_CNF` (bit 1) instead, leaving `Tn_INT_ENB` set with a
        // comparator now permanently BEHIND the main counter. The result was a self-sustaining
        // ~34 kHz interrupt storm: measured 2,745,189 spurious deliveries in one boot (99.9999% of
        // all ticks woke nothing), 80 s of the executive's single-threaded service loop, which
        // starved winlogon of the forward progress the desktop paint needs. See
        // `exec_delay_timer_disarms` and `docs/transport-migration.md` §5.
        LAST_REARM_ARMED.store(0, Ordering::Relaxed);
        config &= !HPET_TN_INT_ENB;
        core::ptr::write_volatile((HPET_VADDR + HPET_T0_CONFIG) as *mut u64, config);
    }
}

unsafe fn delay_timer_rearm_and_drain_overdue(
    queue: &mut nt_delay_execution::Queue,
    handler: &mut ExecNtHandler,
) -> u64 {
    delay_timer_rearm(queue, handler);
    delay_timer_drain_overdue_without_badge(queue, handler)
}

unsafe fn delay_park(
    handler: &mut ExecNtHandler,
    queue: &mut nt_delay_execution::Queue,
    deadline: nt_delay_execution::Deadline,
    reply_cap: u64,
    reply: nt_syscall_abi::ParkedSyscallReply,
    thread_id: u64,
    badge: u64,
) -> bool {
    if reply_cap == 0 || !delay_timer_init() {
        return false;
    }
    let Some((fresh_index, fresh)) = wait_reply_pool_find_free() else {
        return false;
    };
    let waiter = nt_delay_execution::Waiter {
        deadline,
        sequence: 0,
        reply_cap,
        reply,
        thread_id,
        badge,
    };
    if queue.insert(waiter).is_err() {
        return false;
    }
    wait_reply_pool_mark_used(fresh_index);
    REPLY_MAIN_SLOT.store(fresh, Ordering::Relaxed);
    DELAY_PARKED_COUNT.fetch_add(1, Ordering::Relaxed);
    thread_wait_state_mark_badge_waiting(handler, badge);
    let now = nt_time_snapshot();
    if deadline.is_due(now) {
        let _ = delay_wake_due(handler, queue, now.monotonic_100ns);
    }
    let _ = delay_timer_rearm_and_drain_overdue(queue, handler);
    true
}

unsafe fn delay_wake_due(
    handler: &mut ExecNtHandler,
    queue: &mut nt_delay_execution::Queue,
    now: u64,
) -> u64 {
    let mut woken = 0;
    let now = nt_time_snapshot_at(now);
    while let Some(waiter) = queue.pop_due(now) {
        let other_started = disk_census_ticks();
        DELAY_WOKEN_COUNT.fetch_add(1, Ordering::Relaxed);
        DELAY_WAKE_LAST_BADGE.store(waiter.badge, Ordering::Relaxed);
        let reply_started = disk_census_ticks();
        reply_parked_syscall(waiter.reply_cap, waiter.reply, 0);
        let reply_done = disk_census_ticks();
        DELAY_WAKE_REPLY_TICKS.fetch_add(reply_done.wrapping_sub(reply_started), Ordering::Relaxed);
        release_reply_pool_cap(waiter.reply_cap);
        thread_wait_state_clear_badge_ready(handler, waiter.badge);
        DELAY_WAKE_OTHER_TICKS.fetch_add(
            disk_census_ticks()
                .wrapping_sub(other_started)
                .wrapping_sub(reply_done.wrapping_sub(reply_started)),
            Ordering::Relaxed,
        );
        woken += 1;
    }
    woken
}

unsafe fn io_completion_wake_due(handler: &mut ExecNtHandler, now: u64) -> u64 {
    let mut woken = 0;
    let now_snapshot = nt_time_snapshot_at(now);
    while let Some(waiter) =
        unsafe { (&mut *core::ptr::addr_of_mut!(IO_COMPLETION_WAITERS)).pop_due(now_snapshot) }
    {
        let trace = IO_COMPLETION_TIMEOUT_TRACE_N.fetch_add(1, Ordering::Relaxed);
        if trace < 32 {
            print_str(b"[io-completion] TIMEOUT pi=");
            print_u64(waiter.process_index as u64);
            print_str(b" badge=");
            print_u64(waiter.badge);
            print_str(b" tid=");
            print_u64(waiter.thread_id);
            print_str(b" port=");
            print_u64(waiter.port_id as u64);
            print_str(b" deadline=");
            print_u64(
                waiter
                    .deadline
                    .monotonic_target(now_snapshot)
                    .unwrap_or(u64::MAX),
            );
            print_str(b" now=");
            print_u64(now);
            print_str(b"\n");
        }
        reply_parked_syscall(
            waiter.reply_cap,
            waiter.reply,
            nt_io_completion::STATUS_TIMEOUT as u64,
        );
        release_reply_pool_cap(waiter.reply_cap);
        thread_wait_state_clear_badge_ready(handler, waiter.badge);
        handler.release_io_completion_reference(waiter.port_id);
        IO_COMPLETION_TIMEOUT_COUNT.fetch_add(1, Ordering::Relaxed);
        woken += 1;
    }
    woken
}

unsafe fn user_timer_wake_due(handler: &mut ExecNtHandler, now: u64) -> u64 {
    let fired = handler.user_timer_fire_due(nt_time_snapshot_at(now));
    if fired != 0 {
        let woken = wait_wake_dispatcher_set(handler);
        USER_TIMER_FIRED_COUNT.fetch_add(fired, Ordering::Relaxed);
        fired + woken
    } else {
        0
    }
}

unsafe fn delay_timer_drain_due_work(
    queue: &mut nt_delay_execution::Queue,
    handler: &mut ExecNtHandler,
    now_100ns: u64,
) -> u64 {
    let watchdog_tick = subdrain!(8, watchdog_take_timer_work(now_100ns));
    subdrain!(0, delay_wake_due(handler, queue, now_100ns))
        + subdrain!(1, wait_wake_due(handler, now_100ns))
        + subdrain!(2, keyed_wait_wake_due(handler, now_100ns))
        + subdrain!(3, keyed_release_wait_wake_due(handler, now_100ns))
        + subdrain!(4, io_completion_wake_due(handler, now_100ns))
        + subdrain!(5, user_timer_wake_due(handler, now_100ns))
        + subdrain!(6, driver_launch::hosted_driver_timer_wake_due(now_100ns))
        + subdrain!(7, driver_launch::hosted_driver_wait_wake_due(now_100ns))
        + watchdog_tick
}

pub(crate) unsafe fn delay_timer_drain_overdue_without_badge(
    queue: &mut nt_delay_execution::Queue,
    handler: &mut ExecNtHandler,
) -> u64 {
    if DELAY_TIMER_HANDLER.load(Ordering::Relaxed) == 0 {
        return 0;
    }
    DRAIN_CALLS.fetch_add(1, Ordering::Relaxed);
    let scan_started = disk_census_ticks();
    let next = delay_timer_next_deadline(queue, handler);
    let now_100ns = monotonic_time_100ns();
    DRAIN_SCAN_TICKS.fetch_add(
        disk_census_ticks().wrapping_sub(scan_started),
        Ordering::Relaxed,
    );
    let Some((deadline, _source)) = next else {
        return 0;
    };
    if now_100ns < deadline {
        return 0;
    }
    DRAIN_DUE_HITS.fetch_add(1, Ordering::Relaxed);
    // Snapshot the per-sub-drain totals so a SLOW call can report its own deltas. Aggregates are
    // useless here: this path runs a handful of times per boot and one call can cost a minute.
    let mut before = [0u64; SUBDRAIN_N];
    for slot in 0..SUBDRAIN_N {
        before[slot] = SUBDRAIN_TICKS[slot].load(Ordering::Relaxed);
    }
    let work_started = disk_census_ticks();
    let woken = delay_timer_drain_due_work(queue, handler, now_100ns);
    let work_ticks = disk_census_ticks().wrapping_sub(work_started);
    DRAIN_WORK_TICKS.fetch_add(work_ticks, Ordering::Relaxed);
    // Print EVERY due drain, not just slow ones: the path fires only a handful of times per boot,
    // so this is a few lines, and a run that diverges before the expensive one still reports the
    // cheap ones — which is what tells us the shape.
    {
        print_str(b"[drain-due] total_ms=");
        print_u64(work_ticks / 1_000_000);
        print_str(b" woken=");
        print_u64(woken);
        print_str(b" by-subdrain:");
        for slot in 0..SUBDRAIN_N {
            let ms = SUBDRAIN_TICKS[slot]
                .load(Ordering::Relaxed)
                .wrapping_sub(before[slot])
                / 1_000_000;
            if ms == 0 {
                continue;
            }
            print_str(b" #");
            print_u64(slot as u64);
            print_str(b"=");
            print_u64(ms);
            print_str(b"ms");
        }
        print_str(b" delay-wake reply_ms=");
        print_u64(DELAY_WAKE_REPLY_TICKS.load(Ordering::Relaxed) / 1_000_000);
        print_str(b" other_ms=");
        print_u64(DELAY_WAKE_OTHER_TICKS.load(Ordering::Relaxed) / 1_000_000);
        print_str(b" badge=");
        print_u64(DELAY_WAKE_LAST_BADGE.load(Ordering::Relaxed));
        print_str(b"\n");
    }
    TIMER_DUE_WORK_DRAINS.fetch_add(1, Ordering::Relaxed);
    let rearm_started = disk_census_ticks();
    delay_timer_rearm(queue, handler);
    core::ptr::write_volatile((HPET_VADDR + HPET_GEN_INT_STATUS) as *mut u64, 1);
    delay_timer_ack_irq();
    DRAIN_REARM_TICKS.fetch_add(
        disk_census_ticks().wrapping_sub(rearm_started),
        Ordering::Relaxed,
    );
    woken
}

fn delay_timer_delivery_is_stale(config: u64, counter: u64, comparator: u64) -> bool {
    (config & HPET_TN_INT_ENB) == 0 || counter < comparator
}

unsafe fn delay_timer_ack_irq() {
    let handler = DELAY_TIMER_HANDLER.load(Ordering::Relaxed);
    if handler != 0 {
        let _ = syscall5(SYS_SEND, handler, LBL_IRQ_ACK << 12, 0, 0, 0);
    }
}

