fn thread_wait_state_set_tid(
    handler: &mut ExecNtHandler,
    tid: u64,
    state: nt_process::ThreadState,
) {
    if tid == 0 || tid > nt_process::ThreadId::MAX as u64 {
        return;
    }
    let _ = handler
        .pm
        .set_thread_state(tid as nt_process::ThreadId, state);
}

