#[derive(Clone, Copy)]
struct InlineAscii<const N: usize> {
    bytes: [u8; N],
    len: usize,
}

impl<const N: usize> InlineAscii<N> {
    const fn empty() -> Self {
        Self {
            bytes: [0; N],
            len: 0,
        }
    }

    fn set_bytes(&mut self, src: &[u8]) -> bool {
        if src.len() > N || src.iter().any(|&b| b > 0x7f) {
            return false;
        }
        self.bytes[..src.len()].copy_from_slice(src);
        self.len = src.len();
        true
    }

    fn set_str(&mut self, src: &str) -> bool {
        self.set_bytes(src.as_bytes())
    }

    fn as_bytes(&self) -> &[u8] {
        &self.bytes[..self.len]
    }

    fn as_str(&self) -> &str {
        core::str::from_utf8(self.as_bytes()).unwrap_or("")
    }
}

impl<const N: usize> AsRef<str> for InlineAscii<N> {
    fn as_ref(&self) -> &str {
        self.as_str()
    }
}

#[derive(Clone, Copy)]
struct InlinePlanString {
    ptr: *const u8,
    len: usize,
}

impl InlinePlanString {
    const fn empty() -> Self {
        Self {
            ptr: core::ptr::null(),
            len: 0,
        }
    }

    fn as_bytes(&self) -> &[u8] {
        if self.len == 0 {
            &[]
        } else {
            unsafe { core::slice::from_raw_parts(self.ptr, self.len) }
        }
    }

    fn as_str(&self) -> &str {
        unsafe { core::str::from_utf8_unchecked(self.as_bytes()) }
    }
}

impl AsRef<str> for InlinePlanString {
    fn as_ref(&self) -> &str {
        self.as_str()
    }
}

