struct InlineDriverLaunchPlan {
    specs: alloc::vec::Vec<InlineDriverLaunchSpec>,
    devnodes: alloc::vec::Vec<InlineDriverDevnodeSpec>,
    ids: alloc::vec::Vec<InlinePlanString>,
    string_bytes: alloc::vec::Vec<u8>,
}

impl InlineDriverLaunchPlan {
    fn new() -> Self {
        Self {
            specs: alloc::vec::Vec::new(),
            devnodes: alloc::vec::Vec::new(),
            ids: alloc::vec::Vec::new(),
            string_bytes: alloc::vec::Vec::new(),
        }
    }

    fn clear(&mut self) {
        self.specs.clear();
        self.devnodes.clear();
        self.ids.clear();
        self.string_bytes.clear();
    }

    fn reserve_shape(&mut self, shape: InlineDriverLaunchPlanShape) -> bool {
        if self.specs.capacity() < shape.specs {
            if self
                .specs
                .try_reserve_exact(shape.specs - self.specs.capacity())
                .is_err()
            {
                return false;
            }
        }
        if self.devnodes.capacity() < shape.devnodes {
            if self
                .devnodes
                .try_reserve_exact(shape.devnodes - self.devnodes.capacity())
                .is_err()
            {
                return false;
            }
        }
        if self.ids.capacity() < shape.ids {
            if self
                .ids
                .try_reserve_exact(shape.ids - self.ids.capacity())
                .is_err()
            {
                return false;
            }
        }
        if self.string_bytes.capacity() < shape.string_bytes {
            if self
                .string_bytes
                .try_reserve_exact(shape.string_bytes - self.string_bytes.capacity())
                .is_err()
            {
                return false;
            }
        }
        true
    }

    fn push(&mut self, spec: InlineDriverLaunchSpec) -> bool {
        if self.specs.len() >= self.specs.capacity() {
            return false;
        }
        self.specs.push(spec);
        true
    }

    fn push_devnode(&mut self, devnode: InlineDriverDevnodeSpec) -> bool {
        if self.devnodes.len() >= self.devnodes.capacity() {
            return false;
        }
        self.devnodes.push(devnode);
        true
    }

    fn push_id(&mut self, id: InlinePlanString) -> bool {
        if self.ids.len() >= self.ids.capacity() {
            return false;
        }
        self.ids.push(id);
        true
    }

    fn push_string(&mut self, value: &str) -> Option<InlinePlanString> {
        self.push_string_bytes(value.as_bytes())
    }

    fn push_string_bytes(&mut self, value: &[u8]) -> Option<InlinePlanString> {
        core::str::from_utf8(value).ok()?;
        if value.is_empty() {
            return Some(InlinePlanString::empty());
        }
        let start = self.string_bytes.len();
        let end = start.checked_add(value.len())?;
        if end > self.string_bytes.capacity() {
            return None;
        }
        self.string_bytes.extend_from_slice(value);
        Some(InlinePlanString {
            ptr: unsafe { self.string_bytes.as_ptr().add(start) },
            len: value.len(),
        })
    }

    fn devnode_len(&self) -> usize {
        self.devnodes.len()
    }

    fn id_len(&self) -> usize {
        self.ids.len()
    }

    fn devnodes_for(&self, spec: &InlineDriverLaunchSpec) -> &[InlineDriverDevnodeSpec] {
        let Some(end) = spec.devnode_start.checked_add(spec.devnode_count) else {
            return &[];
        };
        self.devnodes.get(spec.devnode_start..end).unwrap_or(&[])
    }

    fn ids_for(&self, start: usize, count: usize) -> &[InlinePlanString] {
        let Some(end) = start.checked_add(count) else {
            return &[];
        };
        self.ids.get(start..end).unwrap_or(&[])
    }

    fn hardware_ids_for(&self, devnode: &InlineDriverDevnodeSpec) -> &[InlinePlanString] {
        self.ids_for(devnode.hardware_id_start, devnode.hardware_id_count)
    }

    fn compatible_ids_for(&self, devnode: &InlineDriverDevnodeSpec) -> &[InlinePlanString] {
        self.ids_for(devnode.compatible_id_start, devnode.compatible_id_count)
    }

    fn as_slice(&self) -> &[InlineDriverLaunchSpec] {
        self.specs.as_slice()
    }
}

fn try_owned_inline_string(value: &str) -> Option<alloc::string::String> {
    let mut owned = alloc::string::String::new();
    owned.try_reserve_exact(value.len()).ok()?;
    owned.push_str(value);
    Some(owned)
}

fn owned_driver_launch_spec_from_inline(
    spec: &InlineDriverLaunchSpec,
    plan: &InlineDriverLaunchPlan,
) -> Option<DriverServiceLaunchSpec> {
    let inline_devnodes = plan.devnodes_for(spec);
    let mut devnodes = alloc::vec::Vec::new();
    devnodes.try_reserve_exact(inline_devnodes.len()).ok()?;
    for devnode in inline_devnodes {
        let copy_ids = |ids: &[InlinePlanString]| {
            let mut copied = alloc::vec::Vec::new();
            copied.try_reserve_exact(ids.len()).ok()?;
            for id in ids {
                copied.push(try_owned_inline_string(id.as_str())?);
            }
            Some(copied)
        };
        devnodes.push(DriverServiceDevnodeSpec {
            instance_id: try_owned_inline_string(devnode.instance_id.as_str())?,
            pdo_name: if devnode.pdo_name_present {
                Some(try_owned_inline_string(devnode.pdo_name.as_str())?)
            } else {
                None
            },
            driver_key: if devnode.driver_key_present {
                Some(try_owned_inline_string(devnode.driver_key.as_str())?)
            } else {
                None
            },
            linkage_export: if devnode.linkage_export_present {
                Some(try_owned_inline_string(devnode.linkage_export.as_str())?)
            } else {
                None
            },
            hardware_ids: copy_ids(plan.hardware_ids_for(devnode))?,
            compatible_ids: copy_ids(plan.compatible_ids_for(devnode))?,
        });
    }
    let mut image_path = alloc::vec::Vec::new();
    image_path.try_reserve_exact(spec.image_path.len).ok()?;
    image_path.extend_from_slice(spec.image_path.as_bytes());
    Some(DriverServiceLaunchSpec {
        service_name: try_owned_inline_string(spec.service_name.as_str())?,
        class_guid: if spec.class_guid_present {
            Some(try_owned_inline_string(spec.class_guid.as_str())?)
        } else {
            None
        },
        driver_object_path: try_owned_inline_string(spec.driver_object_path.as_str())?,
        image_path,
        class: spec.class,
        devnodes,
    })
}

#[derive(Clone, Copy, Default)]
struct InlineDriverLaunchPlanShape {
    specs: usize,
    devnodes: usize,
    ids: usize,
    string_bytes: usize,
}

impl InlineDriverLaunchPlanShape {
    fn add_spec(&mut self, devnodes: usize, ids: usize, string_bytes: usize) -> bool {
        let Some(specs) = self.specs.checked_add(1) else {
            return false;
        };
        let Some(total_devnodes) = self.devnodes.checked_add(devnodes) else {
            return false;
        };
        let Some(total_ids) = self.ids.checked_add(ids) else {
            return false;
        };
        let Some(total_string_bytes) = self.string_bytes.checked_add(string_bytes) else {
            return false;
        };
        self.specs = specs;
        self.devnodes = total_devnodes;
        self.ids = total_ids;
        self.string_bytes = total_string_bytes;
        true
    }
}

