pub(crate) unsafe fn live_config_driver_service_launch_spec(
    service_name: &str,
    max_start: u32,
) -> Result<DriverServiceLaunchSpec, i32> {
    let binding = config_manager_query_driver_service(service_name)?;
    owned_driver_launch_spec_from_live_config_binding(binding, max_start)
        .ok_or(0xC000_0034u32 as i32)
}

fn registry_ascii_hex_digit(b: u8) -> bool {
    b.is_ascii_digit() || (b'a'..=b'f').contains(&b)
}

fn registry_layout_id_from_value(data: &[u8], out: &mut [u8]) -> Option<usize> {
    let mut tmp = [0u8; 16];
    let n = registry_utf16_ascii(data, &mut tmp)?;
    let src = &tmp[..n];
    if !src.iter().copied().all(registry_ascii_hex_digit) {
        return None;
    }
    match n {
        8 => {
            if out.len() < 8 {
                return None;
            }
            out[..8].copy_from_slice(src);
            Some(8)
        }
        4 => {
            if out.len() < 8 {
                return None;
            }
            out[..4].copy_from_slice(b"0000");
            out[4..8].copy_from_slice(src);
            Some(8)
        }
        _ => None,
    }
}

fn default_hive_keyboard_layout_id(out: &mut [u8]) -> Option<usize> {
    // DEFHIVEBUF is a fixed executive-lifetime mapping, and `default_hive_bytes` bounds the slice by
    // the storage-host reported hive size before exposing it.
    let hive = unsafe { writable_fs::default_hive_bytes() }.and_then(RegfHive::new)?;
    let key = hive.open_key("Keyboard Layout\\Preload")?;
    let value = hive.value(key, "1")?;
    registry_layout_id_from_value(&value.1, out)
}

fn live_system_hive_key(path: &str) -> Option<nt_config_client::HiveKeySnapshot> {
    unsafe { config_manager_query_system_hive_key(path).ok() }
}

fn live_system_hive_value<'a>(
    key: &'a nt_config_client::HiveKeySnapshot,
    name: &str,
) -> Option<&'a nt_config_client::HiveValueSnapshot> {
    key.values
        .iter()
        .find(|value| value.name.eq_ignore_ascii_case(name))
}

fn system_hive_nls_keyboard_layout_id(out: &mut [u8]) -> Option<usize> {
    let key =
        live_system_hive_key(r"\Registry\Machine\System\CurrentControlSet\Control\Nls\Language")?;
    let value = live_system_hive_value(&key, "Default")?;
    registry_layout_id_from_value(&value.data, out)
}

fn registry_keyboard_layout_id(out: &mut [u8]) -> Option<(usize, &'static [u8])> {
    if let Some(n) = default_hive_keyboard_layout_id(out) {
        return Some((n, b"default-preload"));
    }
    system_hive_nls_keyboard_layout_id(out).map(|n| (n, b"system-nls-default".as_slice()))
}

fn registry_driver_leaf_is_safe(leaf: &[u8]) -> bool {
    !leaf.is_empty()
        && leaf.iter().copied().all(|b| {
            b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'_' || b == b'-' || b == b'.'
        })
        && !leaf.windows(2).any(|w| w == b"..")
}

fn system_hive_keyboard_layout_file(layout_id: &[u8], out: &mut [u8]) -> Option<usize> {
    if layout_id.len() != 8 || !layout_id.iter().copied().all(registry_ascii_hex_digit) {
        return None;
    }
    let mut key_path = alloc::string::String::from(
        r"\Registry\Machine\System\CurrentControlSet\Control\Keyboard Layouts\",
    );
    for &b in layout_id {
        key_path.push(b as char);
    }
    let key = live_system_hive_key(&key_path)?;
    let value = live_system_hive_value(&key, "Layout File")?;
    let n = registry_utf16_ascii(&value.data, out)?;
    if !registry_driver_leaf_is_safe(&out[..n]) {
        return None;
    }
    Some(n)
}

struct SystemHiveDisplayDriverSpec {
    service_name: Vec<u8>,
    display_driver_leaf: Vec<u8>,
    device_description: Vec<u8>,
}

impl SystemHiveDisplayDriverSpec {
    fn win32k_spec(&self) -> win32k_subsystem::DisplayRegistrySpec<'_> {
        win32k_subsystem::DisplayRegistrySpec {
            display_driver_leaf: &self.display_driver_leaf,
            device_description: &self.device_description,
            framebuffer_size: FB_SIZE_BYTES.load(Ordering::Relaxed),
            mode: win32k_subsystem::DisplayModeSpec {
                width: FB_WIDTH.load(Ordering::Relaxed) as u32,
                height: FB_HEIGHT.load(Ordering::Relaxed) as u32,
                stride: FB_SCANLINE.load(Ordering::Relaxed) as u32,
            },
        }
    }

    fn service_name(&self) -> &[u8] {
        &self.service_name
    }
}

static mut SYSTEM_HIVE_DISPLAY_DRIVER_SPEC: Option<SystemHiveDisplayDriverSpec> = None;
static SYSTEM_HIVE_DISPLAY_DRIVER_SPEC_READY: AtomicU64 = AtomicU64::new(0);

fn registry_ascii_lower_vec(s: &str) -> Option<Vec<u8>> {
    if s.is_empty() {
        return None;
    }
    let mut out = Vec::new();
    out.try_reserve_exact(s.len()).ok()?;
    for b in s.bytes() {
        if !(b.is_ascii_alphanumeric() || b == b'_' || b == b'-') {
            return None;
        }
        out.push(b.to_ascii_lowercase());
    }
    Some(out)
}

fn registry_utf16_ascii_vec(data: &[u8]) -> Option<Vec<u8>> {
    if data.len() < 2 {
        return None;
    }
    let mut out = Vec::new();
    out.try_reserve_exact(data.len() / 2).ok()?;
    let mut i = 0usize;
    while i + 1 < data.len() {
        let unit = u16::from_le_bytes([data[i], data[i + 1]]);
        if unit == 0 {
            break;
        }
        if unit > 0x7f {
            return None;
        }
        let mut b = unit as u8;
        if b == b'/' {
            b = b'\\';
        }
        out.push(b.to_ascii_lowercase());
        i += 2;
    }
    if out.is_empty() {
        return None;
    }
    Some(out)
}

fn registry_build_display_service_paths(service_name: &[u8]) -> Option<(Vec<u8>, Vec<u8>)> {
    let key_prefix = b"SYSTEM\\CURRENTCONTROLSET\\SERVICES\\";
    let key_suffix = b"\\DEVICE0";
    let path_prefix = b"\\Registry\\Machine\\System\\CurrentControlSet\\Services\\";
    let path_suffix = b"\\Device0";
    let key_len = key_prefix
        .len()
        .checked_add(service_name.len())?
        .checked_add(key_suffix.len())?;
    let path_len = path_prefix
        .len()
        .checked_add(service_name.len())?
        .checked_add(path_suffix.len())?;
    let mut key = Vec::new();
    key.try_reserve_exact(key_len).ok()?;
    key.extend_from_slice(key_prefix);
    key.extend_from_slice(service_name);
    key.extend_from_slice(key_suffix);
    let mut path = Vec::new();
    path.try_reserve_exact(path_len).ok()?;
    path.extend_from_slice(path_prefix);
    path.extend_from_slice(service_name);
    path.extend_from_slice(path_suffix);
    Some((key, path))
}

fn registry_display_driver_leaf(installed_driver: &[u8]) -> Option<Vec<u8>> {
    if installed_driver.is_empty() {
        return None;
    }
    if !registry_driver_leaf_is_safe(installed_driver) {
        return None;
    }
    let suffix_len = if installed_driver.contains(&b'.') {
        0
    } else {
        4
    };
    let mut out = Vec::new();
    out.try_reserve_exact(installed_driver.len().checked_add(suffix_len)?)
        .ok()?;
    out.extend_from_slice(installed_driver);
    if !installed_driver.contains(&b'.') {
        out.extend_from_slice(b".dll");
    }
    if !registry_driver_leaf_is_safe(&out) {
        return None;
    }
    Some(out)
}

fn system_hive_display_driver_spec() -> Option<&'static SystemHiveDisplayDriverSpec> {
    if SYSTEM_HIVE_DISPLAY_DRIVER_SPEC_READY.load(Ordering::Relaxed) != 0 {
        return unsafe { (&*core::ptr::addr_of!(SYSTEM_HIVE_DISPLAY_DRIVER_SPEC)).as_ref() };
    }
    let services_path = nt_config_manager::SERVICES_PATH;
    let services = live_system_hive_key(services_path)?;
    for service in &services.subkeys {
        let mut device_path = alloc::string::String::from(services_path);
        device_path.push('\\');
        device_path.push_str(&service.name);
        device_path.push_str("\\Device0");
        let Some(device_key) = live_system_hive_key(&device_path) else {
            continue;
        };
        let Some(installed_value) = live_system_hive_value(&device_key, "InstalledDisplayDrivers")
        else {
            continue;
        };
        let Some(description_value) = live_system_hive_value(&device_key, "Device Description")
        else {
            continue;
        };
        let Some(_vga_compatible) = live_system_hive_value(&device_key, "VgaCompatible")
            .and_then(|value| registry_dword_from_bytes(&value.data))
        else {
            continue;
        };

        let Some(service_name) = registry_ascii_lower_vec(&service.name) else {
            continue;
        };
        let Some(installed_display_driver) = registry_utf16_ascii_vec(&installed_value.data) else {
            continue;
        };
        let Some(display_driver_leaf) = registry_display_driver_leaf(&installed_display_driver)
        else {
            continue;
        };
        if unsafe { !crate::fs_loader::sys32_exists(&display_driver_leaf) } {
            continue;
        }
        let Some(device_description) = registry_utf16_ascii_vec(&description_value.data) else {
            continue;
        };
        if registry_build_display_service_paths(&service_name).is_none() {
            continue;
        }

        let spec = SystemHiveDisplayDriverSpec {
            service_name,
            display_driver_leaf,
            device_description,
        };
        unsafe {
            *core::ptr::addr_of_mut!(SYSTEM_HIVE_DISPLAY_DRIVER_SPEC) = Some(spec);
        }
        SYSTEM_HIVE_DISPLAY_DRIVER_SPEC_READY.store(1, Ordering::Relaxed);
        return unsafe { (&*core::ptr::addr_of!(SYSTEM_HIVE_DISPLAY_DRIVER_SPEC)).as_ref() };
    }
    None
}

