/// If a `KeyRef` names an overlay (created) key, return its overlay index.
fn mutable_key_idx(kr: KeyRef) -> Option<usize> {
    if kr >= MUTABLE_KEY_TAG && kr < MUTABLE_KEY_TAG + MUTABLE_KEY_MAX {
        Some((kr - MUTABLE_KEY_TAG) as usize)
    } else {
        None
    }
}

/// If a `KeyRef` names an overlay (created) key, return its overlay index.
fn overlay_key_idx(kr: KeyRef) -> Option<usize> {
    if kr >= OVERLAY_KEY_TAG && kr < OVERLAY_KEY_TAG + OVERLAY_KEY_MAX {
        Some((kr - OVERLAY_KEY_TAG) as usize)
    } else {
        None
    }
}

pub(crate) fn explorer_shell_com_class_bit_for_path(path: &str) -> u64 {
    let lc = path.to_ascii_lowercase();
    if lc.contains(
        r"\registry\machine\software\classes\clsid\{4622ad11-ff23-11d0-8d34-00a0c90f2719}",
    ) {
        nt_hive_core::REACTOS_EXPLORER_SHELL_COM_CLASS_MASK_START_MENU
    } else if lc.contains(
        r"\registry\machine\software\classes\clsid\{ecd4fc4d-521c-11d0-b792-00a0c90312e1}",
    ) {
        nt_hive_core::REACTOS_EXPLORER_SHELL_COM_CLASS_MASK_REBAR_BAND_SITE
    } else {
        0
    }
}

pub(crate) fn explorer_shell_com_inproc_class_bit_for_path(path: &str) -> u64 {
    let bit = explorer_shell_com_class_bit_for_path(path);
    if bit == 0 || !path.to_ascii_lowercase().ends_with(r"\inprocserver32") {
        0
    } else {
        bit
    }
}
/// NtCreateKey SSN (ReactOS ntdll — `sysfuncs.lst` line 44). services' SCM creates volatile keys
/// (e.g. `Control\ServiceCurrent`) here; the write plane is the [`RegistryOverlay`].
pub const SSN_NT_CREATE_KEY: u64 = 43;
/// Registry key create dispositions (NtCreateKey *Disposition out-param).
const REG_CREATED_NEW_KEY: u32 = 1;
const REG_OPENED_EXISTING_KEY: u32 = 2;

/// True if `path` is exactly the SYSTEM hive `...\Control\Keyboard Layouts\<klid>` subkey (the
/// plural "Keyboard Layouts" under `Control`, distinct from the singular HKCU
/// `Keyboard Layout\Preload`/`Substitutes`). Matched case-insensitively for proof accounting after
/// the normal registry resolver has opened a real mounted-hive key.
fn is_keyboard_layout_key(path: &str) -> bool {
    let comps: alloc::vec::Vec<&str> = path.split('\\').filter(|c| !c.is_empty()).collect();
    let tail: &[&str] = if comps.len() >= 2
        && comps[0].eq_ignore_ascii_case("Registry")
        && comps[1].eq_ignore_ascii_case("Machine")
    {
        &comps[2..]
    } else {
        &comps[..]
    };
    tail.len() == 5
        && tail[0].eq_ignore_ascii_case("System")
        && is_numbered_control_set_component(tail[1])
        && tail[2].eq_ignore_ascii_case("Control")
        && tail[3].eq_ignore_ascii_case("Keyboard Layouts")
        && tail[4].len() == 8
        && tail[4]
            .bytes()
            .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b.to_ascii_lowercase()))
}

fn is_numbered_control_set_component(component: &str) -> bool {
    let bytes = component.as_bytes();
    bytes.len() == b"ControlSet000".len()
        && bytes[..b"ControlSet".len()].eq_ignore_ascii_case(b"ControlSet")
        && bytes[b"ControlSet".len()..].iter().all(u8::is_ascii_digit)
}
/// True if `comps` (backslash-split, no `\Registry\Machine` prefix) name the Winlogon key
/// `Software\Microsoft\Windows NT\CurrentVersion\Winlogon`. Matched EXACTLY (5 components, in order)
/// so no other Software subkey is spuriously satisfied.
pub(crate) fn is_winlogon_key_comps(comps: &[&str]) -> bool {
    comps.len() == 5
        && comps[0].eq_ignore_ascii_case("Software")
        && comps[1].eq_ignore_ascii_case("Microsoft")
        && comps[2].eq_ignore_ascii_case("Windows NT")
        && comps[3].eq_ignore_ascii_case("CurrentVersion")
        && comps[4].eq_ignore_ascii_case("Winlogon")
}
/// True if `path` (a backslash-delimited key path, with or without a leading `\` and with or without
/// a `\Registry\Machine\` prefix) is the Winlogon key. Tolerates both the absolute
/// `\Registry\Machine\Software\...\Winlogon` and the HKLM-relative `Software\...\Winlogon` forms.
pub(crate) fn is_winlogon_key(path: &str) -> bool {
    let comps: alloc::vec::Vec<&str> = path.split('\\').filter(|c| !c.is_empty()).collect();
    if is_winlogon_key_comps(&comps) {
        return true;
    }
    // Absolute form: strip a leading Registry\Machine.
    comps.len() == 7
        && comps[0].eq_ignore_ascii_case("Registry")
        && comps[1].eq_ignore_ascii_case("Machine")
        && is_winlogon_key_comps(&comps[2..])
}
/// True if `path` names `Software\Microsoft\Windows NT\CurrentVersion\ProfileList` (HKLM-relative or
/// with the absolute `\Registry\Machine\` prefix). Matched EXACTLY, in order, like the Winlogon key.
///
/// ★ THE POST-LOGON WITNESS. `userenv!GetProfilesDirectoryW` (`profile.c:1592`) is the FIRST thing
/// `LoadUserProfileW` does, `LoadUserProfileW` is called from exactly one place in winlogon —
/// `HandleLogon` (`sas.c:626`) — and `HandleLogon` runs under exactly one switch arm,
/// `case WLX_SAS_ACTION_LOGON` (`sas.c:1214`, and only from `STATE_LOGGED_OFF_SAS`). So winlogon
/// opening this key IS the structural proof that `WlxLoggedOutSAS` returned `WLX_SAS_ACTION_LOGON`
/// for the real logon. Recognised for COUNTING ONLY — the open still misses honestly (the SOFTWARE
/// hive is not mounted on this host), which is why `LoadUserProfileW` fails and the shell is not
/// started. Nothing about the outcome is changed.
pub(crate) fn is_profile_list_key(path: &str) -> bool {
    fn comps_match(comps: &[&str]) -> bool {
        comps.len() == 5
            && comps[0].eq_ignore_ascii_case("Software")
            && comps[1].eq_ignore_ascii_case("Microsoft")
            && comps[2].eq_ignore_ascii_case("Windows NT")
            && comps[3].eq_ignore_ascii_case("CurrentVersion")
            && comps[4].eq_ignore_ascii_case("ProfileList")
    }
    let comps: alloc::vec::Vec<&str> = path.split('\\').filter(|c| !c.is_empty()).collect();
    comps_match(&comps)
        || (comps.len() == 7
            && comps[0].eq_ignore_ascii_case("Registry")
            && comps[1].eq_ignore_ascii_case("Machine")
            && comps_match(&comps[2..]))
}
