/// Base for object-manager handles (index into `obj_ns`, distinct from key handles).
const OBJ_HANDLE_BASE: u64 = 0x0000_0002_0000_0000;
/// Opaque-tag payload used by the real per-process handle table for anonymous events. The low
/// 32 bits are the shared object-namespace index; named/global event handles keep OBJ_HANDLE_BASE
/// for win32k and cross-process compatibility.
const EVENT_HANDLE_TAG: u64 = 0x4556_4E54_0000_0000;
const EVENT_HANDLE_TAG_MASK: u64 = 0xFFFF_FFFF_0000_0000;
const TIMER_HANDLE_TAG: u64 = 0x5449_4D52_0000_0000;
const TIMER_HANDLE_TAG_MASK: u64 = 0xFFFF_FFFF_0000_0000;
const SEMAPHORE_HANDLE_TAG: u64 = 0x5345_4D41_0000_0000;
const SEMAPHORE_HANDLE_TAG_MASK: u64 = 0xFFFF_FFFF_0000_0000;
const MUTANT_HANDLE_TAG: u64 = 0x4D55_544E_0000_0000;
const MUTANT_HANDLE_TAG_MASK: u64 = 0xFFFF_FFFF_0000_0000;
const DIRECTORY_OBJECT_HANDLE_TAG: u64 = 0x4449_524F_0000_0000;
const SYMBOLIC_LINK_HANDLE_TAG: u64 = 0x5359_4D4C_0000_0000;
const KEYEDEVENT_HANDLE_TAG: u64 = 0x4B45_5956_0000_0000;
const OBJECT_NAMESPACE_HANDLE_TAG_MASK: u64 = 0xFFFF_FFFF_0000_0000;
const DIRECTORY_QUERY_ACCESS: u32 = 0x0001;
const DIRECTORY_TRAVERSE_ACCESS: u32 = 0x0002;
const DIRECTORY_CREATE_OBJECT_ACCESS: u32 = 0x0004;
const DIRECTORY_CREATE_SUBDIRECTORY_ACCESS: u32 = 0x0008;
const SYMBOLIC_LINK_QUERY_ACCESS: u32 = 0x0001;
const OBJ_PERMANENT: u32 = 0x0000_0010;
const EVENT_QUERY_STATE: u32 = 0x0001;
const EVENT_MODIFY_STATE: u32 = 0x0002;
const TIMER_MODIFY_STATE: u32 = 0x0002;
const SEMAPHORE_QUERY_STATE: u32 = 0x0001;
const SEMAPHORE_MODIFY_STATE: u32 = 0x0002;
const SYNCHRONIZE_ACCESS: u32 = 0x0010_0000;
const DELETE_ACCESS: u32 = 0x0001_0000;

const OBJ_KIND_DIRECTORY: u8 = 0;
const OBJ_KIND_SYMBOLIC_LINK: u8 = 1;
const OBJ_KIND_EVENT: u8 = 2;
const OBJ_KIND_SEMAPHORE: u8 = 3;
const OBJ_KIND_MUTANT: u8 = 4;
const OBJ_KIND_LPC_PORT: u8 = 5;
const OBJ_KIND_TIMER: u8 = 6;
const OBJ_KIND_IO_COMPLETION: u8 = 7;
const OBJ_KIND_DELETED: u8 = 0xff;
const OBJ_NAME_CAP: usize = 128;
const OBJ_PARENT_ROOT: usize = usize::MAX;
const OBJ_PARENT_ANONYMOUS: usize = usize::MAX - 1;
static OBJ_NS_GROWTHS: AtomicU64 = AtomicU64::new(0);

fn mark_object_namespace_growth(old_capacity: usize, new_capacity: usize, len: usize) {
    let n = OBJ_NS_GROWTHS.fetch_add(1, Ordering::Relaxed);
    if n < 8 {
        print_str(b"[obj-ns] grew capacity ");
        print_u64(old_capacity as u64);
        print_str(b" -> ");
        print_u64(new_capacity as u64);
        print_str(b" len=");
        print_u64(len as u64);
        print_str(b"\n");
    }
}

/// One node in the executive's minimal object-manager namespace. Inline, `Copy`, no nested heap
/// allocation. Its backing `Vec` remains live through ordinary ownership and may grow beyond the
/// boot reserve. NT object leaf names are allowed to be long enough for BaseNamedObjects mutexes
/// such as userenv's per-profile mutex; `target` is link-only data; `payload` carries backing object
/// identity for kinds whose state lives outside the namespace, such as LPC listen port handles and
/// I/O completion ports. `permanent` mirrors `OBJ_PERMANENT`; non-permanent named objects are
/// unlinked when their final body reference goes away.
#[derive(Clone, Copy)]
struct ObjEntry {
    name: [u8; OBJ_NAME_CAP], // leaf name, lowercased ASCII (len in name_len)
    name_len: u8,
    parent: usize, // index of the parent directory; OBJ_PARENT_ROOT = the root itself
    kind: u8,
    permanent: bool,
    /// References held by published native wait records after the caller's handle capture.
    wait_references: u32,
    target: [u8; OBJ_NAME_CAP], // symbolic-link target (kind == 1)
    target_len: u8,
    payload: u64,
}
impl ObjEntry {
    fn push_zeroed(entries: &mut alloc::vec::Vec<Self>) -> Option<usize> {
        if entries.len() == entries.capacity() {
            let old_capacity = entries.capacity();
            entries.try_reserve(64).ok()?;
            let new_capacity = entries.capacity();
            if new_capacity > old_capacity {
                mark_object_namespace_growth(old_capacity, new_capacity, entries.len());
            }
        }
        let index = entries.len();
        entries.push(Self {
            name: [0; OBJ_NAME_CAP],
            name_len: 0,
            parent: 0,
            kind: OBJ_KIND_DELETED,
            permanent: false,
            wait_references: 0,
            target: [0; OBJ_NAME_CAP],
            target_len: 0,
            payload: 0,
        });
        Some(index)
    }

    fn push_kind(
        entries: &mut alloc::vec::Vec<Self>,
        name: &[u8],
        parent: usize,
        kind: u8,
        target: &[u8],
        permanent: bool,
    ) -> Option<usize> {
        let index = Self::push_zeroed(entries)?;
        let entry = &mut entries[index];
        entry.parent = parent;
        entry.kind = kind;
        entry.permanent = permanent;
        let n = name.len().min(OBJ_NAME_CAP);
        entry.name[..n].copy_from_slice(&name[..n]);
        entry.name_len = n as u8;
        if kind == OBJ_KIND_SYMBOLIC_LINK {
            let n = target.len().min(OBJ_NAME_CAP);
            entry.target[..n].copy_from_slice(&target[..n]);
            entry.target_len = n as u8;
        }
        Some(index)
    }

    fn push_dir(
        entries: &mut alloc::vec::Vec<Self>,
        name: &[u8],
        parent: usize,
        permanent: bool,
    ) -> Option<usize> {
        Self::push_kind(entries, name, parent, OBJ_KIND_DIRECTORY, &[], permanent)
    }

    fn push_symlink(
        entries: &mut alloc::vec::Vec<Self>,
        name: &[u8],
        parent: usize,
        target: &[u8],
        permanent: bool,
    ) -> Option<usize> {
        Self::push_kind(
            entries,
            name,
            parent,
            OBJ_KIND_SYMBOLIC_LINK,
            target,
            permanent,
        )
    }

    fn is_live(&self) -> bool {
        self.kind != OBJ_KIND_DELETED
    }
    fn name(&self) -> &[u8] {
        &self.name[..self.name_len as usize]
    }
    fn target(&self) -> &[u8] {
        &self.target[..self.target_len as usize]
    }

    fn unlink(&mut self) {
        self.name = [0; OBJ_NAME_CAP];
        self.name_len = 0;
        self.parent = OBJ_PARENT_ANONYMOUS;
        self.kind = OBJ_KIND_DELETED;
        self.permanent = false;
        self.wait_references = 0;
        self.target = [0; OBJ_NAME_CAP];
        self.target_len = 0;
        self.payload = 0;
    }
}

/// Raw references to the fault/syscall loop's per-iteration state, handed to the group-C handlers
/// (Workstream A) so they can reach the section/registry/demand-fill state that genuinely lives on
/// the loop (`service_sec_image`), not on the handler. The Tier-1 dispatch arm rebuilds this each
/// iteration pointing at the current loop locals.
///
/// SAFETY: every pointer targets a `service_sec_image` local that outlives each `dispatch` call;
/// the executive is single-threaded and the loop does not touch these between building the ctx and
/// draining the handler's signals, so there is no aliasing in practice. Extended as more group-C
/// cases migrate (reg / dll_pes / csrss handle-tracking / image PEs / demand-fill state).
#[derive(Clone, Copy)]
struct ExecLoopCtx {
    /// The faulting process's PML4 (page_map target for COMMIT frames / demand-filled pages).
    pml4: u64,
    /// Every hosted process's trusted mechanism state. Cross-process VM services select the target
    /// PML4/scratch through the access-checked target pid rather than the caller's active context.
    procs: *mut [ProcExec],
    pfilled: *mut [[u64; 512]],
    /// The named NLS section handle (\Nls\NlsSectionCP20127) NtOpenSection records so
    /// NtMapViewOfSection can back it. Points at the loop-local `nls_section_handle`.
    nls_section_handle: *mut u64,
    /// The DLL registry (csrsrv/basesrv/winsrv + the Win32 client stack): name→index resolution,
    /// per-DLL file/section-handle tracking, and image-info synthesis for the file/section fakes.
    reg: *mut nt_dll_registry::Registry,
    /// Loop-owned parsed hosted EXE PEs and backing pool addresses, keyed by the runtime hosted
    /// image catalog. NtOpenFile can extend this table with later executable images loaded from the
    /// real volume; syscall handlers consume it for metadata and demand-fill lookups instead of
    /// naming bootstrap image locals directly.
    hosted_loaded_images: *mut HostedLoadedImageTable,
    /// Generic owner-local executable handle/state table for Win32 child processes. The PE bytes
    /// remain loop-owned; this table validates open -> section -> spawn -> publish transitions.
    exe_images: *mut nt_exe_image::ImageTable<HOSTED_PROCESS_IMAGE_CAP>,
    /// Runtime-owned identity catalog for hosted executable images admitted through file/section
    /// creation. `NtCreateProcess` consumes this as the target authority instead of re-resolving
    /// static leaf metadata at spawn time.
    exe_image_catalog: *mut nt_exe_image::OwnedHostedImageCatalog<HOSTED_PROCESS_IMAGE_CAP>,
    /// The active process's demand-fill bookkeeping (page VA per fault index) + fault count — the
    /// same locals `csrss_out_write` mutates. NtQueryDefaultLocale demand-fills an image .data page.
    filled_pages: *mut [u64; 512],
    faults: *mut u64,
    /// The faulting image's persistent executive scratch base (smss's), and the two images
    /// NtQueryDefaultLocale may demand-fill from (the main image `pe` at PE_LOAD_BASE up to
    /// `img_end`, and `ntdll_pe` in [`nt_base`,`nt_end`); `ntdll_pe` is null if absent).
    scratch_base: u64,
    pe: *const nt_pe_loader::PeFile<'static>,
    ntdll_pe: *const nt_pe_loader::PeFile<'static>,
    img_end: u64,
    nt_base: u64,
    nt_end: u64,
    /// The mutable backing store for loadable DLL PEs (csrsrv/basesrv/winsrv + the Win32 client
    /// stack). The demand-load path writes freshly parsed PEs here, and `dll_pes()` derives a live
    /// slice from the current vector so runtime slot growth cannot leave a stale reference table.
    dll_pe_store: *mut DllPeStore,
    /// Generic data/pagefile section objects and mapped views. This is the real section-object path
    /// for non-SEC_IMAGE mappings: NtCreateSection records backing, NtMapViewOfSection reserves a
    /// VAD, and the fault router materialises pages on demand.
    generic_sections: *mut GenericSectionTable,
    /// Per-hosted-process DLL arena paging state. Each hosted VSpace needs its own PD covering the
    /// compact DLL range plus PT windows for every mapped DLL.
    dll_arena_paging: *mut DllArenaPagingState,
}

impl ExecLoopCtx {
    unsafe fn dll_pes(&self) -> &'static [Option<nt_pe_loader::PeFile<'static>>] {
        (&*self.dll_pe_store).as_slice()
    }
}

/// A pending cross-VSpace thread creation: everything the LOOP needs to turn the handler's
/// already-completed policy decision into the real seL4 thread inside the TARGET process.
/// See [`rendezvous::spawn_slot_thread`] and `ExecNtHandler::create_remote_thread`.
#[derive(Clone, Copy)]
pub(crate) struct RemoteThreadRequest {
    /// Hosted-process index of the TARGET (the process the new thread belongs to).
    pub target_pi: usize,
    /// The bounded per-process thread window claimed for it.
    pub slot: usize,
    /// The TARGET's published hosted VSpace (PML4) cap.
    pub pml4: u64,
    /// The caller-supplied start context (`rip` = start routine, `rcx` = parameter).
    pub start: nt_thread_start::Amd64ThreadContext,
    /// The new thread's `ClientId` — the TARGET's pid + the ETHREAD's tid.
    pub cid_proc: u64,
    pub cid_thread: u64,
    /// `CreateSuspended = FALSE` ⇒ resume it as soon as it is built.
    pub resume: bool,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum HostedThreadSpawnRequest {
    Winlogon {
        slot: usize,
    },
    ServicesListener,
    LsassListener {
        slot: usize,
    },
    TpWorker {
        pi: usize,
        slot: usize,
    },
    ThreadEx {
        pi: usize,
        slot: usize,
        start: nt_thread_start::Amd64ThreadContext,
    },
}

#[derive(Clone, Copy)]
struct PendingWaitTimeout {
    deadline: nt_delay_execution::Deadline,
}

/// Allocation-safe handoff from native dispatch to the service-loop reply-cap owner after the LPC
/// broker atomically commits a reply and reports that the receive must block.
#[derive(Clone, Copy)]
struct PendingLpcReceivePark {
    reservation: nt_lpc_continuation::Reservation,
    request: nt_lpc_continuation::ReceiveRequest,
    memory: SyscallUserMemory,
}

/// Full kernel continuation retained for one wakeable LPC receive.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct LpcReceiveContinuation {
    pi: u32,
    badge: u64,
    tid: u64,
    memory: SyscallUserMemory,
    reply_cap: u64,
    reply: nt_syscall_abi::ParkedSyscallReply,
}

/// Allocation-safe handoff for a broker connection that has become pending. The table reservation
/// is acquired before the broker mutates connection state; the service loop binds the live reply
/// object only after dispatch returns.
#[derive(Clone, Copy)]
struct PendingLpcConnectPark {
    reservation: nt_lpc_continuation::Reservation,
    request: nt_lpc_continuation::ConnectRequest,
    memory: SyscallUserMemory,
    name: [u16; 32],
    name_len: u8,
}

/// Full kernel continuation retained until the exact broker connection completes or terminates.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct LpcConnectContinuation {
    pi: u32,
    badge: u64,
    tid: u64,
    memory: SyscallUserMemory,
    name: [u16; 32],
    name_len: u8,
    reply_cap: u64,
    reply: nt_syscall_abi::ParkedSyscallReply,
}

/// Terminal broker result transferred from accept/complete dispatch to the reply-cap owner.
struct PendingLpcConnectCompletion {
    connection_id: u64,
    status: u32,
    client_handle: u64,
    connection_information: alloc::vec::Vec<u8>,
}

/// Allocation-safe handoff for a queued synchronous request. The broker has already assigned the
/// message identity; the service loop binds the current reply object before the caller is parked.
#[derive(Clone, Copy)]
struct PendingLpcRequestPark {
    reservation: nt_lpc_continuation::Reservation,
    request: nt_lpc_continuation::RequestWaitRequest,
    memory: SyscallUserMemory,
}

/// Full kernel continuation retained until the exact broker reply arrives or the port terminates.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct LpcRequestContinuation {
    pi: u32,
    badge: u64,
    tid: u64,
    memory: SyscallUserMemory,
    reply_cap: u64,
    reply: nt_syscall_abi::ParkedSyscallReply,
}

impl PendingWaitTimeout {
    const fn none() -> Self {
        Self {
            deadline: nt_delay_execution::Deadline::Infinite,
        }
    }

    fn from_interval(interval_100ns: i64) -> Self {
        let now = nt_time_snapshot();
        Self {
            deadline: nt_delay_execution::Deadline::from_nt_timeout(Some(interval_100ns), now),
        }
    }

    fn is_none(self) -> bool {
        self.deadline == nt_delay_execution::Deadline::Infinite
    }

    fn is_due_now(self) -> Option<bool> {
        if self.is_none() {
            None
        } else {
            Some(self.deadline.is_due(nt_time_snapshot()))
        }
    }

    const fn deadline(self) -> nt_delay_execution::Deadline {
        self.deadline
    }
}

/// Kernel-captured native `PORT_VIEW` and resolved section identity. The user buffer is retained
/// only as an output destination; all input fields come from the captured bytes.
#[derive(Clone, Copy)]
struct CapturedLpcPortView {
    pointer: u64,
    native: [u8; nt_lpc_abi::PORT_VIEW_LEN],
    section_index: usize,
    section_offset: u64,
    view_size: u64,
}

/// Kernel-captured native `REMOTE_PORT_VIEW` output descriptor.
#[derive(Clone, Copy)]
struct CapturedLpcRemoteView {
    pointer: u64,
    native: [u8; nt_lpc_abi::REMOTE_PORT_VIEW_LEN],
}

/// One offered section mapped into its owner and peer processes.
#[derive(Clone, Copy)]
struct MappedLpcPortView {
    owner_pi: usize,
    owner_base: u64,
    peer_pi: usize,
    peer_base: u64,
    view_size: u64,
}

impl MappedLpcPortView {
    fn abi(self) -> nt_lpc_abi::MappedPortView {
        nt_lpc_abi::MappedPortView {
            owner_base: self.owner_base,
            peer_base: self.peer_base,
            view_size: self.view_size,
        }
    }
}

/// Kernel-owned connection-view transaction. A broker connection id, never an image role or a
/// most-recent slot, is the durable identity across connect, accept, and complete.
#[derive(Clone, Copy)]
struct PendingLpcConnectionViews {
    connection_id: u64,
    connector_pi: usize,
    connector_memory: SyscallUserMemory,
    connector_view: Option<CapturedLpcPortView>,
    connector_remote_view: Option<CapturedLpcRemoteView>,
    connector_mapping: Option<MappedLpcPortView>,
    acceptor_mapping: Option<MappedLpcPortView>,
}

struct ExecNtHandler {
    /// The REAL ReactOS SYSTEM hive (root = \Registry\Machine\System), parsed read-only by
    /// borrowing the regf bytes the storage host read off the disk into HIVEBUF (no 204 KiB copy —
    /// the executive heap is small). None if the hive wasn't staged on the disk.
    hive: Option<RegfHive<'static>>,
    /// The REAL ReactOS **SECURITY** hive (root = `\Registry\Machine\SECURITY`) — the LSA policy
    /// database's backing store, read BY PATH off `\reactos\system32\config\security`. The staged
    /// hive is the genuine post-setup one: 8 KiB, root key only, NO `Policy` subkey. That emptiness
    /// is load-bearing — it is exactly what makes lsasrv's `LsapIsDatabaseInstalled()` answer FALSE
    /// and run its real first-boot `LsapCreateDatabaseKeys` + `LsapCreateDatabaseObjects` install
    /// (which mints the account-domain SID). Persistent writes now land in `mutable_hives`; the
    /// borrowed `RegfHive` remains the boot image navigator while D2 retires the old overlay shadow.
    pub(crate) security_hive: Option<RegfHive<'static>>,
    /// The REAL ReactOS **SAM** hive (root = `\Registry\Machine\SAM`), same by-path staging.
    pub(crate) sam_hive: Option<RegfHive<'static>>,
    /// The REAL ReactOS **SOFTWARE** hive (root = `\Registry\Machine\SOFTWARE`) — HKLM\Software's
    /// backing store, read BY PATH off `\reactos\system32\config\software`. 471040 B (~57x the
    /// SECURITY/SAM hives), borrowed from SWHIVEBUF read-only like every other mount. It carries
    /// `Microsoft\Windows NT\CurrentVersion\ProfileList\ProfilesDirectory`, which is what
    /// `userenv!GetProfilesDirectoryW` — the first thing winlogon's `LoadUserProfileW` does — reads.
    pub(crate) software_hive: Option<RegfHive<'static>>,
    /// ★ The `\Registry\User` (`HKEY_USERS`) MOUNT TABLE — every hive that is not one of the four
    /// boot mounts above, in ONE general mechanism: `\Registry\User\.Default` (mounted at
    /// construction from the staged `config\default`, exactly as `CmpInitializeHiveList` does) and
    /// the per-user hives `NtLoadKey` mounts at run time. The vector owns its run-time path and hive
    /// allocations directly.
    pub(crate) hive_mounts: alloc::vec::Vec<HiveMount>,
    /// Owned mutable hive authority mounted at the same NT registry roots as the borrowed `RegfHive`
    /// selectors. Mounted-hive create/open handles use `mutable_key_handles` so later writes can
    /// land in this authority without path shadowing through `RegistryOverlay`.
    mutable_hives: MutableHiveSet,
    /// Process handle targets in the mutable key range. Entries store stable hive/cell identity and
    /// are released when the last process handle to that target closes; dynamic hive unload also
    /// clears entries for that hive so stale handles stop resolving.
    mutable_key_handles: alloc::vec::Vec<Option<ResolvedHiveKey>>,
    /// Mutable-hive journal records appended since the last writable-volume snapshot. The log append
    /// itself is synchronous in the mounted volume; this counter batches the expensive snapshot
    /// reserve commit instead of exporting the whole writable volume after every registry value.
    mutable_hive_journal_pending_records: u32,
    /// Bitmask of boot-mounted hives that have journal records in the pending snapshot batch.
    /// Dynamic profile hives can share the record counter, but boot-hive checkpoint proof must only
    /// account for hives whose `system32\config\*.LOG` sidecar actually changed in this batch.
    mutable_hive_journal_pending_boot_mask: u8,
    /// Bitmask of boot-mounted hives with live dirty cells backed by their journal sidecar. Unlike
    /// `mutable_hive_journal_pending_boot_mask`, this survives snapshot batching until a committed
    /// sidecar snapshot has been observed or a full-image checkpoint clears the hive dirty set.
    mutable_hive_journal_dirty_boot_mask: u8,
    /// Set after the live boot-mounted hives have been refreshed from a restored writable-volume
    /// checkpoint. This is one-shot per boot: later `NtFlushKey` calls update the same files, but CM
    /// must not repeatedly replace live hives while hosted processes are holding key handles.
    boot_hive_checkpoints_refreshed: bool,
    /// Cached indexed view of `HKLM\SYSTEM\CurrentControlSet\Services` in the order ReactOS SCM uses
    /// while building its service database. The mounted hive remains the authority; this is only the
    /// kernel-side enumeration index, invalidated by any mutable hive write and rebuilt on demand.
    registry_services_order_cache: alloc::vec::Vec<alloc::string::String>,
    registry_services_order_cache_valid: bool,
    /// Last successful mutable-hive value copyout to a hosted process. ReactOS `RegCopyTreeW`
    /// enumerates a source value into a process heap buffer, then calls `NtSetValueKey` with a data
    /// pointer into that same buffer. Keeping the source value identity here lets the Configuration
    /// Manager install the destination as a same-hive shared payload when the pointer/length/type
    /// still match and the user buffer validates byte-for-byte.
    registry_value_copy_provenance: RegistryValueCopyProvenanceTable,
    /// Security descriptors for virtual registry namespace roots. `\Registry\Machine` and
    /// `\Registry\User` are CM namespace sentinels, not hive cells and not overlay keys, but
    /// security queries/updates still target their handle identity.
    registry_machine_root_security_descriptor: Option<alloc::vec::Vec<u8>>,
    registry_user_root_security_descriptor: Option<alloc::vec::Vec<u8>>,
    /// Live system timezone state returned by class 44 and used to derive class 3's current bias.
    time_zone_information: nt_kernel_exec::timezone::TimeZoneInformation,
    /// The minimal object-manager namespace (index 0 = root `\`). Entries are inline and the owned
    /// vector grows beyond its boot reserve when required.
    obj_ns: alloc::vec::Vec<ObjEntry>,
    /// Dispatcher state for every `obj_ns` event, keyed by the stable namespace index. The store
    /// owns manual/auto-reset and signal state; `obj_ns` owns names and identity.
    events: nt_kernel_exec::EventStore,
    /// Native waitable timers, keyed by `obj_ns` timer entries. Dispatcher signal state is stored in
    /// `events`; this table holds due-time, period, and optional APC metadata.
    user_timers: nt_user_timer::TimerTable,
    user_timer_rearm_requested: bool,
    /// Set only after the authoritative system clock moved. The service-loop tail consumes this
    /// before replying so KUSER publication and absolute-deadline re-evaluation are inseparable
    /// from a successful clock adjustment.
    system_time_change: Option<nt_time::SystemTimeChange>,
    /// Counting semaphore state keyed by the same stable namespace indices.
    semaphores: nt_kernel_exec::SemaphoreStore,
    /// Mutant state keyed by the same stable namespace indices.
    mutants: nt_kernel_exec::MutantStore,
    /// The session-global atom namespace backing NtAdd/Find/Delete/QueryInformationAtom. Its fixed
    /// arena is allocated once in `new()` and shared across every hosted process (`pi`).
    global_atoms: nt_kernel_exec::rtl_atom::OwnedAtomTable,
    /// Fixed executive completion-port objects and packet queues. The backing table lives in BSS so
    /// `ExecNtHandler::initialize_in` does not materialize it on the early root task stack.
    io_completion_ports: ExecIoCompletionPorts,
    /// Shared FILE_OBJECT completion associations. Backed by BSS for the same bounded-stack reason
    /// as the completion-port table.
    file_completion: ExecFileCompletion,
    /// Shared FILE_OBJECT-style state for FAT directory handles, including enumeration cursors.
    /// The backing table lives in BSS to keep it off the bounded rootserver stack.
    directory_opens: ExecDirectoryOpens,
    /// Shared FILE_OBJECT-style state for read-only FAT file handles, including current byte
    /// offsets used by synchronous implicit-position reads.
    readonly_file_opens: ExecReadOnlyFileOpens,
    /// Filesystem-owned byte ranges for local FAT and MemFs FILE_OBJECTs. Provider-backed Files
    /// keep their lock state in the receiving FSD through `IRP_MJ_LOCK_CONTROL`.
    byte_range_locks: nt_fs::ByteRangeLockTable<u64>,
    next_local_byte_lock_irp: u64,
    /// One-shot directory watches for the read-only FAT owner. Writable MemFs notifications remain
    /// inside its `nt-fs::FileSystem`; provider-backed watches remain inside the receiving FSD.
    readonly_directory_notifications: nt_fs::DirectoryNotifyTable<u64>,
    next_local_directory_notify_irp: u64,
    /// Per-call context the dispatch loop refreshes before each `dispatch` (Workstream A: the
    /// converged table-driven path carries executive context on the handler rather than a parallel
    /// mechanism). `pi` = process index (0 = smss, 1 = csrss); `stop` = a side-signal a handler
    /// sets when it can't service the call, so the loop stops the process (the ladder's
    /// `handled = false; break`).
    pi: usize,
    current_tid: u64,
    current_badge: u64,
    current_resume_ip: u64,
    current_sp: u64,
    current_flags: u64,
    /// Exact native service number for synchronous File retry grants.
    current_service_number: u32,
    /// Whether the current service arrived as our ntdll's native seL4-Call request.
    current_native_call_transport: bool,
    /// Address-space policy for the currently dispatched native call.
    current_user_memory: SyscallUserMemory,
    /// Client process whose LPC request the current server thread is servicing. The generic receive
    /// path binds this to the worker until it replies, allowing object services to resolve
    /// client-owned handles without an image-specific transport.
    current_server_client_pid: u32,
    /// Promoted acquisition whose retained route replaces process-handle lookup on retry.
    active_synchronous_file_retry: Option<nt_io_manager::SynchronousFileWaiter>,
    /// File lock acquired by this call; inline completion releases it at the dispatch boundary.
    current_synchronous_file_lock: u64,
    user_apc_redirected: bool,
    context_continue_redirected: bool,
    post_action: ExecPostAction,
    stop: bool,
    /// Monotonic fake-handle allocator for objects the executive doesn't model yet (ports, threads,
    /// events, sections, tokens, files). Persistent across smss + csrss (single source of truth —
    /// the remaining ladder cases reference `nt_handler.next_handle`). Migrated off the loop-local
    /// `next_handle` when the create-handle group moved onto the table (Workstream A, group A).
    next_handle: u64,
    /// Queued out-param writes (Workstream A group B2): out-writing query handlers (NtQuerySystemTime
    /// /PerformanceCounter/VolumeInformationFile) push `(ptr, value)` here instead of writing
    /// directly, because a csrss out-ptr can be an arbitrary VA that needs the loop's demand-fill
    /// bookkeeping (filled_pages/faults/scratch/reg/dll_pes/pml4). The dispatch loop drains this
    /// after `dispatch`, writing each via `csrss_out_write` (csrss) or `smss_stack_write` (smss).
    out_writes: [(u64, u64); 8],
    out_writes_n: usize,
    /// Raw refs to the loop's per-iteration state for group-C handlers (see [`ExecLoopCtx`]). Set
    /// by the Tier-1 dispatch arm before each `dispatch`; `None` outside the loop.
    loop_ctx: Option<ExecLoopCtx>,
    /// Hosted executable spawn reservation produced by the executable image state table. The loop
    /// consumes it after dispatch, builds the seL4 mechanism, then publishes or rolls back the
    /// reservation. This covers csrss/winlogon and later Win32 children.
    exe_spawn_request: Option<nt_exe_image::SpawnRequest>,
    /// Local hosted-thread mechanism request produced by NtCreateThread policy and consumed by the
    /// loop after dispatch. The handler owns NT policy (ETHREAD, TEB, handles, ClientId copyout);
    /// the loop owns seL4 TCB construction because it holds the target VSpace + fault endpoint.
    thread_spawn_request: Option<HostedThreadSpawnRequest>,
    /// Allocation-reserved generic LPC receive that the service loop must bind to the current reply
    /// object. The durable wait moves into `LPC_RECEIVE_WAITS`; no scalar state survives dispatch.
    lpc_receive_park: Option<PendingLpcReceivePark>,
    /// Allocation-reserved generic LPC connect that the service loop must bind to the current reply
    /// object. Completion is keyed only by the broker-authored connection id.
    lpc_connect_park: Option<PendingLpcConnectPark>,
    /// Accepted, refused, or disconnected connect outcome waiting for exact connector copyout.
    lpc_connect_completion: Option<PendingLpcConnectCompletion>,
    /// Allocation-reserved synchronous request keyed by broker-authored message identity.
    lpc_request_park: Option<PendingLpcRequestPark>,
    /// A reply was published to the LPC broker during this dispatch. The service loop consumes the
    /// edge once to redrive generic receive continuations without polling every parked port after
    /// every unrelated syscall.
    lpc_endpoint_progress: bool,
    /// ★ CROSS-VSPACE `NtCreateThread` (`RtlCreateUserThread(ProcessHandle != NtCurrentProcess)`):
    /// the handler did the POLICY (handle + `PROCESS_CREATE_THREAD` access check, the target's real
    /// ETHREAD, the `*ThreadHandle`/`*ClientId` out-params) and asks the LOOP to build the
    /// MECHANISM — the seL4 thread in the TARGET's VSpace — because only the loop holds the main
    /// fault endpoint the new thread must be badged onto. `None` = no request (every boot today).
    pub(crate) remote_thread_request: Option<RemoteThreadRequest>,
    /// Checkpoint B: set by NtWaitForSingleObject when the target is a real waitable object whose
    /// signal state is clear → the loop must PARK this caller (reply-cap park keyed by encoded
    /// WaitObject) instead of replying, and wake it on the matching state transition. -1 = no park.
    /// Reset each dispatch (group-A signal, like spawn_request).
    wait_park_event: i64,
    /// Alertability captured with the pending single-object wait handoff.
    wait_alertable: bool,
    /// Raw NT timeout interval for the pending wait-object park. The loop converts it into a
    /// monotonic deadline at the reply-cap park boundary, after any handler-side bookkeeping.
    wait_timeout: PendingWaitTimeout,
    /// Typed set captured by `NtWaitForMultipleObjects` for reply-cap parking.
    wait_capture_handles: [u64; WAITER_MAX_EVENTS],
    wait_park_objects: [WaitObject; WAITER_MAX_EVENTS],
    wait_park_result_indices: [u8; WAITER_MAX_EVENTS],
    wait_park_count: usize,
    wait_park_all: bool,
    /// `NtWaitForKeyedEvent` asks the loop to park this syscall on an arbitrary user-mode key.
    /// Finite waits reuse the shared delay timer.
    keyed_wait_key: u64,
    keyed_wait_timeout: PendingWaitTimeout,
    /// `NtReleaseKeyedEvent` uses the same rendezvous transport when no wait side is already parked.
    keyed_release_wait_key: u64,
    keyed_release_wait_timeout: PendingWaitTimeout,
    /// NtDelayExecution asks the service loop to park this syscall's reply until this signed
    /// 100ns interval becomes due. The handler validates/copies the user pointer; the loop owns
    /// deadline conversion and the HPET-backed reply-cap park.
    delay_requested: bool,
    delay_interval_100ns: i64,
    delay_alertable: bool,
    /// Blocking completion remove side signal. `-1` means no park request; nonnegative is the
    /// retained completion-port id to publish at the reply-cap park site.
    io_completion_park_port: i64,
    io_completion_key_out: u64,
    io_completion_apc_out: u64,
    io_completion_iosb_out: u64,
    io_completion_timeout: PendingWaitTimeout,
    /// Direct packet handoff selected by NtSetIoCompletion. The loop owns cross-process copyout and
    /// reply-cap wake, so the syscall handler only transfers this allocation-free pair.
    io_completion_wake: Option<(
        nt_io_completion::CompletionWaiter,
        nt_io_completion::CompletionPacket,
    )>,
    /// A synchronous file-I/O completion requested signaling this real executive event. The loop
    /// consumes it after dispatch so it can also wake reply-cap parked waiters.
    io_signal_event: i64,
    /// A pending general File IRP transferred into `PENDING_FILE_IO` after dispatch. The service
    /// loop attaches the live reply cap only when `pending_file_io_wait` says the native API or
    /// synchronous File object must wait for terminal completion.
    pending_file_io_transfer: Option<nt_io_manager::PendingFileIo>,
    pending_file_io_wait: bool,
    /// Exact pre-dispatch owner claim consumed only if the driver returns a pending IRP.
    pending_file_io_reservation: Option<nt_io_manager::PendingFileIoReservation>,
    /// Demand-start `NtLoadDriver` batches. The handler reserves a generation-exact slot before
    /// DriverEntry/AddDevice/START side effects, and the service loop attaches the live syscall
    /// Reply object only when an exact START IRP remains pending.
    pending_driver_loads: nt_driver_start::PendingDriverStartTable<PendingDriverStart>,
    boot_driver_start_reports: BootDriverStartReports,
    pending_driver_load_transfer: Option<(OwnedHostedPnpStartBatch, nt_driver_start::Reservation)>,
    /// Contended synchronous File acquisition transferred into the FIFO owner at the reply site.
    pending_synchronous_file_wait: Option<nt_io_manager::SynchronousFileWaiter>,
    /// Final-handle `NtClose` continuation reserved before removing the process handle. File Busy
    /// ordering and CLEANUP/CLOSE ownership remain in their canonical policy/manager tables.
    pending_file_cleanup_wait: Option<(u64, nt_io_manager::PendingFileCleanupWaitReservation)>,
    /// `NtCancelIoFile` continuation reserved before cancellation and transferred into its drain
    /// table only at the reply-capability park site.
    pending_file_irp_drain: Option<(
        nt_io_manager::PendingFileIrpDrain,
        nt_io_manager::PendingFileIrpDrainReservation,
    )>,
    /// ★ Dbgk TARGET-SIDE BLOCKING, SYSCALL flavour. Set by a debug-event post issued from a
    /// SYSCALL arm (`dbgk_module_load` — `DbgkMapViewOfSection`, which NT queues with flags 0 and
    /// therefore BLOCKS the mapping thread on the continue). The handler cannot park: the reply-cap
    /// steal needs the caller's resume_ip/sp/flags, known only at the reply site. The LOOP consumes
    /// this latch there, parks the caller as the event's blocked reporter and recvs the next event
    /// WITHOUT replying. `false` = no block requested — the plain-boot value, since the poster
    /// returns on its first line with no debug object alive.
    dbgk_block_request: bool,
    /// An npfs endpoint transition may have completed another retained read/transceive/listen IRP.
    /// The loop drains those exact driver completions; this latch never owns their publication.
    pipe_endpoint_progress: bool,
    /// Monotonic counter for anonymous (unnamed) event objects (rpcrt4's server_ready_event/mgr_event).
    /// Each anon event gets a unique synthetic name so no two dedup. See `obj_create_anon_event`.
    anon_event_seq: u32,
    /// Cursor over the CM-indexed PnP device-install event stream. `NtGetPlugPlayEvent` exposes the
    /// current devnode until umpnpmgr acknowledges it through `PlugPlayControlUserResponse`.
    pnp_event_cursor: usize,
    /// Dispatcher event used to park `NtGetPlugPlayEvent` callers once the CM-backed stream drains.
    /// Zero means the event has not been allocated yet.
    pnp_notify_event: u64,
    /// Runtime `DN_*` / `CM_PROB_*` status owned by PnP control calls. Devnode identity still comes
    /// from CM; this table only records mutable status overlays requested by umpnpmgr.
    pnp_status: PnpRuntimeStatusTable,
    lpc_connection_views: alloc::vec::Vec<PendingLpcConnectionViews>,
    /// The DATA-plane cache of established LPC connections (control/data-plane split): the isolated
    /// nt-lpc-server owns the namespace + rendezvous, but is NOT on the message path. When a CONNECT
    /// completes through the server, the executive records the connection here so the future message
    /// bulk (NtRequestWaitReplyPort/NtReplyWaitReceivePort/NtReplyPort) is served by DIRECT cross-
    /// badge delivery against this cache — never a per-message round-trip to the server. Records are
    /// `Copy` (inline name, no nested heap), and the vector owns any growth beyond its boot reserve.
    lpc_connections: alloc::vec::Vec<LpcConnRecord>,
    /// The real NT Process Manager (nt-process): EPROCESS/ETHREAD, per-process handle tables, and the
    /// process/thread lifecycle. FIRST convergence increment — each hosted process (smss/csrss/
    /// winlogon) is backed by a real EPROCESS created in `new()`. This increment only CREATES + LOOKS UP the
    /// EPROCESSes (read-only during the loop, so no runtime realloc). Policy lives here; the seL4
    /// VSpace/CSpace/TCB caps + mirror/scratch VAs stay executive-side because only the trusted root
    /// task holds those caps, linked to an EPROCESS through the process mechanism table.
    pm: nt_process::ProcessManager,
    /// Allocation-free hosted process mechanism slots keyed by NT PID/TID/badge. Backed by BSS;
    /// the handler owns only the exclusive wrapper while it is live.
    process_mechanisms: ExecProcessMechanisms,
    /// Loop-owned hosted process identity catalog. The handler stores a pointer instead of owning a
    /// second catalog so process identity, image open, and spawn all consult the same runtime table.
    hosted_images: *const nt_exe_image::OwnedHostedImageCatalog<HOSTED_PROCESS_IMAGE_CAP>,
    /// seL4 VSpace caps for hosted and temporary process slots, owned by the handler.
    process_vspaces: alloc::vec::Vec<u64>,
    /// Non-hosted throwaway processes used by post-quiesce self-tests. These slots deliberately do
    /// not enter `process_mechanisms`: they have no fault badge and are not launch topology.
    temporary_process_slots: alloc::vec::Vec<nt_process::ProcessId>,
    /// Allocation-free hosted main/pool ETHREAD identities. Backed by BSS to keep handler
    /// construction independent of table size.
    thread_mechanisms: ExecThreadMechanisms,
    /// Runtime occupancy mask for the pre-created ETHREAD pool of each hosted process.
    pool_used: alloc::vec::Vec<u64>,
    /// Hosted worker stack/TEB VA windows consumed in each process VSpace. Thread teardown releases
    /// the mapped frames/caps and clears the slot, so a later ETHREAD can reuse the same mechanism
    /// lane with fresh stack/TEB/IPCBUF/trampoline frames.
    tp_worker_window_used: alloc::vec::Vec<u64>,
    /// Executive-side seL4 mechanism runtime keyed by real NT TID. This is where live handler paths
    /// resolve TID -> TCB; the old TCB atomics are synchronized mirrors for global glue that has not
    /// been threaded through `ExecNtHandler` yet.
    thread_runtime: HostedThreadRuntimes,
    /// Session-scoped win32k state observed from provider-owned objects and reused only through
    /// explicit session/runtime lookup.
    win32k_session: Win32kSessionRuntime,
    /// Stable, reference-counted token objects. Each EPROCESS records its primary `TokenId`; token
    /// handles and ETHREAD impersonation contexts retain independent references and their storage.
    token_store: nt_security::TokenStore,
    /// The two security-subsystem-owned Anonymous Logon identities. Each syscall selects one by
    /// current LSA policy and retains a separate reference for the target ETHREAD.
    anonymous_logon_tokens: nt_security::AnonymousLogonTokenIds,
    /// Volatile registry write plane for keys that do not belong to a mounted mutable hive.
    /// Mounted hive paths use `mutable_hives`; this overlay remains for explicitly volatile state
    /// such as boot-created Control keys until D4 gives volatile keys first-class hive ownership.
    overlay: nt_hive_core::RegistryOverlay,
    /// Set by any handler that touched the writable filesystem. This schedules the service-loop
    /// ownership barrier so explicit durability requests can publish a volume snapshot before the
    /// corresponding success becomes externally visible.
    writable_fs_dirty: bool,
    /// Explicit writable-volume durability callers set this when user-visible success depends on a
    /// registry save/flush checkpoint reaching the snapshot reserve before the current syscall
    /// reply is sent. Ordinary file `NtFlushBuffersFile` calls validate and flush their concrete
    /// MemFs file object without forcing a whole-volume raw-reserve checkpoint in the hot syscall
    /// path.
    writable_fs_commit_required: bool,
}

const PENDING_DRIVER_LOAD_INITIAL_CAPACITY: usize = 8;

#[derive(Clone, Copy)]
struct BootDriverStartReportTarget {
    trace: HostedPnpStartTrace,
    pci: bool,
}

#[derive(Clone, Copy, Default)]
struct BootDriverStartReports {
    boot_service: HostedPnpStartReport,
    hardware_proof: HostedPnpStartReport,
    hardware_pci: HostedPnpStartReport,
}

impl BootDriverStartReports {
    fn merge(&mut self, target: BootDriverStartReportTarget, report: HostedPnpStartReport) {
        match target.trace {
            HostedPnpStartTrace::BootService => self.boot_service.merge(report),
            HostedPnpStartTrace::HardwareProof => {
                self.hardware_proof.merge(report);
                if target.pci {
                    self.hardware_pci.merge(report);
                }
            }
            HostedPnpStartTrace::DemandStart => {
                panic!("demand START cannot publish into a boot report")
            }
        }
    }
}

struct DriverStartBootstrap {
    pending: nt_driver_start::PendingDriverStartTable<PendingDriverStart>,
    reports: BootDriverStartReports,
}

impl DriverStartBootstrap {
    fn with_capacity(capacity: usize) -> Self {
        Self {
            pending: nt_driver_start::PendingDriverStartTable::with_capacity(capacity),
            reports: BootDriverStartReports::default(),
        }
    }
}

unsafe fn launch_boot_driver_service(
    fs: &Fat32,
    spec: &InlineDriverLaunchSpec,
    plan: &InlineDriverLaunchPlan,
    options: HostedPnpStartOptions,
    driver_starts: &mut DriverStartBootstrap,
) -> Option<(driver_launch::DriverComponent, HostedPnpStartReport)> {
    let target = BootDriverStartReportTarget {
        trace: options.trace,
        pci: inline_launch_spec_has_pci_devnode(plan.devnodes_for(spec)),
    };
    let prepared_start =
        if spec.class == driver_launch::DriverClass::Device && spec.devnode_count != 0 {
            let owned = match owned_driver_launch_spec_from_inline(spec, plan) {
                Some(owned) => owned,
                None => {
                    print_str(b"[driver-launch] boot START ownership allocation failed service=");
                    print_str(spec.service_name.as_bytes());
                    print_str(b"\n");
                    return None;
                }
            };
            let reservation = match driver_starts.pending.reserve() {
                Ok(reservation) => reservation,
                Err(_) => {
                    print_str(b"[driver-launch] boot START continuation reserve failed service=");
                    print_str(spec.service_name.as_bytes());
                    print_str(b"\n");
                    return None;
                }
            };
            Some((owned, reservation))
        } else {
            None
        };
    let Some(dc) = load_driver(
        fs,
        spec.image_path.as_bytes(),
        spec.class,
        spec.driver_object_path.as_str(),
    ) else {
        if let Some((_, reservation)) = prepared_start {
            driver_starts
                .pending
                .cancel(reservation)
                .expect("failed boot driver load lost its START reservation");
        }
        return None;
    };
    let Some((owned, reservation)) = prepared_start else {
        return Some((dc, HostedPnpStartReport::default()));
    };
    let mut batch = OwnedHostedPnpStartBatch::new(&dc, owned, options);
    let report = match batch.drive() {
        OwnedHostedPnpStartProgress::Complete(_) => {
            driver_starts
                .pending
                .cancel(reservation)
                .expect("synchronous boot START lost its continuation reservation");
            driver_starts.reports.merge(target, batch.report());
            batch.report()
        }
        OwnedHostedPnpStartProgress::AwaitingCompletion => {
            let report = batch.report();
            driver_starts
                .pending
                .publish(
                    reservation,
                    PendingDriverStart {
                        batch,
                        owner: PendingDriverStartOwner::Boot {
                            target,
                            report_published: false,
                        },
                    },
                )
                .expect("pending boot START rejected its pre-reserved owner");
            report
        }
        OwnedHostedPnpStartProgress::OwnershipLost(_) => {
            let report = batch.report();
            driver_starts.reports.merge(target, batch.report());
            driver_starts
                .pending
                .publish(
                    reservation,
                    PendingDriverStart {
                        batch,
                        owner: PendingDriverStartOwner::Boot {
                            target,
                            report_published: true,
                        },
                    },
                )
                .expect("indeterminate boot START rejected its barrier owner");
            report
        }
    };
    Some((dc, report))
}

fn report_deferred_generic_hardware_checks(
    report: HostedPnpStartReport,
    pci_report: HostedPnpStartReport,
    registry_selected: bool,
    selected: u64,
    root_selected: u64,
    pci_registry_selected: bool,
    pci_selected: u64,
    provider: driver_launch::HostedProviderSharingEvidence,
    passed: &mut u64,
) {
    print_str(b"[driver-launch] final config PnP summary selected=");
    print_u64(selected);
    print_str(b" attempted=");
    print_u64(report.attempted);
    print_str(b" add=");
    print_u64(report.add_device_count);
    print_str(b" started=");
    print_u64(report.started);
    print_str(b" terminal/failed/pending/pending-observed/indeterminate=");
    print_u64(report.terminal);
    print_str(b"/");
    print_u64(report.failed);
    print_str(b"/");
    print_u64(report.pending);
    print_str(b"/");
    print_u64(report.pending_observed);
    print_str(b"/");
    print_u64(report.indeterminate);
    print_str(b" first_error=0x");
    print_hex(report.first_error);
    print_str(b" first_indeterminate=0x");
    print_hex(report.first_indeterminate);
    print_str(b" pci_selected/attempted/started=");
    print_u64(pci_selected);
    print_str(b"/");
    print_u64(pci_report.attempted);
    print_str(b"/");
    print_u64(pci_report.started);
    print_str(b" root_selected/started=");
    print_u64(root_selected);
    print_str(b"/");
    print_u64(report.root_started_count);
    print_str(b"\n");

    check(
        b"exec_generic_hw_registry_selected",
        registry_selected
            && report.driver_ready_for_pnp
            && report.add_device
            && report.attempted == selected
            && report.add_device_count == selected,
        passed,
    );
    check(
        b"exec_generic_pnp_starts_terminal",
        report.attempted != 0
            && report.terminal == report.attempted
            && report.started + report.failed == report.terminal
            && report.pending == 0
            && report.indeterminate == 0
            && report.first_indeterminate == 0,
        passed,
    );
    check(
        b"exec_generic_pnp_pending_starts_observed",
        report.pending_observed >= 2,
        passed,
    );
    check(
        b"exec_generic_hw_mmio_interrupt_dma",
        report.resource_granted
            && report.mmio_mapped
            && report.interrupt_connected
            && report.dma_adapter
            && report.dma_common,
        passed,
    );
    check(
        b"exec_generic_hw_root_pdo_started",
        root_selected != 0
            && report.root_started_count == root_selected
            && report.start_ok
            && report.root_started,
        passed,
    );
    check(
        b"exec_generic_pci_registry_selected",
        pci_registry_selected && pci_selected != 0,
        passed,
    );
    check(
        b"exec_generic_pci_provider_domain_serviced",
        provider.provider_domain_bindings != 0
            && provider.provider_export_requests != 0
            && provider.provider_export_completions != 0
            && provider.provider_export_rejections == 0,
        passed,
    );
    let legacy_receive_ok = provider.provider_protocol_receive_requests != 0
        && provider.provider_protocol_receive_requests
            == provider.provider_protocol_receive_completions
        && provider.provider_protocol_receive_complete_requests != 0
        && provider.provider_protocol_receive_complete_requests
            == provider.provider_protocol_receive_complete_completions;
    let packet_receive_ok = provider.provider_protocol_receive_packet_requests != 0
        && provider.provider_protocol_receive_packet_requests
            == provider.provider_protocol_receive_packet_completions;
    let packet_array_receive_ok = provider.provider_packet_array_export_requests != 0
        && provider.provider_packet_array_export_requests
            == provider.provider_packet_array_export_completions
        && ((provider.provider_packet_array_protocol_receive_packet_requests != 0
            && provider.provider_packet_array_protocol_receive_packet_requests
                == provider.provider_packet_array_protocol_receive_packet_completions)
            || (provider.provider_packet_array_protocol_receive_requests != 0
                && provider.provider_packet_array_protocol_receive_requests
                    == provider.provider_packet_array_protocol_receive_completions));
    check(
        b"exec_provider_ndis_receive_indicated",
        legacy_receive_ok || packet_receive_ok || packet_array_receive_ok,
        passed,
    );
    check(
        b"exec_generic_pci_add_device_reached",
        pci_report.add_device && pci_selected != 0 && pci_report.add_device_count == pci_selected,
        passed,
    );
    check(
        b"exec_generic_pci_resource_accessed",
        pci_registry_selected
            && (pci_report.mmio_mapped
                || pci_report.io_port_out32
                || pci_report.interrupt_delivered
                || pci_report.dma_common
                || pci_report.dma_packet_descriptors
                || pci_report.dma_device_tx_completion_count != 0
                || pci_report.dma_device_rx_completion_count != 0
                || pci_report.dma_device_interrupt_cause_count != 0),
        passed,
    );
    check(
        b"exec_generic_hw_interrupt_delivered",
        report.interrupt_connected && report.interrupt_delivered && report.interrupt_acknowledged,
        passed,
    );
    check(
        b"exec_generic_hw_dpc_delivered",
        report.interrupt_delivered && report.dpc_delivered,
        passed,
    );
    check(
        b"exec_generic_hw_dma_packet_descriptors",
        report.dma_common && report.dma_packet_descriptors,
        passed,
    );
}

struct NativeDriverStartReply {
    tid: u64,
    badge: u64,
    reply_cap: u64,
    reply: nt_syscall_abi::ParkedSyscallReply,
}

enum PendingDriverStartOwner {
    Native(NativeDriverStartReply),
    Boot {
        target: BootDriverStartReportTarget,
        report_published: bool,
    },
    Detached,
}

struct PendingDriverStart {
    batch: OwnedHostedPnpStartBatch,
    owner: PendingDriverStartOwner,
}

static mut EXEC_NT_HANDLER_WORK: core::mem::MaybeUninit<ExecNtHandler> =
    core::mem::MaybeUninit::uninit();

#[inline(never)]
unsafe fn reset_exec_nt_handler(
    hosted_images: *const nt_exe_image::OwnedHostedImageCatalog<HOSTED_PROCESS_IMAGE_CAP>,
    driver_starts: DriverStartBootstrap,
    require_boot_system: bool,
) -> &'static mut ExecNtHandler {
    let slot = core::ptr::addr_of_mut!(EXEC_NT_HANDLER_WORK) as *mut ExecNtHandler;
    // SAFETY: `service_sec_image` is serialized and owns the returned exclusive borrow until the
    // service loop exits. Reinitializing this slot intentionally leaks the previous bump-heap-backed
    // contents, matching the rest of the rootserver bootstrap allocator model.
    ExecNtHandler::initialize_in(slot, hosted_images, driver_starts, require_boot_system)
}

