#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum ExecPostAction {
    None,
    ContinueCurrentThread {
        tid: u64,
        tcb: u64,
        registers: [u64; 20],
    },
    TerminateCurrentThread {
        tid: u64,
    },
    TerminateRemoteThread {
        tid: u64,
    },
    TerminateProcess {
        process_index: u8,
        current_tid: u64,
        drop_reply: bool,
    },
    CriticalTermination {
        code: u32,
        object: u64,
    },
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum HostedThreadRole {
    Main,
    TpWorker { slot: usize },
    ScmWorkerSlot { slot: usize },
    LsaWorkerSlot { slot: usize },
    CsrApi,
    CsrSbApi,
    WinlogonListener,
    WinlogonWorker { slot: usize },
    ServicesListener,
    LsassListener,
    LsassListener2,
    LsassListener3,
    DbgkSelftestTarget,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum HostedRpcWorkerKind {
    Scm,
    Lsa,
}

impl HostedRpcWorkerKind {
    const fn worker_role(self, slot: usize) -> HostedThreadRole {
        match self {
            Self::Scm => HostedThreadRole::ScmWorkerSlot { slot },
            Self::Lsa => HostedThreadRole::LsaWorkerSlot { slot },
        }
    }

    const fn trace_role(self) -> &'static [u8] {
        match self {
            Self::Scm => b"scm-rpc",
            Self::Lsa => b"lsa-rpc",
        }
    }
}

impl HostedThreadRole {
    const fn worker_window_slot(self) -> Option<usize> {
        match self {
            Self::TpWorker { slot }
            | Self::ScmWorkerSlot { slot }
            | Self::LsaWorkerSlot { slot } => Some(slot),
            Self::CsrApi => Some(0),
            Self::CsrSbApi => Some(1),
            _ => None,
        }
    }

    const fn rpc_worker_kind(self) -> Option<HostedRpcWorkerKind> {
        match self {
            Self::ScmWorkerSlot { .. } => Some(HostedRpcWorkerKind::Scm),
            Self::LsaWorkerSlot { .. } => Some(HostedRpcWorkerKind::Lsa),
            _ => None,
        }
    }

    const fn is_scm_rpc_worker(self) -> bool {
        matches!(self.rpc_worker_kind(), Some(HostedRpcWorkerKind::Scm))
    }

    const fn is_lsa_rpc_worker(self) -> bool {
        matches!(self.rpc_worker_kind(), Some(HostedRpcWorkerKind::Lsa))
    }
}

const fn hosted_thread_runtime_gate_bit(pi: usize, role: HostedThreadRole) -> u64 {
    const MAIN_THREAD_BASE: usize = 16;
    match (pi, role) {
        (pi, HostedThreadRole::Main) if pi < MAX_PI && pi + MAIN_THREAD_BASE < 64 => {
            1u64 << (MAIN_THREAD_BASE + pi)
        }
        (2, HostedThreadRole::WinlogonListener) => 1 << 0,
        (3, HostedThreadRole::ServicesListener) => 1 << 1,
        (4, HostedThreadRole::LsassListener) => 1 << 2,
        _ => 0,
    }
}

fn hosted_thread_runtime_gate_published(pi: usize, role: HostedThreadRole) -> bool {
    let bit = hosted_thread_runtime_gate_bit(pi, role);
    bit != 0 && (HOSTED_THREAD_RUNTIME_OK.load(Ordering::Relaxed) & bit) != 0
}

pub(crate) fn publish_hosted_thread_runtime_gate(pi: usize, role: HostedThreadRole) {
    let bit = hosted_thread_runtime_gate_bit(pi, role);
    if bit != 0 {
        HOSTED_THREAD_RUNTIME_OK.fetch_or(bit, Ordering::Relaxed);
    }
}

