struct HostedThreadRuntimeTable {
    entries: Vec<HostedThreadRuntime>,
    allocation_failures: u64,
    store_failures: u64,
}

impl HostedThreadRuntimeTable {
    const fn new() -> Self {
        Self {
            entries: Vec::new(),
            allocation_failures: 0,
            store_failures: 0,
        }
    }

    fn reset(&mut self, initial_reserve: usize) {
        self.entries.clear();
        if self.entries.capacity() < initial_reserve
            && self.entries.try_reserve(initial_reserve).is_err()
        {
            self.allocation_failures = self.allocation_failures.saturating_add(1);
        }
    }

    fn register(
        &mut self,
        pi: usize,
        tid: u64,
        tcb: u64,
        badge: u64,
        role: HostedThreadRole,
    ) -> Option<HostedThreadRuntime> {
        if tcb <= 1 {
            return None;
        }
        self.store(pi, tid, tcb, badge, role)
    }

    fn reserve(
        &mut self,
        pi: usize,
        tid: u64,
        badge: u64,
        role: HostedThreadRole,
    ) -> Option<HostedThreadRuntime> {
        self.store(pi, tid, 1, badge, role)
    }

    fn store(
        &mut self,
        pi: usize,
        tid: u64,
        tcb: u64,
        badge: u64,
        role: HostedThreadRole,
    ) -> Option<HostedThreadRuntime> {
        if tid == 0 || tcb == 0 {
            return None;
        }
        let mut runtime = HostedThreadRuntime {
            pi,
            tid,
            tcb,
            badge,
            role,
            mechanism: HostedThreadMechanismCaps::empty(),
            teb_alias: 0,
            user_stack_allocation_base: 0,
            user_stack_base: 0,
            lpc_server_port: 0,
            lpc_client_process: 0,
        };
        if let Some(existing) = self.entries.iter_mut().find(|entry| entry.tid == tid) {
            runtime.mechanism = existing.mechanism;
            runtime.teb_alias = existing.teb_alias;
            runtime.user_stack_allocation_base = existing.user_stack_allocation_base;
            runtime.user_stack_base = existing.user_stack_base;
            runtime.lpc_server_port = existing.lpc_server_port;
            runtime.lpc_client_process = existing.lpc_client_process;
            *existing = runtime;
            return Some(runtime);
        }
        if self
            .entries
            .iter()
            .any(|entry| entry.is_live() && entry.pi == pi && entry.role == role)
        {
            return None;
        }
        if let Some(empty) = self.entries.iter_mut().find(|entry| !entry.is_live()) {
            *empty = runtime;
            return Some(runtime);
        }
        if self.entries.len() == self.entries.capacity() && self.entries.try_reserve(1).is_err() {
            self.allocation_failures = self.allocation_failures.saturating_add(1);
            self.store_failures = self.store_failures.saturating_add(1);
            return None;
        }
        self.entries.push(runtime);
        Some(runtime)
    }

    fn stats(&self) -> (usize, usize, usize, u64, u64) {
        (
            self.entries.iter().filter(|entry| entry.is_live()).count(),
            self.entries.len(),
            self.entries.capacity(),
            self.allocation_failures,
            self.store_failures,
        )
    }

    fn get_by_tid(&self, tid: u64) -> Option<HostedThreadRuntime> {
        (tid != 0).then_some(())?;
        self.entries
            .iter()
            .copied()
            .find(|entry| entry.is_live() && entry.tid == tid)
    }

    fn set_user_stack(
        &mut self,
        tid: u64,
        allocation_base: u64,
        stack_base: u64,
    ) -> Option<HostedThreadRuntime> {
        if tid == 0 || allocation_base == 0 || stack_base <= allocation_base {
            return None;
        }
        let entry = self
            .entries
            .iter_mut()
            .find(|entry| entry.is_live() && entry.tid == tid)?;
        entry.user_stack_allocation_base = allocation_base;
        entry.user_stack_base = stack_base;
        Some(*entry)
    }

    fn set_mechanism_caps(
        &mut self,
        tid: u64,
        mechanism: HostedThreadMechanismCaps,
    ) -> Option<HostedThreadRuntime> {
        if tid == 0 || !mechanism.is_live() {
            return None;
        }
        let entry = self
            .entries
            .iter_mut()
            .find(|entry| entry.is_live() && entry.tid == tid)?;
        entry.mechanism = mechanism;
        Some(*entry)
    }

    fn set_teb_alias(&mut self, tid: u64, teb_alias: u64) -> Option<HostedThreadRuntime> {
        if tid == 0 || teb_alias == 0 {
            return None;
        }
        let entry = self
            .entries
            .iter_mut()
            .find(|entry| entry.is_live() && entry.tid == tid)?;
        entry.teb_alias = teb_alias;
        Some(*entry)
    }

    fn tcb_by_tid(&self, tid: u64) -> Option<u64> {
        self.get_by_tid(tid)
            .map(|entry| entry.tcb)
            .filter(|&tcb| tcb > 1)
    }

    fn main_for_pi(&self, pi: usize) -> Option<HostedThreadRuntime> {
        self.entries.iter().copied().find(|entry| {
            entry.is_live() && entry.pi == pi && matches!(entry.role, HostedThreadRole::Main)
        })
    }

    fn tcb_for_main_pi(&self, pi: usize) -> Option<u64> {
        self.main_for_pi(pi)
            .map(|entry| entry.tcb)
            .filter(|&tcb| tcb > 1)
    }

    fn get_by_role(&self, pi: usize, role: HostedThreadRole) -> Option<HostedThreadRuntime> {
        self.entries
            .iter()
            .copied()
            .find(|entry| entry.is_live() && entry.pi == pi && entry.role == role)
    }

    fn get_by_badge(&self, badge: u64) -> Option<HostedThreadRuntime> {
        self.entries
            .iter()
            .copied()
            .find(|entry| entry.is_live() && entry.badge == badge)
    }

    fn set_lpc_server_context(&mut self, badge: u64, port: u64, process: u32) -> bool {
        let Some(entry) = self
            .entries
            .iter_mut()
            .find(|entry| entry.is_live() && entry.badge == badge)
        else {
            return false;
        };
        entry.lpc_server_port = port;
        entry.lpc_client_process = process;
        true
    }

    fn tcb_for_role(&self, pi: usize, role: HostedThreadRole) -> Option<u64> {
        self.get_by_role(pi, role)
            .map(|entry| entry.tcb)
            .filter(|&tcb| tcb > 1)
    }

    fn release_tid(&mut self, tid: u64) -> Option<HostedThreadRuntime> {
        (tid != 0).then_some(())?;
        let entry = self
            .entries
            .iter_mut()
            .find(|entry| entry.is_live() && entry.tid == tid)?;
        let previous = *entry;
        *entry = HostedThreadRuntime::empty();
        Some(previous)
    }
}

static mut HOSTED_THREAD_RUNTIME_WORK: HostedThreadRuntimeTable = HostedThreadRuntimeTable::new();

/// Exclusive pointer to the serialized executive's hosted TID -> seL4 TCB table.
///
/// The table is deliberately not stored inline in `ExecNtHandler`; that handler is constructed on the
/// root task stack during the early SEC_IMAGE self-tests. The record store grows in the executive
/// heap and reuses released records.
struct HostedThreadRuntimes {
    table: *mut HostedThreadRuntimeTable,
}

impl HostedThreadRuntimes {
    fn reset() -> Self {
        let table = core::ptr::addr_of_mut!(HOSTED_THREAD_RUNTIME_WORK);
        // SAFETY: service_sec_image is serialized. A previous handler has been
        // dropped before a new one is constructed, so no other table reference exists.
        unsafe { (&mut *table).reset(HOSTED_THREAD_RUNTIME_INITIAL_RESERVE) };
        Self { table }
    }

    fn register(
        &mut self,
        pi: usize,
        tid: u64,
        tcb: u64,
        badge: u64,
        role: HostedThreadRole,
    ) -> Option<HostedThreadRuntime> {
        // SAFETY: this wrapper is the sole owner while its handler is live.
        unsafe { (&mut *self.table).register(pi, tid, tcb, badge, role) }
    }

    fn reserve(
        &mut self,
        pi: usize,
        tid: u64,
        badge: u64,
        role: HostedThreadRole,
    ) -> Option<HostedThreadRuntime> {
        // SAFETY: this wrapper is the sole owner while its handler is live.
        unsafe { (&mut *self.table).reserve(pi, tid, badge, role) }
    }

    fn set_lpc_server_context(&mut self, badge: u64, port: u64, process: u32) -> bool {
        // SAFETY: this wrapper is the sole owner while its handler is live.
        unsafe { (&mut *self.table).set_lpc_server_context(badge, port, process) }
    }

    fn get_by_tid(&self, tid: u64) -> Option<HostedThreadRuntime> {
        // SAFETY: shared access is bounded by the borrow of this sole-owner wrapper.
        unsafe { (&*self.table).get_by_tid(tid) }
    }

    fn set_user_stack(
        &mut self,
        tid: u64,
        allocation_base: u64,
        stack_base: u64,
    ) -> Option<HostedThreadRuntime> {
        // SAFETY: this wrapper is the sole owner while its handler is live.
        unsafe { (&mut *self.table).set_user_stack(tid, allocation_base, stack_base) }
    }

    fn set_mechanism_caps(
        &mut self,
        tid: u64,
        mechanism: HostedThreadMechanismCaps,
    ) -> Option<HostedThreadRuntime> {
        // SAFETY: this wrapper is the sole owner while its handler is live.
        unsafe { (&mut *self.table).set_mechanism_caps(tid, mechanism) }
    }

    fn set_teb_alias(&mut self, tid: u64, teb_alias: u64) -> Option<HostedThreadRuntime> {
        // SAFETY: this wrapper is the sole owner while its handler is live.
        unsafe { (&mut *self.table).set_teb_alias(tid, teb_alias) }
    }

    fn tcb_by_tid(&self, tid: u64) -> Option<u64> {
        // SAFETY: shared access is bounded by the borrow of this sole-owner wrapper.
        unsafe { (&*self.table).tcb_by_tid(tid) }
    }

    fn get_by_role(&self, pi: usize, role: HostedThreadRole) -> Option<HostedThreadRuntime> {
        // SAFETY: shared access is bounded by the borrow of this sole-owner wrapper.
        unsafe { (&*self.table).get_by_role(pi, role) }
    }

    fn get_by_badge(&self, badge: u64) -> Option<HostedThreadRuntime> {
        // SAFETY: shared access is bounded by the borrow of this sole-owner wrapper.
        unsafe { (&*self.table).get_by_badge(badge) }
    }

    fn tcb_for_main_pi(&self, pi: usize) -> Option<u64> {
        // SAFETY: shared access is bounded by the borrow of this sole-owner wrapper.
        unsafe { (&*self.table).tcb_for_main_pi(pi) }
    }

    fn tcb_for_role(&self, pi: usize, role: HostedThreadRole) -> Option<u64> {
        // SAFETY: shared access is bounded by the borrow of this sole-owner wrapper.
        unsafe { (&*self.table).tcb_for_role(pi, role) }
    }

    fn release_tid(&mut self, tid: u64) -> Option<HostedThreadRuntime> {
        // SAFETY: this wrapper is the sole owner while its handler is live.
        unsafe { (&mut *self.table).release_tid(tid) }
    }
}

fn hosted_thread_runtime_table_stats() -> (usize, usize, usize, u64, u64) {
    unsafe { (&*core::ptr::addr_of!(HOSTED_THREAD_RUNTIME_WORK)).stats() }
}

/// One established LPC connection cached executive-side (see
/// `ExecNtHandler::lpc_connections`). The isolated broker owns transport state; this bounded record
/// retains only the kernel-side process association and broker-authored connection metadata needed
/// to validate native service boundaries. `Copy`/inline storage survives the per-syscall bump reset.
#[derive(Clone, Copy)]
struct LpcConnRecord {
    /// The broker's connection id (ties back to the nt-lpc-server connection).
    connection_id: u64,
    /// The client comm-port handle handed to the connector.
    client_handle: u64,
    /// Which hosted process connected (0 = smss, 1 = csrss) — the connector badge for direct delivery.
    connector_pi: u8,
    /// Broker-authored connector identity used to validate request provenance.
    client_process: u64,
    client_thread: u64,
    /// Broker-owned limits inherited from the named connection port.
    limits: nt_port_core::PortLimits,
    /// QoS captured by the kernel before the broker connection was queued.
    security: nt_port_core::ConnectionSecurity,
    /// Reference-owning token copy captured at connect completion for static tracking.
    static_security: Option<LpcStaticSecurityContext>,
    /// Folded port name (inline; `\SmApiPort` etc. fit in 32 units).
    name: [u16; 32],
    name_len: u8,
}

#[derive(Clone, Copy)]
struct LpcStaticSecurityContext {
    token: nt_security::TokenId,
    effective_only: bool,
    level: nt_security::SecurityImpersonationLevel,
}

// ===================== ALPC last-mile item (a): register the NtAlpc* SSNs =========================
// SSNs EXTRACTED (not hardcoded — the rootserver-constant-drift trap) from references/ntdll.dll (a
// real Windows x64 ntdll, the Win7-pivot target; ReactOS ros-ntdll.dll, which the LIVE smss/csrss/
// winlogon run, exports NO NtAlpc* at all — ALPC is Vista+ and ReactOS has only kernel-less stubs).
//   NtAlpcAcceptConnectPort=111 NtAlpcConnectPort=113 NtAlpcCreatePort=114 NtAlpcCreatePortSection=115
//   NtAlpcCreateSectionView=117 NtAlpcDisconnectPort=123 NtAlpcSendWaitReceivePort=130
// ★ CONSTANT-DRIFT / COLLISION FINDING (load-bearing): the Win7 ALPC SSN block (111..131) OVERLAPS
// the live ReactOS SSN space — e.g. Win7 NtAlpcConnectPort=113 == the live ReactOS NtMapViewOfSection
// =113 (registered in build_nt_table). So the ALPC route MUST NOT be merged into build_nt_table nor
// fired on a raw m0 for the 3 live ReactOS processes (that would HIJACK live NtMapViewOfSection etc.).
// It is a DEDICATED recognizer, gated by ALPC-PROCESS IDENTITY (`ALPC_HOST_PRESENT`, never set at
// boot — no ALPC binary yet), so it is DORMANT (byte-identical boot) yet genuinely wired into the
// fault dispatcher. The recognizer + the SSN→adapter routing are proven by counted specs
// (exec_alpc_ssn_registered / exec_alpc_ssn_routes_to_adapter); a live hosted caller arrives with a
// real ALPC binary running the Win7 ntdll (whose ntdll then defines the authoritative SSNs).
pub const SSN_NT_ALPC_ACCEPT_CONNECT_PORT: u64 = 111;
pub const SSN_NT_ALPC_CONNECT_PORT: u64 = 113;
pub const SSN_NT_ALPC_CREATE_PORT: u64 = 114;
pub const SSN_NT_ALPC_CREATE_PORT_SECTION: u64 = 115;
pub const SSN_NT_ALPC_CREATE_SECTION_VIEW: u64 = 117;
pub const SSN_NT_ALPC_DISCONNECT_PORT: u64 = 123;
pub const SSN_NT_ALPC_SEND_WAIT_RECEIVE_PORT: u64 = 130;

/// Set true ONLY when a real ALPC binary (running the Win7 ntdll) is hosted. Never set at boot, so
/// `try_route_alpc_ssn` is dormant — the Win7 ALPC SSNs can never hijack the live ReactOS SSN space.
static ALPC_HOST_PRESENT: core::sync::atomic::AtomicBool =
    core::sync::atomic::AtomicBool::new(false);

/// Recognizer: map a Win7 `NtAlpc*` SSN to its unified port-service ALPC wire opcode (0x2300 block).
/// This IS the registration of the NtAlpc* SSNs in the executive's dispatch logic.
pub fn alpc_ssn_to_opcode(ssn: u64) -> Option<u16> {
    use nt_alpc_abi::opcode as aop;
    Some(match ssn {
        SSN_NT_ALPC_CREATE_PORT => aop::ALPC_OP_CREATE_PORT,
        SSN_NT_ALPC_CONNECT_PORT => aop::ALPC_OP_CONNECT_PORT,
        SSN_NT_ALPC_ACCEPT_CONNECT_PORT => aop::ALPC_OP_ACCEPT_CONNECT,
        SSN_NT_ALPC_SEND_WAIT_RECEIVE_PORT => aop::ALPC_OP_SEND_RECEIVE,
        SSN_NT_ALPC_DISCONNECT_PORT => aop::ALPC_OP_DISCONNECT_PORT,
        SSN_NT_ALPC_CREATE_PORT_SECTION => aop::ALPC_OP_CREATE_PORT_SECTION,
        SSN_NT_ALPC_CREATE_SECTION_VIEW => aop::ALPC_OP_CREATE_SECTION_VIEW,
        _ => return None,
    })
}

/// Fault-dispatcher hook: if a hosted ALPC process (running the Win7 ntdll) issued an `NtAlpc*`
/// syscall, translate its SSN → the ALPC adapter opcode and route it to the unified port service
/// over the shared ring (`LPC_CLIENT`), returning the NTSTATUS. DORMANT unless `ALPC_HOST_PRESENT`
/// (never set at boot) — so it can NEVER fire for the 3 live ReactOS processes whose SSN space
/// collides with the Win7 ALPC SSNs. The per-binary marshalling of the native ALPC arg blocks
/// (PORT_MESSAGE + ALPC_MESSAGE_ATTRIBUTES from the fault register/stack image) is the shim that
/// lands with a real ALPC binary; the recognizer + adapter routing here are proven by counted specs.
unsafe fn try_route_alpc_ssn(ssn: u64, req: &[u8], out: &mut [u8]) -> Option<u64> {
    if !ALPC_HOST_PRESENT.load(Ordering::Relaxed) {
        return None;
    }
    let op = alpc_ssn_to_opcode(ssn)?;
    #[allow(static_mut_refs)]
    let lpc = LPC_CLIENT.as_mut()?;
    let (status, _f, _i, _d0, _d1) = lpc.backend_mut().0.raw(op, req, out);
    Some(status as u64)
}

